/* 令和8年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r08.committeeSessions.push(...[{"id":"r08-20260629-8","meetingId":"r08-m0708","date":"2026年6月29日","dateIso":"2026-06-29","committee":"建設委員会","time":"午前１０時００分～午後３時２８分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を90件抜き出しています。","hasFullText":false,"topics":[{"id":"topic-01","title":"第６５号議案、 品川区手数料条例の一部を改正する条例","agenda":"第６５号議案、 品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"資料１の下段の、改正の主な内容の①のところで、今回、マンションを除却する手法が追加されたとのことですけれど、従来はどんな手法があって、それらの手法の実績というのはこれまでどれぐらいあったのかなというのをお伺いしたいのと、同じく、下段の③のところで、今回新たに高さ緩和の特例許可申請が加わったのですが、もともと容積率緩和の特例許可申請というのもあると思うのですが。","respondent":"川原住宅課長、森建築課長","answer":"私からは、①のマンション改正法の除却以外の手法や、あと、その実績についてのご質問にお答えをいたします。容積率緩和の特例許可の現在までの申請件数ですけれども、現在のところはございません。","voiceIndex":19,"id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問","question":"これは、マンションの管理適正法が改正になったことで、自治体の権限が大幅に強化をされたというところで、今後、この改正によって、立入検査、そして報告徴収、最終的には行政処分ということも可能になったということなのですけれども、本当に今現在なのですが、このマンション管理適正化法によって、その管理不全マンションの放置というのは、大体でいいのですけれども。","respondent":"川原住宅課長","answer":"ただ、一方で細かいその実態調査というところは、これから今年度、新規事業として、分譲マンション約１,８００棟を対象に、実地も含めて検査をいたしますので、 見回った上で新たに何か発生するといったことはもしかしたらあるかもしれないのですけれども。","voiceIndex":23,"id":"exchange-002"},{"speaker":"安藤委員","kind":"意見","question":"賛成です。資金がないなどの理由で建て替えに参加できない方への支援ですとか、例えば公営住宅への受入れ、家賃補助、法的な特別融資など、抜本的な様々な支援制度が必要なところではありますけれども、更新のためのこういう要件緩和自体は否定するものではございませんので、賛成します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":30,"id":"exchange-003"}]},{"id":"topic-02","title":"第６６号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正 する条例","agenda":"第６６号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正 する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"資料１で見ますと、Ａ地区で容積率７５０％、高さの最高限度が１４３.６ｍ、Ｂ地区、Ｄ地区で容積率が７００％、高さの最高限度が１４３.３ｍになっていますけれども、それぞれのもともとの容積率と高さの最高限度は幾らだったのか伺いたいのと、また、それがなぜ、このような、７５０％、 ７００％になったのか伺いたいと思います。","respondent":"森建築課長、中道都市開発課長","answer":"用途、高さ、現状がどうだったのかというところですけれども、山手通りの道路の端から ３０ｍ以内のところに用途の境がございまして、３０ｍ以内のところが容積率４００％、３０ｍを超えたところが容積率３００％です。その後に、有効空地などをそういった手引に基づいて評価をいたしまして、また、促進区の地区計画を使うことで、容積を適正に配分するということができますので、今回７５０％ または７００％といった容積になってあります。","voiceIndex":37,"id":"exchange-004"},{"speaker":"安藤委員","kind":"意見","question":"かなりの容積率の緩和ということで、促進区も使ったということもありましたけれども、やはり上位計画や行政が、こうした超高層ビルが林立するような地区計画を誘導しているということがよく分かりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":40,"id":"exchange-005"},{"speaker":"安藤委員","kind":"意見","question":"反対ですけれど、私は昨年１１月の都市計画審議会で、この超高層再開発の都市計画決定の審議では反対をしました。理由は、２割もの権利者の方が同意をしていない、協力開発企業が巨額の利益を上げる一方で、地権者の権利はないがしろにされている、地区計画など情報が秘匿されている、そして大崎駅の混雑を一層ひどくするなどの理由でした。その再開発の具体化の条例であるため、反対いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":45,"id":"exchange-006"},{"speaker":"おぎの委員","kind":"質問","question":"私のほうから幾つかお伺いしたいと思います。北品川三丁目その３の入札不調のところですが、入札不調の原因というものが、応札者がゼロだったのか、または価格面で不成立だったのか、こちらの内容と、あと、工事範囲等を見直して再度発注と、資料に書かれておりますが、こちらの今後のスケジュールが分かっていればお知らせください。","respondent":"関根河川下水道課長","answer":"今後の見通しにつきましては、資料でご説明をいたしました、資料の中の２番の工事概要のところにありますとおり、今年の１２月からおおむね１年間の工事の中で、今回入札不調になった範囲も含めて工事を実施していく予定としています。","voiceIndex":55,"id":"exchange-007"},{"speaker":"おぎの委員","kind":"質問","question":"技術者の配置困難ということで、今言われております建設業界の人手不足や物価高騰など、工事を受注しにくいという現実があるのかなと思います。こちらの北品川三丁目その３以外も、今あちこちでやっていると思いますが、そちらのほうは予定どおりに進んでいるのでしょうか。","respondent":"関根河川下水道課長","answer":"今年度につきましては、当初３件の工事を予定しておりまして、そのうち１件が本日ご説明させていただいた入札不調のあった案件です。残り２件につきましては、契約のほうは締結をいたしまして、現在、予定どおり工事のほうを進めている状況です。","voiceIndex":57,"id":"exchange-008"},{"speaker":"おぎの委員","kind":"意見","question":"その他は予定どおりということで、少し安心いたしました。もう一点、家庭用消火器あっせん販売の補助の件なのですが、こちら１点だけ、区民負担額自体は５,０００円から４,２００円に減るということでよかったと思いますが、あっせん価格自体は、こちらは７,８００円から９,８００円になっておりますが、こちらは消火器の物価高という認識でしょうか。","respondent":"遠藤防災体制整備担当課長","answer":"委員おっしゃった、昨今の物価高、上昇によって、今年度価格改定をするというところで、７月から価格改定でこのたびの価格に変更するです。","voiceIndex":59,"id":"exchange-009"},{"speaker":"安藤委員","kind":"確認","question":"家具転倒防止のほうですが、１００世帯という予算なのですけれども、その根拠を伺いたいのが１つです。感震ブレーカーは、表題に補助拡大とありますけれども、少し先ほどの説明でもあったような気もするのですが、確認なのですけれど、今回、この補助が拡大するということによって、分電盤型の非木造住宅の補助というのが拡大するという意味なのでしょうか、伺います。","respondent":"羽鳥防災課長、遠藤防災体制整備担当課長","answer":"今回補助を活用することで、さらに多くの方にご利用いただけるということを見込んで、切りのいいところで １００世帯とさせていただきました。感震ブレーカーの補助拡大についてのご認識といったところですが、委員おっしゃるとおり、 非木造住宅についても分電盤型の感震ブレーカーの補助を拡大するというところで実施をしたいと考えております。","voiceIndex":62,"id":"exchange-010"},{"speaker":"こんの委員","kind":"質問・要望","question":"それで、この非木造住宅に付随して、私も質問で少し挙げさせていただいたのですが、一般質問でもご答弁をいただいたところをいま一度確認したいのですが、非木造住宅の中には、いわゆるプレハブのおうちが今、すごく耐震がよくなって、構造もよくなっている、プレハブ的なおうちがありますけれども、それにも、たしか、対象になりますよという答弁をいただいたかと思いますが。","respondent":"羽鳥防災課長、遠藤防災体制整備担当課長","answer":"こちらは、 まず、区民の方が器具をご購入いただいて、その後、区のほうに補助金の申請をしていただいて、その後、区から交付決定をして、というスケジュールと、あと、また、区のほうから都に報告をして。２点ご質問をいただきました。１点、消火器のあっせん販売の補助とタイプの選択といったところについてですが、現在、区のほうで考えているのは、まず、粉末タイプの物で補助することを考えています。","voiceIndex":66,"id":"exchange-011"},{"speaker":"こんの委員","kind":"確認","question":"これも私、ノズルのついたという言い方だけでしてしまったのですが、いわゆる粉末タイプとスプレー式とありますと、それで、スプレー式は入らないのですかというお聞きをしたつもりだったのですが、今お答えはいただいて、いわゆる粉末式が基本だといったところなので、後でご答弁をいただけるというか、後ほどお聞きしたいところでは、そのスプレータイプも入れたらどうですかといったところです。","respondent":"羽鳥防災課長、遠藤防災体制整備担当課長","answer":"今年度の実施の状況を踏まえて、なるべく区民の皆様が長く購入期間を設けられるように、来年度のスケジュールのほうは検討していきたいと考えてあります。スプレー式の物も採用したらどうかといったご質問でした。一応こちらのほうにつきましても、予算等を鑑みながら、採用できるようであれば検討して進めていきたいと思いますので、よろしくお願いいたします。","voiceIndex":69,"id":"exchange-012"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"家具類転倒等防止器具のことでお尋ねなのですけれども、この２の事業内容の中の（６）その他のところで、これは高齢者地域支援課の事業も対象の助成になっていて、合わせて周知をするとなっておりますけれども、今まで、連携しているとは思うのですが、改めて、この高齢者地域支援課がやっている事業の助成の場合というか、要するに、取付けは多分、人材をシルバーセンターにお願いをしていると思うので。","respondent":"羽鳥防災課長","answer":"今回、防災課のほうで新たな補助を始めますので、例えば高齢者の方が防災課のほうの補助で購入されるということの申請がありましたら、高齢者地域支援課の事業のほうをしっかりご案内するということもそうですし、あと、高齢者地域支援課の事業のほうでも。","voiceIndex":73,"id":"exchange-013"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ、連携して周知を図っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-014"},{"speaker":"えのした副委員長","kind":"確認","question":"私からも何点か少し確認をします。消火器の件で、以前私もこれを質問させていただいたのですけれども、街頭消火器の中身の種類、内容が違うということで、これは電気火災の対応になっている種類なのか、あっせんの消火器の種類についてお知らせください。","respondent":"遠藤防災体制整備担当課長","answer":"街頭消火器の薬剤の種類ということでよろしいですか。","voiceIndex":77,"id":"exchange-015"},{"speaker":"えのした副委員長","kind":"質問","question":"種類はそのときに質問したのですけれども、今回のあっせん販売する消火器は、ノズル式、粉末式と言っていましたが、それというのは電気火災にも対応するような種類になっているのでしょうか。","respondent":"遠藤防災体制整備担当課長","answer":"大変失礼しました。今回の、あっせん販売する粉末タイプに関しましては、電気火災にも対応している物となっています。","voiceIndex":79,"id":"exchange-016"},{"speaker":"えのした副委員長","kind":"確認","question":"確認が取れました。安心して、こちらは電気火災に対応するということで確認させていただきました。","respondent":"遠藤防災体制整備担当課長","answer":"漏電遮断機能がついているものであれば、場合によっては、ケース・バイ・ケースなのですけれども、外づけの接続タイプであったり、また、交換するものであったりと、現場、ご自宅の設置状況によって、随分タイプが異なるといったところなので、まずは調査をして。","voiceIndex":81,"id":"exchange-017"},{"speaker":"えのした副委員長","kind":"質問・要望","question":"古いものでも交換ができるということで、これはかなり在宅避難、今、区民の方、マンションにお住まいの方が８割以上と言われているので、大変助かると思うのですが、なかなかこれは分かりづらいと思うのです。なので、ぜひ周知の際には分かりやすく、こういった図も示したりしながら周知をしていただければと、こちらは要望です。","respondent":"遠藤防災体制整備担当課長","answer":"先ほど、こんの委員のご質問の中で、私、スプレータイプの物について検討しますという答弁させていただいたのですけれども、今回取り扱う物は全てノズルの消火器といったところになりますので、そちらのほうだけご理解していただければと思いますので、よろしくお願いいたします。","voiceIndex":83,"id":"exchange-018"}]},{"id":"topic-03","title":"令和８年請願第５号、リニア中央新幹線工事再開に対し 再度住民説明会を求める請願","agenda":"令和８年請願第５号、リニア中央新幹線工事再開に対し 再度住民説明会を求める請願","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"これから審査するということですので、やはり審査の中身にも関わってくることですので、ぜひご希望があれば冒頭からでも意見陳述を受け付けるべきだと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":95,"id":"exchange-019"},{"speaker":"こんの委員","kind":"意見","question":"質疑終了後で取扱いを決めるでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":100,"id":"exchange-020"},{"speaker":"おぎの委員","kind":"質問","question":"実際、こちらの説明会、２日間かけて行っておりますが、どういった形で行われていたのかということと、あと、参加された方からもし感想等をお聞きになっているようでありましたら、どういった声が出ていたのかというのを併せてお聞かせいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":107,"id":"exchange-021"},{"speaker":"おぎの委員","kind":"確認","question":"オープンハウス型でもそういったご意見があったということは確認いたしました。もう一点なのですが、補償についてお伺いしたいと思います。こういった工事がありますと、 本当に住民の方の心配の根底には、地盤であったり家屋の損壊や生活への支障などの心配をされていると思いますが、万が一といったときは、必ずそういったものは何らかの補償の確認等はしっかりとされているのでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"ＪＲ東海のほうからは、工事の実施前に、事前の家屋調査というものを、範囲を定めて地域の皆様にお知らせをして、希望される方がいれば当然その調査をして、もし万が一、そういった補償をせざるを得なくなった事態に陥った際は。","voiceIndex":110,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回リニア中央新幹線工事再開に対し再度住民説明会を求める請願ということで、 １,２１４名の方から署名が集まっているということなのですけれど、これは期日の中で出された数なのですが、その後、追加で出された署名などの数が分かれば教えていただきたいと思います。いかがでしょうか。","respondent":"あくつ委員長、大石まちづくり立体化担当課長","answer":"最初の追加署名のところにつきましては、当委員会としての回答をさせていただければと思いますけれども、６月２５日段階で、先ほど書記からもご説明あったとおり、５名の追加署名がございました。区といたしまして、個別に聞いているというものは、先ほど申したとおり、ＪＲ東海としての説明責任についてどう考えているのか、もう一点ですと、事故原因の調査が不足している、こういったご意見があったとは聞いているところです。","voiceIndex":113,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり、都合がいい声しか載せていないということですよね。それで、次の質問に行くのですけれども、４月２２日に掘進が再開されたということなのですが、それ以後、工事による住民からの通報や問合せなどはあったのでしょうか。品川区内をこのトンネルが通るわけですけれども、 そのトンネル沿線の地元地域や、その町会などから、品川区長に対してはどのような要望が出ているのか伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"４月２２日の掘進再開以降、区民からのどのような通報や問合せがあるかですけれども、今現状、把握しているものといたしましては、件数としては３件ございまして、内容といたしましては、まず、申入れしたことに感謝しますというのもお褒めの言葉をいただいたものや。","voiceIndex":116,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"地元といっても旗の台のほうなのですけれども、荏原第四地域センターのほうに届いていると区も承知しているかと思うのですが、区政協力委員会への要望書ということで、旗の台４丁目町会から提出されております。これは、数えると１０もの町会長が再度、説明会を求めていると。これをＪＲ東海に求めてほしいという、この求めを区としてはどういうふうに受け止めているのか伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"ご要望の詳細が分かり次第、区としてもＪＲ東海に改めてお声を届けてまいります。なお、ＪＲ東海からは、 今後も掘進時期に合わせて順次、オープンハウス型の説明会は開催する予定と聞いているところでございます。","voiceIndex":121,"id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"そんなのは当然なことであって、今すぐ一斉説明型の説明会を開いてほしいということが住民の望みなわけです。それで、所管として把握していないということなのですけれども、内容を把握していないということだと思うのですが、こういう要望書が届いているという事実自体は、所管としても把握しているということでよろしいのか確認させてください。","respondent":"大石まちづくり立体化担当課長","answer":"詳細について把握していないと申し述べましたのは、お問合せのお電話があった際に、旗の台四丁目の方だと思われるのですけれども、その方から区政協力委員会でそういったご要望を出すというお話を聞いてはいますが、すみません、実際に。","voiceIndex":123,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。ぜひ、区として改めて、具体的に、この一斉説明型の説明会の開催というのを求めていただきたいのですけれども、これだけの１,２００人を超す署名、そして、地元を中心とした旗の台等からの１０もの町会長からも要望していることですから、改めて説明会の開催というのを求めていただきたいのですけれど、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"区といたしましては、 ＪＲ東海のほうが十分な説明をするなど責任を持って対応すべきものと考えているため、公表した４月 １７日の申入れにおいても、様々な方法により、区民への丁寧な説明を行うよう求めてきております。","voiceIndex":125,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"重く受け止めているということもありましたけれども、こういった請願が出され、旗の台のほうからもこういった強い要望が出たという中で、４月の掘進再開の際に行った申入れとは別に、改めてこうした状況を受けて、申し入れてほしいのですけれど、文言については、私は教室型説明会を早急に再び開いてほしいということがいいと思うのですが、とにもかくにも、もう一度この時点で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":127,"id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"その詳細を把握していただいて、重く受け止めていただいて、改めて、要望を出すよう強く求めたいと思います。ただ、今回の請願は、区議会に対しても、ＪＲ東海に再度の一斉説明型の説明会の開催を求めるよう求めているものです。私としては、 もう当然ですけれど、当然の要望なので、求めるべきだと思っているわけですが、これは実は議会も問われているということになるのです。いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-029"},{"speaker":"こんの委員","kind":"確認","question":"今の質疑で確認させていただいた部分もありましたので、意見陳述は結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":134,"id":"exchange-030"},{"speaker":"安藤委員","kind":"意見","question":"そもそも、私とおぎの委員しかしゃべっていないのに深まっているのかという問題がありますし、あと、やはりこの当事者の声を聞くというのが、かなり大事なことだと思いますし、議会としては、請願者の思いを聞いて審査をするというのは、私は当然そうあるべき議会だと思いますので、聞いていく必要があると思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":135,"id":"exchange-031"},{"speaker":"おぎの委員","kind":"質問・要望","question":"本日結論を出すでお願いいたします。説明会というものは非常に重要になってくると思います。先ほど、 オープン型のほうが分かりやすかったといった意見もありますので、品川区としては、しっかりとこの工事の進捗によって適時説明会をＪＲ東海に行っていただくように、引き続き強く要望していただきたいとお願いをしまして、今回の一斉説明型の説明会という部分に関しまして、会派としては、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":139,"id":"exchange-032"},{"speaker":"えのした副委員長","kind":"確認","question":"本日結論を出すで、不採択にします。理事者のご答弁から、しっかりと区では、区民への丁寧な説明を、文書での再発防止も含めて申入れをしていますし、先ほどもお話ありましたけれども、オープンハウス型のほうがより分かりやすかった、今後もＪＲ東海は、そういった説明会をしていくということで確認が取れました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":140,"id":"exchange-033"},{"speaker":"こんの委員","kind":"提案","question":"本日結論を出すでお願いいたします。そうなると、住民の方の不安払拭というところにはなかなか対応が難しいのかなというところもある。ですので、要は、より一層の丁寧な説明と対応ということが重要なことは当然ですので、住民にとって効率よく十分な対応、これが取れるように、今後も区としては求めていただきたい、このことを要望しまして、今請願につきましては不採択とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":142,"id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"採択を主張したいのですが、住民の方々が、今、工事がもう既に目の前で行われている中、一刻を争って、再度の教室型、一斉説明型の説明会を求めるというのは、本当に何ら不思議がないことだと思います。当然の要求だなと思います。ぜひ、今、不採択と表明された会派の皆さんもいますけれども、今からでも考え直してほしいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-035"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今度、秋の区政協力委員会のときに、この要望書が、もう出されたのかまだ定かではないですけれども、これは議題として、北品川工区については議題に上がるようなことも私もお聞きしておりますので、私も、この調査対象地区の家屋に入っております。中には、 旗の台三丁目には旗岡八幡神社もあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":144,"id":"exchange-036"},{"speaker":"安藤委員","kind":"質問・要望","question":"４つありますので、どうしましょうかという感じですが、まず、陳情第２０号を審査する上で少し伺いたいのですが、小山三丁目第１地区において、再開発組合の設立を決めた準備組合の総会、この議決が規約に基づき行われていなかった、その文書が公にされていない、などの手続上の不備があると陳情第２０号には書かれているのですけれども、これはなかなか分かりづらいと思うのですが、どういうことなのか。","respondent":"中道都市開発課長","answer":"先ほど、安藤委員のほうから、いわゆる都市計画決定の前に、そういったものを近隣説明会の中で報告したほうがいいのではないかというようなご提案がございましたけれども、いわゆる都市計画決定の前というのは。","voiceIndex":154,"id":"exchange-037"},{"speaker":"安藤委員","kind":"質問","question":"この変更に当たって、区とか行政というのはどういう関与などをしているのか、そこら辺も伺いたいと思います。伺いたいのは、そもそもこの小山三丁目第１地区の組合員数というのは何人になっているのか伺いたいと思いますし、少しくどいですけれど、そもそも総会が成立していなければ、その議決というのも当然無効になると思うのですが、いかがでしょうか。","respondent":"中道都市開発課長","answer":"そこについて弁護士に相談したところ、弁護士とも問題がないというような回答を得ているというところは、区のほうに報告が来ているところです。","voiceIndex":156,"id":"exchange-038"},{"speaker":"安藤委員","kind":"質問","question":"それで、不安や疑問が上がっているのですが、資料にあるところ、従前資産額というところで、土地価格というところが約 ４０％の上昇を想定と記載されている一方で、建物価格というのは概略権利変換時の数値で試算と書いているのですけれど、その部分が不当にマンション区分所有者の従前資産を低く見積もっているのではないかと思ってしまうところなのですが。","respondent":"中道都市開発課長","answer":"総会の開催の件ですけれども、考え方というかその捉え方はいろいろとあるのかなとは思っていますが、いわゆる準備組合の様々な品川区で行われていますほかの再開発でも、おおむね考え方といいますと、いわゆる都市再開発法にのっとってマンション区分を持っている方を１と考えて。","voiceIndex":159,"id":"exchange-039"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと併せて、陳情第２３号なのですけれど、陳情の６ページの下から２つ目の段落辺りで、詳しい説明を求めたいとあるので、規制緩和で登記行為まで省略された無登記の再開発組合に地権者所有土地建物をなぜ権利変換しなければならないのか、詳しい説明を行政担当者に求めたいとありますので、こちらをご答弁いただければと思います。最後、もう一つ言ってしまいます。","respondent":"中道都市開発課長","answer":"ですので、こういった形で組合が設立、事業が認可されたというところは、市街地再開発事業が認可されたということで交付対象となるですので、その中で、組合がそういった申請書を出されれば、それは交付すべきものという認識です。","voiceIndex":161,"id":"exchange-040"},{"speaker":"安藤委員","kind":"意見","question":"やはり、とりわけ陳情者の方も書いていますけれども、今後、そういった分譲マンションがたくさんあるようなところで超高層再開発を進めていくということが本当にいいのかと、私は見直すべきだなと思います。これは意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":163,"id":"exchange-041"},{"speaker":"おぎの委員","kind":"質問・要望","question":"安藤委員のほうから大分聞いていただきましたので、私のほうから２点だけお聞かせください。地権者住民の要望を無視しているということで、個人的にも、森澤区長もおっしゃっています、まちづくりの主体はそこに住む人たちだということ、私も同意見です。先ほど８４％という数字となっておりましたが、実際住民の方の要望というのは、その辺をもう少し詳しくお聞かせいただけたらと思います。そちら１点です。","respondent":"中道都市開発課長","answer":"もう一つ、やはり商店街の活力という意味で、今後１００年、商店街を継続させていかなければいけないという声もいただいてあります。ですので、こういった再開発の中で商店街を魅力あるものにしていきたいというような声も非常に多く上がってあります。","voiceIndex":165,"id":"exchange-042"},{"speaker":"おぎの委員","kind":"質問・要望","question":"本日結論を出すでお願いいたします。現時点では、弁護士にも確認しており、手続上に不備がなかったと、現時点ではそうなっておりますので、今回この陳情に関しましては、不採択といたしたいと思いますが、でも、再開発はやはり、生活が再開発によって大きく変わる方もいらっしゃいますので、相談窓口設置など不安な気持ちに寄り添うように引き続き、区としても適宜介入して求めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":168,"id":"exchange-043"},{"speaker":"えのした副委員長","kind":"質問","question":"本日、結論を出すで不採択でお願いします。理事者のご答弁からも、規約に沿って運営されている、また、弁護士の方も問題がないと回答していると、区として報告を受けているということで、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":169,"id":"exchange-044"},{"speaker":"こんの委員","kind":"確認","question":"本日結論を出すでお願いいたします。今、陳情第２０号の採決ですけれども、ほか３件についても同じような態度表明になりますので、まず、そのことをお伝えしたいと思います。陳情者の疑問だとか不安だとか、ご意見、主張、こうした出されたものに対して理解しないわけではありませんけれども、これまでの会議録を確認してきました。確認もさせていただきました。ですので、本陳情については不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":171,"id":"exchange-045"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、趣旨採択でお願いしたいのですが、手続の不備は、私は明らかだと言わざるを得ないと思います。ただ、それぞれの委員の見解も明らかにすべきだと思いますし、陳情者の気持ちも分かるのですけれども、それぞれの委員がどのような意思表示を行うかの自由は保障されるべきだとは思いますので、趣旨採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":172,"id":"exchange-046"},{"speaker":"おぎの委員","kind":"質問・要望","question":"本日結論を出すでお願いいたします。状況に応じて資金計画の確認はしっかりと今後も行っていただきたい、ここの点は要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":177,"id":"exchange-047"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、採択を主張したいのですが、やはり再開発への補助金の支出額というのは、私は予定額も含めて早期に議会や住民に明らかにすべきであると思いますので、採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":180,"id":"exchange-048"},{"speaker":"おぎの委員","kind":"質問・要望","question":"本日結論を出すでお願いいたします。住民の方からの要望といったところで、防災であったりとか、また、商店街の活力であったりとか、 そういった希望なども多く出ているということを確認させていただきました。皆さんでしっかりと再開発は考えていくものだと思います。今回は、こちらは不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":185,"id":"exchange-049"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、趣旨採択なのですけれど、開発企業の利益が動機の超高層再開発を、行政も便宜も図ってマンション区分所有者、独り暮らし高齢者をはじめ、弱小権利者を置き去りにして推進してきたことに対する怒りが陳情全体から伝わってまいります。気持ちは本当によく分かるので、この趣旨を酌み取って趣旨採択ということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":188,"id":"exchange-050"},{"speaker":"おぎの委員","kind":"質問・要望","question":"本日結論を出すでお願いいたします。個人的な要望なのですけれども、こういったタワーマンションはすごく、投機マネーというのでしょうか、そういったもので非常に値段が都内も本当に上がっておりますので、千代田区のように再開発事業に行政支援を行う一方で、過度な住宅価格高騰が起きないように、要請を出すなり、ほか、何らかの方法も併せて考えていただきたいなと思います。最後は要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":193,"id":"exchange-051"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、趣旨採択でお願いしたいのですが、現時点において区の判断で１円も補助金を出さないということは難しいかもしれませんけれども、そもそも巨額な税金を使うべきではない事業だということには私は変わりないと思いますし、気持ちは十分分かりますので、趣旨採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":196,"id":"exchange-052"}]},{"id":"topic-04","title":"号、品川浦周辺地区まちづくりガイドライン策定に関して現状等を住民 に説明・質疑応答する会と対象地域から除外を希望する住民の希望調べの実施と次回の意見交換会","agenda":"号、品川浦周辺地区まちづくりガイドライン策定に関して現状等を住民 に説明・質疑応答する会と対象地域から除外を希望する住民の希望調べの実施と次回の意見交換会","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"陳情の本文のほうから伺っていきたいのですが、２ページの辺りから、今住んでいる住民をどかせて新しいまちをつくらないといけないのか、なぜそれを上位計画に縛られないといけないのか、本当に分かりませんと。私たちの住む家は、個々に住む権利や財産としてあるものではないでしょうかと。そのような陳情者の当然の要求はどうしたらかなえられるのか、伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"事業に対するご不安やご懸念の声を、まずは区といたしましては真摯に受け止めているところです。区といたしましては、いただいたご意見等を準備組合に届けるとともに、丁寧な対応を行うよう準備組合に伝えてまいりたいと考えているところです。","voiceIndex":206,"id":"exchange-053"},{"speaker":"安藤委員","kind":"質問","question":"再開発準備組合が設立されているという前提で、この話が進んでいるというか、それでは私は、住み続けたいという方の住み続けられるという要求はかなわないのではないかと思うのです。準備組合に届けますということですけれども、結果的にそこに住み続けたいという方が住み続けられなくても、まちづくりのためには仕方ないという認識なのでしょうか、伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"先ほどご答弁申し上げたのはそういった趣旨ではなく、まちづくりにつきましては、地域の皆さんで話し合いながら進めていくことが重要と考えています。","voiceIndex":208,"id":"exchange-054"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いたいのですが、品川浦周辺地区内の区分所有者権利者が住む分譲マンションのそれぞれの地区での棟数と戸数、また、品川浦周辺地区では、準備組合の加入はマンションごとになっているのか、それとも区分所有者それぞれ個人が加入することになっているのか、午前中の武蔵小山の質疑もありましたけれども、この地区ではどうなっているのか伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"周辺地区内の区分所有者のマンションの棟数と戸数という関係のご質問です。北地区につきましては、７棟で全部で４３２戸、西地区につきましては、６棟で３１８戸、南地区につきましては、２棟で１２３戸、三丁目北地区につきましては、３棟で１４０戸と聞いてあります。","voiceIndex":210,"id":"exchange-055"},{"speaker":"安藤委員","kind":"質問","question":"伺いますけれども、したがって、先ほどのマンションの軒数の件も併せて、陳情にあるように、準備組合は住民の一部にすぎないと。しかも、再開発を進めたい方々の集まりだけであって、地区内住民の代表とは到底言えないと思うのですけれども、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"準備組合に対しましては、より多くの方によりましてまちづくりの検討がなされるよう、準備組合に加入されていない方に対しても丁寧な説明を行うよう、繰り返し求めております。","voiceIndex":212,"id":"exchange-056"},{"speaker":"安藤委員","kind":"質問","question":"ニュースには、３月に３地区の理事長とともに、準備組合事務局が区に補助金の件を含め相談に行ったとありますが、どのような話合いだったのか、時間はどれぐらい話し合ったのか、伺いたいと思います。あわせて、陳情の中で紹介されています、来た準備組合に対して区が言ったという、まちづくりの進展に合わせて必要な対応を図るというのはどういう意味なのか、伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"そのような方たちに対しても丁寧な説明と対応を行って、 理解と協力をいただくことが必要と考えている。まちづくり検討を行っていく上で、より多くの方が準備組合に参加し議論することが非常に重要であるとお伝えしました。","voiceIndex":214,"id":"exchange-057"},{"speaker":"安藤委員","kind":"確認","question":"今、 答弁もありましたが、伺いますけれども、再開発準備組合ニュースにある、姿勢に変わりがないことは確認済みであるというのはどういう意味なのでしょうか。国が補助金を出さない地域にしたにもかかわらず、区は補助金を出せる状況をつくるために動くという意味なのでしょうか。現時点ではという話もありましたけれども、本会議等での答弁から立場が変わったということなのか、もう一度伺います。","respondent":"大石まちづくり立体化担当課長","answer":"このため、今後のまちづくりの機運や地域からの声、関係機関との協議状況等によっては、総合的に考える必要が生じるものと考えておりますが、 現時点におきましては、補助金に対する考え方に変更はございません。","voiceIndex":216,"id":"exchange-058"},{"speaker":"安藤委員","kind":"質問・要望","question":"超高層再開発というのは、これまで繰り返したように様々問題点があるのです。冒頭の説明ではこの陳情項目に対してのお答えがなかったので、 私としても設けていただきたいと思いますが、いかがでしょうか。そして、最後の段落というか、①のところの「特に」以降なのですけれども、違いがあれば、その相違点を教えていただきたいとありますので、ぜひこちらを教えていただきたいのですが、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"当該地区につきましては、先ほど申したとおり、西地区の一部を除いて交付対象外の地区に令和９年度以降なりますが、これによって市街地再開発の事業の実施有無に影響を与えるものではないと考えているところです。","voiceIndex":218,"id":"exchange-059"},{"speaker":"安藤委員","kind":"質問・要望","question":"なので、今回出されているような、再開発も含めて質疑応答できる場をつくってもらいたいということですので、ぜひ意見交換会の場をそういう場にしてほしいと思うのですけれども、再度いかがでしょうか。住民が再開発によって悩まされているわけですから、②にあるように、区として対象地域から除外を希望する希望調査というのは、私は行うべきだと思うのですけれども、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"その範囲につきましては、まずは地域の中で議論されることが重要と考えています。このため、区といたしましては、個別に調査の実施は考えてございませんが、いただいたご意見については準備組合に届けてまいります。","voiceIndex":220,"id":"exchange-060"},{"speaker":"安藤委員","kind":"質問・要望","question":"もう一度その辺りについて、改めてそういった点から、少なくとも再開発というのを話題のテーマにも入れてほしい。アンケートについても書かれておりますが、陳情にあるような点、偏りがない、誘導がないものにしてくださいということですとか、自由記述もありで、閲覧も可能なものにしてくださいという要望が書かれておりますが、こちらについても、こういった意見をどう反映するのか伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"２点目の陳情項目③のところですが、まず、詳細につきましては今後の検討になります。いただいたご意見も踏まえまして、どのような開催方法やアンケートの記載方法がよろしいかというのは、 今後検討してまいりたいと考えているところです。","voiceIndex":222,"id":"exchange-061"},{"speaker":"おぎの委員","kind":"質問","question":"どうしても再開発というと、イコールタワーマンションとか、そういうイメージも出てきてしまうのですが、そもそもの意見交換会の趣旨としては、地域全体の魅力であったり防災や景観について、みんなでまずは話し合うという認識でよろしいでしょうかということをお聞かせください。","respondent":"大石まちづくり立体化担当課長","answer":"意見交換会の趣旨といたしましては、委員ご指摘のとおり、再開発とは切り離して、今まちづくりの検討が行われている地区に対して、準備組合の中で話し合っている将来像とは別に、区が考えるものや、 例えば準備組合に加入されていない方たちの声がしっかりと行き届くように。","voiceIndex":225,"id":"exchange-062"},{"speaker":"おぎの委員","kind":"確認","question":"いろいろな意見を聴いてガイドラインに落とし込んでいく作業というか、そういった機会を持っていくということで確認いたしました。陳情では、中立な会となるようにということで、前回は少しこの方は発言しづらかったのかなという部分も感じられますが、前回のやり方はどんな感じだったのかというのと、あと推進派と反対派が同じグループになるのも避けてくださいということですが、これは可能なのでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"２点目の推進派と反対派ですが、なかなか区といたしましては、受付時にどちらの方ですかと聞くわけにもいきませんので、そちらはなかなか判断がしづらいところですので、昨年開催したように、あくまで、例えば抽せんでやるだとか。","voiceIndex":227,"id":"exchange-063"},{"speaker":"おぎの委員","kind":"質問","question":"本日結論を出すでお願いいたします。本当に様々なご意見があると思います。推進派と反対派がグループ別になってしまうと話合いにならないかなと思いますので、 お互いの考えていることが理解できて納得できるような、そういった会をしっかりとつくっていただきたいと思います。今回のこちらは不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":230,"id":"exchange-064"},{"speaker":"えのした副委員長","kind":"確認","question":"本日結論を出すでお願いします。区の予定も確認ができました。秋頃から年内予定で意見交換会およびアンケート調査を実施ということで、開催方法、実施範囲等は現在検討中ということでしたが、中立な立場でやっているということで、 まちづくりに対して今後も丁寧な対応をお願いいたします。不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":231,"id":"exchange-065"},{"speaker":"こんの委員","kind":"確認","question":"強硬にとか、そういうことではなくて、両者が何度も話合いを重ねていきながら溝を埋めていって、この地域の将来像を決めていくということが非常に大事かなと思うところから、今、区としては、先ほど質疑の中にありまして確認しましたけれども、当然中立の立場で進めてくださっているところですので、今後も地道に忍耐強く話合いを重ねていただきながら、あるべき姿のまちづくりをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":232,"id":"exchange-066"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、採択でお願いしたいのですが、言うまでもなく、開発企業主導で進める超高層再開発準備組合に加担するということが、行政の行うまちづくりではないと思います。超高層再開発は、 その地区内に住む居住者、権利者に大きな影響を与え、また、建物の規模からいって、周辺地域にも大きな影響を与えるものです。したがって、採択を主張したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":233,"id":"exchange-067"}]},{"id":"topic-05","title":"令和８年陳情第２９号、危険行為、違反行為を行った建設事業者にペナルティー等を科すこ とを求める陳情","agenda":"令和８年陳情第２９号、危険行為、違反行為を行った建設事業者にペナルティー等を科すこ とを求める陳情","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"今、看板の設置のお話がご説明ありましたけれども、陳情の工事現場で、理由のところにありますような隣地への落下物なども含めて、ほかの違反行為とか危険行為は確認されたのか伺いたいと思います。","respondent":"川原住宅課長","answer":"道路使用の許可であるとか、占用許可であるとか、あと建築基準法上に係ることについては、関連部署に連絡を取らせていただいて、関連部署から確認をするなどの対応をしていただいて、結果、陳情者に、このようなことだったということで。","voiceIndex":242,"id":"exchange-068"},{"speaker":"安藤委員","kind":"質問","question":"条例の説明もありましたけれども、現状では危険行為や違反行為を繰り返すことについては、 公表の対象となっていないといいますか、手引も見ましたが、条例も見ましたけれども、看板ですとか、 かなり限られたところのみになっていると思うのですが、例えば、これから条例などでもう少し広げて、 公表というペナルティーを規定するということは可能なのか、また。","respondent":"川原住宅課長、森建築課長","answer":"現在、今申し上げたのは中高層建築物の建築に係る条例という形でございまして、ここの項目では、 公表といったところは先ほど申し上げた内容にはなってしまうのですけれども。今、２１回ほど落下物があったということですけれども、そういうことをしていない。今回、シートは張ってあったので違反ではないのですが、全く張らないで、物が落ちるような状況で工事を進めている場合は、罰金等の規定があります。","voiceIndex":244,"id":"exchange-069"},{"speaker":"おぎの委員","kind":"質問","question":"違法といいますか、不適切なものに関しては、適宜介入していただくということで、一方で、しっかりとされていても、思わず事故が起きてしまうことはあると思うのですが、最近ニュースにもなっていましたが、西五反田の足場の倒壊等のときも、区ではどういった介入を行ったのでしょうか。","respondent":"森建築課長","answer":"内容といたしましては、作業的なミスみたいなのがあって、外壁が倒壊して、そのまま足場も倒壊したということでしたので、そういうことはないように話をいたしました。警察や消防も来ていました。様々連携を取りながら、そういうことがないように指導しています。","voiceIndex":248,"id":"exchange-070"},{"speaker":"えのした副委員長","kind":"質問","question":"本日結論を出すでお願いします。紛争予防に関わる条例についてもご説明いただきまして、様々、区も事象ごとに対応していただいているということで、建築計画の標識も設置されてきましたし、近隣住民説明会も行われているということで、今後も建築主および近隣住民に対して、問題解決するようにご調整をお願いいたします。不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":252,"id":"exchange-071"},{"speaker":"こんの委員","kind":"質問・要望","question":"本日結論を出すでお願いいたします。先ほどの質疑も聞かせていただいて、そういうことなのだなと、こちらも質問したいと思ったところが答弁で聞けて、確認ができました。いわゆる条例に基づくもの、法的には違反という行為には当たらなかったといったところ、また、それ以外のところで適宜対応してくださっている区の対応、こうしたものも確認をさせていただきました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":253,"id":"exchange-072"},{"speaker":"安藤委員","kind":"意見","question":"確かに、何を危険行為とするか、違反行為をどう判断するかは難しい点はあるのですけれども、危険行為ですとか違反行為を防ぐために、区の規定の改善の検討はあってもよいと思われます。は検討からというところで、趣旨採択を主張します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":254,"id":"exchange-073"},{"speaker":"高橋（伸）委員","kind":"意見","question":"本日結論を出すでお願いします。私はこの陳情を見て、少し驚きなのですけれども、今もってこういう建設業者はいるのですね。少し私も驚いているところであります。町場は近隣でやるときは、本当に気を遣ってやっているわけです。今後こういったことがあれば、また指導、最終的には公表となるかもしれませんけれども、本日のこの陳情に対しては、不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":255,"id":"exchange-074"}]},{"id":"topic-06","title":"令和８年請願第４号、先日ギックリ腰になりました。ベンチがなくて辛かったです～ベンチ 増設の請願","agenda":"令和８年請願第４号、先日ギックリ腰になりました。ベンチがなくて辛かったです～ベンチ 増設の請願","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"昨年９月に建設委員会で、ベンチ設置に関連した陳情の審査がありましたけれども、そのときに比べて、今ご説明もありましたが、２つ増えて２８７基となったのですけれども、場所が多いという言葉もありましたが、どのような経緯で増えたのかというのを知りたい、あと、もう少し場所なども詳しく伺いたいというのが一つと、品川区としては。","respondent":"櫻木地域交通政策課長","answer":"ご要望、また交通状況等含めて、適地があり、かつご要望があるところであれば、検討していきたいと考えています。","voiceIndex":264,"id":"exchange-075"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。検討していきたいということでしたし、増えたところも、区民等からの要望で増えたということなので、今後とも要望を受けて、ぜひ増やしていっていただきたいと思います。今後の検討で、樹木被覆地面積ですとか、樹冠被覆率ですとか、そういったものをここまで持っていくという目標を持つ考えは品川区にはあるのでしょうか、伺いたいと思います。","respondent":"髙梨都市計画課長","answer":"樹冠被覆率については、海外の事例も今広く調査をしているところで、ニューヨーク等で用いられている指標であるというところは確認をしておりまして、品川区での適用等についても、今後検討の中で考えてまいりたいと考えています。","voiceIndex":266,"id":"exchange-076"},{"speaker":"安藤委員","kind":"確認","question":"ごめんなさい、樹木被覆地と同じ意味だということなのかという確認と、あと、そういった数値的な目標を持つ考えはあるのかというのを伺ったので、もう一度お願いします。","respondent":"大友公園課長、髙梨都市計画課長","answer":"樹木被覆地と樹冠被覆率なのですけれども、正式には若干異なるところはあるのですが、ほぼイコー ルというところで考えて捉えていただいて大丈夫かと思います。数値目標を樹冠被覆率で設けるかどうか等についても、現在検討中です。","voiceIndex":268,"id":"exchange-077"},{"speaker":"おぎの委員","kind":"質問","question":"私から簡単に２点だけお聞きしたいと思います。他区の状況はどうなっているのでしょうか。他区と比べて、品川区はそんなに少ない感じなのでしょうか。あわせまして、お休み石マップみたいなのを、私が探せていないだけかもしれないのですけれども、そういったものがあれば行動計画が立てやすいのかなと思いますが、その辺りに関してはいかがでしょうか。","respondent":"櫻木地域交通政策課長","answer":"２点目のマップにつきましては、少しデータの整理等ありますが、今後様々な形でお知らせ、周知していければと考えています。","voiceIndex":272,"id":"exchange-078"},{"speaker":"おぎの委員","kind":"質問・要望","question":"今お話を聞かせていただきまして、品川区はかなりの数のお休み石があるということで、ベンチを含めて、要望があれば、お休み石も適地であれば増やしているということで、先ほど要望として少し上げさせていただきましたが、ご高齢の方や体調の優れない方は、ベンチなどを必要としていらっしゃる方もたくさんいらっしゃいますので、ぜひ周知を含め、「ここにお休み石がありますよ」みたいなものがあれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":275,"id":"exchange-079"},{"speaker":"えのした副委員長","kind":"質問・要望","question":"本日結論を出すでお願いいたします。お休み石の設置、ベンチ、こちらも区民の要望から増えていると。木陰の面積も増えているということで、シェードポリシーにも期待をしておりますということで、不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":276,"id":"exchange-080"},{"speaker":"こんの委員","kind":"質問・要望","question":"本日結論を出すでお願いしたいと思います。昨年も同様の陳情が出されていたところで、議事録も確認してきました。ですので、事前に品川区はこれだけ設置されているのだということも私は確認して、今日は出席をしております。それでも区としては要望があれば、また、歩道上安全性が確保されて適地であれば、設置をするという考え方も持っていただいている。大変にありがたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":277,"id":"exchange-081"},{"speaker":"安藤委員","kind":"確認","question":"なので、品川区ももちろん、質疑を通して、これからも増やしていくという意思はあるということも確認させていただきましたけれども、さらに区民の皆さんのこうした請願を採択することで、そうした方向性も議会から後押ししていくというのも大事なのではないかということで、私は採択を主張させていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":278,"id":"exchange-082"}]},{"id":"topic-07","title":"令和８年７月区営住宅入居者募集","agenda":"令和８年７月区営住宅入居者募集","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"区営住宅のニーズは明らかなので、一般質問でも共産党は求めましたけれども、増設すべきだと思いますが、一般質問で公営住宅の増設を求める質問については、民間住宅も含めた住宅ストック全体で考えていく必要があると認識しているという答弁だったのですが、要するに、民間を含めた区内の住宅は余っているから、つくらないということだと思うのですけれども、実際どれぐらいストックがあるのですかというか。","respondent":"川原住宅課長","answer":"一方で、６万から８万円の少し価格が上がった家賃価格帯は、約２万８,６００戸あるということで、 それぞれ低価格帯のものも、６万から８万円台の価格帯のものも、２,６００戸、３,６００戸、それぞれ戸数としては増えている状況でございまして、これに基づきまして。","voiceIndex":286,"id":"exchange-083"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは要望なのですが、それと、ごめんなさい、最後、先ほどの令和５年度、１２万６,０００戸が借家としてあるということですが、これは余っている戸数なのですか、それとも純粋に、人が入っているか入っていないかは問わないで、それだけの戸数があるという意味なのでしょうか。どちらなのか伺わせてください。","respondent":"川原住宅課長","answer":"あくまでも借家数ということで、戸数です。空きがある住戸数とはまた別という形でございます。","voiceIndex":288,"id":"exchange-084"},{"speaker":"安藤委員","kind":"質問・要望","question":"空いていたとしても、高いところだったら入れないというところもありますので、そういった現状を踏まえて、現在の生活困窮者の方々の住まいの相談を受けている業界の皆さんなどの現場の声もよく聴いて、住宅政策を見直していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":290,"id":"exchange-085"},{"speaker":"こんの委員","kind":"質問・要望","question":"２点お伺いしたいと思います。一つは、区営住宅の申込みについて、都営住宅では電子で申込みができる。区営住宅は電子の申込みは今ないと認識しているのですが、今後はそういうことは考えていらっしゃるのですかといったところが１点。もう１点が、何年前になるでしょうか、二葉一丁目区営住宅の建て替えについてという要望を、これまで何度か議会質問で上げさせていただいてきました。","respondent":"川原住宅課長","answer":"委員ご指摘のとおり、都営住宅については令和５年から電子申請を開始したというところで、今、区としてどういった形で電子申請が可能かどうかというところは、昨年度から検証しているところでございますが。","voiceIndex":292,"id":"exchange-086"},{"speaker":"こんの委員","kind":"確認","question":"電子申請は分かりました。検証されて、考え方としては、そういった方向性も考えられるといったことを思っていらっしゃるのだと確認させていただきましたので、この先、電子が主流になってくるというのは、時代的にもあるのかなと思うと、こうしたところも考えていくことが必要であるかなと思っております。ですが、更新をしないということではないということも、今のお答えで確認をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":294,"id":"exchange-087"}]},{"id":"topic-08","title":"専決処分の報告について（報告第１９号）","agenda":"専決処分の報告について（報告第１９号）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"通行人など人に当たる可能性は、時間帯によってはあったと考えているのか伺いたいと思います。そして、なかなか簡単ではないと思うのですけれども、再発防止策というのはどういったことを考えているのか伺います。","respondent":"森道路課長","answer":"対策ですけれども、本樹木も樹木診断を実施して、不健全という結果が出ておりましたので、倒木が起きる前に伐採をしていくように考えていたところ、実際に倒木が起きてしまったというところで、タイミングの話だったのかなというところもありますけれども。","voiceIndex":299,"id":"exchange-088"}]},{"id":"topic-09","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"６月２５日の松永議員、新妻議員、６月２６日のこしば議員の地域公共交通についての質問なのですけれども、品川区は今後、環境の変化などを踏まえて、区民へのアンケートや移動データ等も用いて、 区全体の交通ネットワークを総合的に検討していくという答弁だったと思うのですが、改めて、今後の地域公共交通全体についての方針をどのように考えているのかというのを伺うのと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":303,"id":"exchange-089"},{"speaker":"安藤委員","kind":"質問","question":"先日土曜日、６月２７日に台風が２つ、７号・８号が来たわけですけれども、災害対策本部は設置されなかったと思うのですが、それでよいのかというのと、あと、設置するときとしないときというのは、 基準というか、考え方があると思うのですけれども、今回設置されなかった理由というか、基準みたいなのがあればお伺いしたいと思います。","respondent":"羽鳥防災課長","answer":"先日の台風７号・８号についての対応についてご質問がありましたので、お答えさせていただきたいと思います。結果といたしましては、今回、災害対策本部は立ち上がらずに済んだというところです。","voiceIndex":311,"id":"exchange-090"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.29ke.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":61,"characters":73361,"voices":314}},{"id":"r08-20260629-9","meetingId":"r08-m0708","date":"2026年6月29日","dateIso":"2026-06-29","committee":"文教委員会","time":"午前10時00分～午後１時55分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を57件抜き出しています。","hasFullText":false,"topics":[{"id":"topic-01","title":"第６７号議案 品川区文化財保護条例の一部を改正する条例","agenda":"第６７号議案 品川区文化財保護条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"今、指定文化財制度がある上で登録文化財制度というところですが、資料２ページ目の３の指定文化財制度と登録文化財制度の違いですね。強い規制と緩やかな規制。区の支援のところです。修理の補助金というのが、指定文化財制度にも登録文化財制度にもありますが、これ、額は違うものなのか伺いたい。保存と活用を促進するということですが、活用というのは、 例えばどういうことなのか、伺いたいと思います。","respondent":"舩木庶務課長","answer":"この補助については、区指定文化財制度と区登録文化財制度に同等の必要と認められるものをしっかりと対応していくということを予定して考えておりますが、ここでの差異としましては、区指定文化財制度には奨励金があるということです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。そうすると、緩やかな規制というところでは、届出を受理された時点でもう形や色の変更ができるということなのですね。現在、指定文化財は区内にどのくらいあって、２３区では、今、登録文化財制度はどこまで広がっているのか、教えてください。","respondent":"舩木庶務課長","answer":"区の指定文化財は、現在１４３件あります。既に登録文化財制度を条例の中に盛り込んでいる自治体もあります。２３区に目を向けますと、１６区ほどこの登録文化財制度を導入済みであることを確認しております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"結構な区が登録文化財制度を導入されているということです。品川区が今回登録文化財制度を導入することになった理由と、指定文化財は今まであったわけですけれど、指定文化財が登録文化財に変わっていくということはないのですね。指定文化財はもうずっと指定文化財のまま、 登録文化財になるのは新たなものという考え方でよろしいでしょうか。","respondent":"舩木庶務課長","answer":"これまで積極的に指定文化財制度を進めていた本区ではありますが、 区教育委員会といたしましては、文化財保護審議会の中でどういった形でそういったところを進めていくかということで、約３年強にわたって審議を重ねた中で、このたびお示ししている案で考え方がまとまったです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"西本委員","kind":"質問・要望","question":"要望が非常に多くなってきているなと思うのと、指定文化財が１４３件あるということなのですが、 その管理の方法というのはやはり問題かなと思っています。それから、往々にして持ち主がほとんど民間です。企業もあるかもしれません。それから保護奨励金というものも、決まりがあるのですか。運用上、細かい規定が必要なのかなというのが多々あると思いますが、その件はいかがでしょうか。","respondent":"舩木庶務課長","answer":"最後、奨励金につきましては規定が細かくありますが、おおむね１.５万円から５万円の範囲内で、 有形、無形、それからそれぞれ区分があるのですけれど、そういう形で支援しています。","voiceIndex":12,"id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"非常にいいことだとは思うのです。これは有形・無形も含めてです。それから、これは区民だけでなくて、先ほど言ったように事業者にも関わる話です。だから事前に確認してくださいなどと、部署はまたがってしまうかもしれませんが、そこを共有していかないと、いいことをやっても大きなもめごとにつながってしまいます。そこは工夫して、周知徹底していただきたいなと思います。いかがでしょうか。","respondent":"舩木庶務課長","answer":"２点目につきましては、品川区として指定文化財制度、登録文化財制度という両輪で進めていくに当たっては、しっかりと条例等の中で理解が得られるように進めていきたいと考えております。","voiceIndex":14,"id":"exchange-005"},{"speaker":"澤田委員","kind":"質問・要望","question":"私からは、学校との連携についてお伺いしたいのですが、先ほどご説明の中で、文化財を巡る授業などもやっているとおっしゃっていたと思いますが、これは区内の全校が行っているのかというところと、校長先生の判断などで学校ごとに実施されているのか。具体的にどんなことをされているのかということを教えていただきたいなというところです。お願いします。","respondent":"舩木庶務課長","answer":"そういうところで進めているという中で、学校としては、市民科の中で品川博士になろうみたいな感じで、大森貝塚や伊藤博文公のお墓といったところにも少し触れられております。この辺りは、どういう対応が取れるかは、教育委員会の内部でも検討してまいりたいと考えています。","voiceIndex":17,"id":"exchange-006"},{"speaker":"澤田委員","kind":"意見","question":"地域の方と回るというところですけれど、学校と勘違いしていました。地域の方がそうやって回ることも、すごくツアーとして楽しいと思います。もうされているかもしれませんが、子どもたちがこういう文化財を巡ってみたり、無形文化財を体験するということは、とても大事だと思うのです。自身の住んでいる地域の歴史や文化的な価値のあるものに触れて考えていく。お考えをお聞かせいただけたらと思います。","respondent":"舩木庶務課長","answer":"やはり先々どういうものが登録文化財になっていくかということは、今の段階では未定ですけれども、それを進めていく中で、やはり知っていただく、魅力を感じていただくというところが、歴史文化を理解していただくことにつながるように展開していきたいと考えております。","voiceIndex":19,"id":"exchange-007"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"今、質疑の中で、市民教育の一環というお話があったと思います。地域に密着した文化財の学習資源となっていくと思います。学校にでの制度の周知についても視野に入れて取り組んでいただきたいと思います。これは要望も含めて、お聞きできればと思います。","respondent":"舩木庶務課長","answer":"併せて、学校ということを踏まえたときにどういう進め方ができるかについては、先ほどご答弁しましたように、どういう関わり方ができるかどうかは、教育委員会内部でも検討してまいりたいと考えております。","voiceIndex":23,"id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ご説明ありがとうございました。それから品川歴史館、それから学校、また地域団体ですかね。もう少しお考えを伺いたいと思います。ほかの委員の質問にもありましたが、保存云々も含めますけれども、次世代に伝える取組を、次世代といっても学校教育になっていくことも多いと思いますが、どのように強化していくのかという取組がもしあれば、具体的にお願いします。","respondent":"酒川指導課長、舩木庶務課長","answer":"学校教育での文化財の扱いの１点目について、お答えします。特に小学校３年生、４年生が、区または都の学習をする中で、地域の年中行事や具体的な有形の文化財等について学びます。それらがどんな思いで継承されてきたか。１つ１つどういったものが登録文化財になるかというところはこれから進めてまいりますが、委員ご指摘のところも含めて考えていきたいと思います。","voiceIndex":26,"id":"exchange-009"},{"speaker":"山本副委員長","kind":"質問・要望","question":"私から何点かお伺いいたします。区登録文化財制度ということで、緩やかな基準を設けるということですが、お申出があった場合の審査は誰がどのように判断するのかというところで、区指定文化財制度との違いを踏まえて教えていただければと思います。それから、登録はどの程度の件数を見込まれているのかということを教えてください。既に何かもう区民からの要望等で候補があるようでしたら、教えてください。","respondent":"舩木庶務課長","answer":"今申し上げた部分について、約１年以上かかってしまうというところもありますので、登録については、若干速やかに所有者のご意向をもってという意味では、文化財保護審議会の届出をもって、審議会の中で審議をし、そこで登録の妥当性を検討して。","voiceIndex":31,"id":"exchange-010"},{"speaker":"山本副委員長","kind":"質問・要望","question":"それぞれご答弁ありがとうございました。理解が深まりました。審査についても理解しました。文化財保護審議会に届け出て、確認いただくということで、基本的には受けていただけると思うのですが、そこでもしっかり確認いただけるということで理解しました。３０件、４０件これから増えていくものを、どのように区民にお知らせしていくかということについて、方針があれば教えてください。","respondent":"舩木庶務課長","answer":"維持補修の予算につきましては、今年度については、既存の予算の中で対応していかれないかということは、事前に財政部門と話をして、今後、登録の件数であるとか数の膨らみによっては、しっかりと対応できるようにしていきたいと考えています。","voiceIndex":33,"id":"exchange-011"},{"speaker":"山本副委員長","kind":"質問・要望","question":"ご説明ありがとうございました。区民の郷土への関心、愛着を高める取組と思いますので、ぜひ効果のあるものとして進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"賛成なのですが、今回、保存と活用ということで、活用という部分が入ったと思います。その活用のされ方が、保存という形ではなくて、開発とかに絡まれていくような形でないようにしていただきたいなと思いますし、そうあるべきだなと思いますので、そこに私たちは注目していきたいと思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-013"}]},{"id":"topic-02","title":"第８０号議案 児童相談所を設置する特別区における措置費共同経理課の共同設置に関する 規約の変更","agenda":"第８０号議案 児童相談所を設置する特別区における措置費共同経理課の共同設置に関する 規約の変更","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"今、ご説明されたとおりだと思いますが、要は、児童相談所を開設する区が新たに増えると、こういう議案になるということなのでしょうか。","respondent":"柴田子ども施策連携担当課長","answer":"委員のおっしゃるとおり、児童相談所を設置する区が増えましたらば、毎回このような形で議会にお諮りして議決をいただく。こういったプロセスを踏んでいく形となっております。","voiceIndex":47,"id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"１１か所とのことですが、これは何か所まで増える予定なのでしょうか。今２３区全部ではなかったと思うので、大体それが定まっている状況なのかということが聞きたいです。それから措置費共同経理課という形なのですが、これは一体何をするところで、権限はどこまであるのでしょうか。私たち品川区にとってのメリットは何でしょうか。教えてください。","respondent":"柴田子ども施策連携担当課長","answer":"大きく２点ご質問いただきました。１点目の児童相談所は杉並区が１１か所目なのですが、今後増えていくことにつきましては、こちらで各区のホームページを調べたところによりますと、あと１区、北区が開設予定を公表しております。","voiceIndex":50,"id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"北区が加わるということが考えられているということですが、ただ、これは開設の数によって、都区間との交渉というのは、どういうふうな動向になっていくのでしょうか。２３区でいいのですが、何区ぐらいが確実に児童相談所をやっていこうという意識があるのかということを、もし分かったら教えてほしいです。それは、今１１か所だから、１１か所の自治体が出資しているという感覚でいいのですか。","respondent":"柴田子ども施策連携担当課長","answer":"大田区もホームページでそのような報告をされております。それ以外、その方向性といったところは、私どもではホームページでのチェックというのが限界ですので、現状は、先ほどお伝えしたとおり、今後設置が予定されているのは北区が１区ですね。そのように認識してございます。","voiceIndex":52,"id":"exchange-016"},{"speaker":"西本委員","kind":"提案","question":"ありがとうございました。分担というのはどのぐらいの金額なのか、大まかでいいので、このぐらい品川区から出ているというのを、分かったら教えてほしいです。今１１か所になり、それぞれ児童相談所の在り方が違うと思うのですが、いろいろ情報共有することによって、運用上のヒントや改善提案などができるかと思います。そういう仕組みにもなっているということでしょうか。そこら辺を教えてください。","respondent":"柴田子ども施策連携担当課長","answer":"今年度も既に開かれて、来月も予定されていたりと、頻繁な情報共有ができておりますので、いろいろノウハウを学びながら、児童相談所の運営の充実につなげてまいりたいと考えています。","voiceIndex":54,"id":"exchange-017"},{"speaker":"澤田委員","kind":"質問","question":"ご説明ありがとうございました。私からお伺いしたいのは、病児保育についてです。お伺いしたいのは、これは病児ではないのですけれども、区立園で保育士が急遽お休みした際に、 連携して園同士で先生方を補塡するというか、そういうのがあったような気がしましたが、お分かりになれば、まずそこを教えていただいてよろしいでしょうか。","respondent":"染谷保育施設運営課長","answer":"基本的には、各園で休みが入った場合についても、今、園の中で体制が取れるような人員配置にはなっておりますが、例えば看護師ですとか、各園に１人ないし２人という少人数しかいない職種に関しては、ブロックにおきまして応援体制を取って、ほかの園から応援派遣という形で。","voiceIndex":71,"id":"exchange-018"},{"speaker":"澤田委員","kind":"質問","question":"病児保育の現場で、必ず保育士が配置されていると思います。預かる人数によってというのがありますけれども、常時いなければいけないというのがあったと思います。そうすると、やはり保育士が急遽お休みすることがあるという声を伺っております。保育士が足りないときに応援できる体制というか、情報共有も含めて、そういうことができるプラットフォームというのはあるのでしょうか。","respondent":"染谷保育施設運営課長","answer":"今お話のありました急な欠員への対応というところも含めまして、区の委託事業として病児保育を実施していただくに当たって、区の支援があったほうがいいというお声は、個別に今お話を伺っているところではあるのですが、今、プラットフォームというお話もございましたけれど。","voiceIndex":73,"id":"exchange-019"},{"speaker":"澤田委員","kind":"質問","question":"お声も届いていらっしゃるというところで、よかったなと思っています。すみません、もう一点です。以前、私は委員会で、年齢拡大というのを病児保育で質問したこともあります。小学校低学年というのも、やはり病児保育というか。課題認識というか、そちらも教えていただけたらと思います。","respondent":"染谷保育施設運営課長","answer":"様々区民の声ですとかご意見のメールなどで、病児保育についてのご要望等をいただいておりますので、そういったニーズを確認させていただきながら、年齢拡大について可能なのかどうかということも含めて検討させていただければと考えております。","voiceIndex":75,"id":"exchange-020"},{"speaker":"澤田委員","kind":"提案","question":"例えば病後児保育をやっているところだと結構広いスペースのところがあったり、人数を多く預かれるような場所があるというところもお聞きしています。全施設で一斉に始めるというよりは、例えばそういうところでお試しというか、一度やっていただく機会を施設に提案していただいたり、働きかけていただくことというのも１つあるのかなと思いました。いかがでしょうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":77,"id":"exchange-021"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これは、国のほうで引き上げることに伴ってということですが、国はなぜこれを引き上げようとしたのか、理由を伺いたいのと、認可外、私立幼稚園、ぷりすくーる、それから区立の幼稚園、認定こども園、それぞれどれぐらいの方が利用されていて、これは上限なので、上限を超える方というのは自己負担が出てくるということになると思いますが、自己負担が出る方というのはどれぐらいいるのかというのが。","respondent":"佐藤保育入園調整課長、染谷保育施設運営課長","answer":"今回の国の引上げの理由です。こちらの施設等利用給付交付金が、国は、令和元年１０月から据え置いていたというところで、直近の物価水準や賃金動向を踏まえて見直しを実施するというようなところでお知らせが来ております。区立幼稚園等についてですが、今、在園児数が令和８年４月時点で３１１名いるうちのおよそ７割程度の方が、この子育てのための施設等利用給付の認定を受けています。","voiceIndex":82,"id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"最初に言った数字は、これは、今回のでプラスになる方を言っていただいたのか。ごめんなさい、そこをもう一回伺いたいのと、幼稚園のところは詳しく説明いただき、分かりました。物価水準が落ち着いて賃金が上がるのが一番いいと思いますが、そういったところでの対応というのは、引き続き求めていっていただきたいなと思っています。最初のところだけ、数字が、何の数字だったのかというのを伺います。","respondent":"佐藤保育入園調整課長","answer":"失礼いたしました。私のほうで申し上げたところにつきましては、今回の補正でプラスになる方の人数というところです。","voiceIndex":85,"id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"質問","question":"結構多くの方がプラスになるということです。次の病児保育のところです。病児保育の新規も４名ということですけれど、それも含めて、病児保育というのは、合わせると定員は何人なのか、病後児保育は何人の定員なのかを伺いたいのと、利用率はいかがでしょうか。なので、その需要がどうなのかというところです。それについて目標というのはあるのでしょうかということを伺いたいと思います。","respondent":"染谷保育施設運営課長","answer":"そういったエリアに関しては、今後その中で例えば開設が可能なクリニックがあるかないかですとか、医師会とも話をさせていただきながら、どこにでもつくるということではなくて、地域をある程度絞った形で今後開設を進めていくというのが目標というか。","voiceIndex":87,"id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。特定の資材とは鋼材ですとおっしゃったと思いますが、どこにどういうふうに使われる鋼材なのかということと、鈴ケ森小学校の工事の入札が不調だったということです。これから再入札に臨む。工期の延長はないとおっしゃっていました。入札が順当に行くことを想定されていると思いますけれども、工期延長は本当にないのですかというところを、もう少し具体的に改めて伺いたいと思います。","respondent":"荒木学校施設担当課長","answer":"この期間が長いということもございまして、今回不調となった機械設備工事に関しましては、本件で補正予算をご議決いただいた後、次回の第３回定例会でしっかりと入札手続を進めて契約をしていけば、十分間に合うだろうと見込んです。","voiceIndex":89,"id":"exchange-025"},{"speaker":"西本委員","kind":"質問","question":"こういうふうに変わったというのは分かりますが、品川区にとってどういう影響があるのでしょうかというのを知りたいのです。要は、国が上げたから、負担額が逆に下がったというふうに見るべきなのか。認可外保育所というのは、品川区の施設として無償化になっているのですか。病児保育と病後児保育とありますけれど、この違いは何ですか。どういう区分けをしていますかということをまず教えてください。","respondent":"佐藤保育入園調整課長、染谷保育施設運営課長","answer":"こちらは国のほうでやっておりますけれども、国の負担が２分の１、都の負担が４分の１ということで、区の負担も４分の１ある形ですので、こちらの制度を適用させるためには、一定の区の持ち出しがあるというところで。病後児保育は、 病気の回復期であって、安静の確保に配慮する必要があり、医師が不在でも保育が可能と診断されている児童というところで、それぞれお預かりするお子さんの条件といったところは決めております。","voiceIndex":92,"id":"exchange-026"},{"speaker":"西本委員","kind":"確認","question":"保育料の件、利用料なのですが、補正の内容が、歳出が２,７９３万円余、歳入が２,１７３万円余ですが、この差額は品川区の財布から出るということですか。それが今回の改正に伴って負担するという認識でよろしいでしょうかというのを確認させてください。大変だ。子どもにとってと考えたときに、この病児保育というのがどういう意味を持つのでしょうかということをきちんと考えないといけないと思います。","respondent":"佐藤保育入園調整課長、染谷保育施設運営課長、荒木学校施設担当課長","answer":"交付金の引上げのところです。最終的には、差額は、歳出が６００万円余のプラスになっております。もちろん病気のときにはご自宅でお子さんと過ごせる環境が望ましいということは、こちらもそういうふうに考えているところではありますが。学校改築の不調の事例です。先ほどご説明した鈴ケ森小学校の建築工事につきましても、昨年度１度入札不調が発生しています。","voiceIndex":95,"id":"exchange-027"},{"speaker":"西本委員","kind":"質問・要望","question":"それは行政として啓発活動をしていかないといけないのではないのですか。最後、お考えをお聞きしたいと思います。１８校ですか、改築をまだ決めていないところもあるということで、やらなければいけないです。工期は延びる。そうすると、鈴ケ森小学校の工事費だけでも１００億円です。私は非常に危機感を持っているのですけれども、そこの危機感をどう感じておられるかだけ教えていただけますでしょうか。","respondent":"柴田子ども施策連携担当課長、荒木学校施設担当課長","answer":"区の取組が子どもにとってどう受け止められているのかという視点も持ちながら、そういったところで意見聴取を進めていきたいと考えています。よろしくお願いいたします。公共施設整備の発注者として、しっかりと対応していきたいと考えてございます。具体的には、現在私どもで進めている取組ですが、１点目が、適正な予定価格での発注でございます。","voiceIndex":99,"id":"exchange-028"},{"speaker":"西本委員","kind":"質問・要望","question":"病児保育については今回新設ということから、こどもの権利条例の話にまで広げてしまいましたけれども、やはり知っていただきたいのは、子ども支援と子育て支援というのは違うのですよ。なので、そこを踏まえて考えていただきたい。当然やっていますというお話だと思いますけれども、子どもたちの校舎ですから、うまく新しい校舎を短い期間で何とか造れてという形で、ぜひご努力いただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-029"},{"speaker":"ゆきた委員","kind":"確認","question":"保育の利用補助について伺います。病児保育のほうで、今回の施設整備は、利用定員の不足を解消するためではなくて、地域偏在を解消して、利用者が身近な場所で利用できる環境を整えることが主な目的という理解でよろしいか、 改めて確認でお聞きしたいと思います。","respondent":"佐藤保育入園調整課長、染谷保育施設運営課長","answer":"現在受けていらっしゃる方、 今回こちらが引上げになる前につきましても、様々給付のお知らせ等を個別にしているものがございますので、そのタイミングに合わせて。ただ、区の西側と比較すると、東側のエリアにおいては施設数が足りていないという状況がございましたので、そういった意味では、委員おっしゃられたとおり、偏在を是正するという意味で今回開設していきたいと考えているものです。","voiceIndex":106,"id":"exchange-030"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"認可外保育施設については補助総額に変更はないので、なぜ認可外だけ変わらないのかと疑問に感じる利用者が一定数いらっしゃると思います。こちらは要望で終わりたいと思います。病児保育のところです。実際に西大井周辺にお住まいの保護者から、利用しづらいとか、近くに施設が欲しいといったご意見とか要望は区に寄せられているのか、お聞きしたいと思います。お願いします。","respondent":"染谷保育施設運営課長","answer":"西大井のエリアにお住まいの保護者のお声は、現状においては把握しておりませんが、いただくご意見の中で、施設が近くになくて利用しづらいというお声というのは、エリアは限定されませんけれども、 多少いただいております。","voiceIndex":109,"id":"exchange-031"},{"speaker":"ゆきた委員","kind":"確認","question":"確認できました。先ほどのこの偏在の改善については、開設が可能なクリニックや医師会とも連携して、地域を絞って行うということもあったと思いますが、偏在の解消を進める上で、整備の候補地域を選定していくのに、 選定基準といったものはあるのか、お聞きしたいと思います。","respondent":"染谷保育施設運営課長","answer":"整備をどのような形で進めていくかというところにつきましては、現状において、エリアごとに需要と供給の数字をこちらで出しているものがあります。そういった数字を見ていく中で、必要なところに整備していくという考え方で進めてまいりたいと考えております。","voiceIndex":111,"id":"exchange-032"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"西大井周辺も含めて、引き続き区民の声を把握し、必要な地域への施設整備につなげていただくことを要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-033"},{"speaker":"高橋（し）委員","kind":"質問","question":"病児保育についてお尋ねします。ほかの委員からもありましたが、この図でいくと、大井町の横の駅は下神明なのですかね。数字的に充足したので一段落というところなのかというのが１つです。いろいろなご事情でどうしてもやめてしまうこともあるけれど、 でもそこはというのを、契約上何とかできるのかというところをお伺いします。","respondent":"染谷保育施設運営課長","answer":"それから契約の部分については、基本的には委託契約については、単年度ごとで契約を結んでいるところではありますが、今委員のお話の中でもありましたとおり、施設整備をしていくことによりまして国や都からの補助金を受けるということがある中で、施設の減価償却。","voiceIndex":115,"id":"exchange-034"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"契約については、区のほうでお願いしているという部分もありますけれども、やはり地域の方のご利用だったり安心感のためには、永久的というとあれですが、きちんとお願いするというところを確認いただきたいのと、もう一つは、今お話があったように、やはりまだまだ南品川とか東品川もそうですけれど、特に南大井、東大井も含めて、マンションがたくさんできて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-035"}]},{"id":"topic-03","title":"令和８年度第１回家庭教育講演会","agenda":"令和８年度第１回家庭教育講演会","exchanges":[{"speaker":"澤田委員","kind":"意見","question":"ぜひ広く子育てに関わる皆さんに視聴していただけたらなと思います。申込みも要らないし、時間帯も働いている方でも見られるのは本当にありがたいと思いますので、どうぞよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":167,"id":"exchange-036"},{"speaker":"西本委員","kind":"質問","question":"１点お願いしたいことがあるのですが、この講演は何時間やるのでしょうか。時間が書いていないのです。何時から何時でなくて、この講演が１時間なのか２時間なのか。それをすると、さっと見られるかどうかというのが分かりやすいので、それが欲しいと思ったのですが、いかがでしょうか。","respondent":"舩木庶務課長","answer":"全体で６０分程度の構成にしております。大体１５分刻みぐらいで、資料にありますようにチャプターという項目を設けまして、よりご関心のあるところから視聴できるような環境を整えております。","voiceIndex":169,"id":"exchange-037"},{"speaker":"ゆきた委員","kind":"質問","question":"今ご説明の中で、幅広い区民への周知を行っていくということでした。特性を持っているお子さんの子育てに不安を抱える保護者など、本当に支援を必要としている方に対しての周知というのを改めてどうやって行っていくかお聞きしたいと思います。","respondent":"舩木庶務課長","answer":"そこも含めて、そこにどのようなアプローチをしていくというところは、現時点では詰めていく必要があるかなとは思いますけれども、委員のご指摘のとおり進めていかれればと考えています。","voiceIndex":173,"id":"exchange-038"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"確認できました。大変参考になる内容だと感じております。こういった内容の際には、教育委員会としても、所管をまたがるところ、福祉部門などと連携して、必要な保護者への情報提供、情報の周知というのも必要かと思いますので、そこについては要望したいと思います。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":175,"id":"exchange-039"}]},{"id":"topic-04","title":"令和８年度新入学学校別増減要因一覧","agenda":"令和８年度新入学学校別増減要因一覧","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"今、学校選択に際して、希望申請して入れなかった人を記載していないとおっしゃっていたと思いますが、どれくらいの子というのは、今この場で数字を持っているのでしょうか。","respondent":"石井学務課長","answer":"小学校につきましては、６１７件の希望申請があり４７４名が入学しておりますので、大体入学率としては７６.８％ほど。中学校・義務教育学校後期課程につきましては、４９５名の希望申請がございまして入学者数が１８０名ですので、３６.４％ほどの入学率となっております。","voiceIndex":181,"id":"exchange-040"},{"speaker":"石田（ち）委員","kind":"質問","question":"中学校のほうが入学率が低いというのは、どういう要因でしょうか。","respondent":"石井学務課長","answer":"中学校ですけれども、令和８年度入学から１クラスが３５名になりました。そのことによって、教室数の兼ね合いといったところから、受入れ可能人数が大分減少しました。そのことがこの入学率になっていると、今のところ考えております。","voiceIndex":183,"id":"exchange-041"},{"speaker":"澤田委員","kind":"質問","question":"今、入学率等もお答えになっていらっしゃいましたが、中学校が低いというところで、学校選択制で、違う学校を希望しているにもかかわらず入れなかったということがある中で、やはり今後、学校選択制の在り方、進め方というものの検討が必要となってくると思いますが、 区としてはどのようにお考えでしょうか。","respondent":"石井学務課長","answer":"こうした複合的な要因がありますので、まずは就学人口の動向をきちんと見定めていくということがすごく大事になってくるのではないかなと考えています。","voiceIndex":186,"id":"exchange-042"},{"speaker":"西本委員","kind":"質問","question":"抽せんの結果が、２月初めに分かるではないですか。なので、抽せんに漏れた子がスムーズに次の指定校に行くのかどうか。３月とか３月末になってもなかなか決めかねている子がどれぐらいいるものなのか。その現状を教えてほしいのと、第三日野小学校は、３７名が私立に行ってしまうのですね。私立に対しての希望は、もうこういう傾向なのでしょうか。増えていっている傾向なのでしょうか。お教えください。","respondent":"石井学務課長","answer":"抽せんの結果が出てから、大体小学校は１月ぐらいから申請を受け始めながら、国公立・私立に行かれる方などで希望を辞退される方ですとか、そういったことを含めながら、指定校変更についても一定程度議論していくという形になります。","voiceIndex":190,"id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"すみません。抽せんで漏れた子が、どのぐらいの時期に最終的に行く学校が決まっているのでしょうか。抽せんに漏れてしまったら、別の学校を選ばなければいけないわけではないですか。あまり最近そういう方はいらっしゃらないのか。そこを教えてください。それがいいか悪いかはここでは言えませんが、そういう傾向もあるのではないかなと思うのですが、その辺に対してどうお考えになっていますか。","respondent":"石井学務課長","answer":"私も着任して２年目ですけれども、かつての時代は、かなりの方々が抽せんに漏れた後、指定校変更の手続をなさっていると聞きました。","voiceIndex":192,"id":"exchange-044"},{"speaker":"西本委員","kind":"質問・要望","question":"無償化などが入ってくると、いろいろ変わっていきますので、動向を見ながらいろいろ考えていただきたいと思いますが、学校選択制については、いろいろな保護者の方がいて、今、答弁いただいたように公立学校はどこの学校へ行っても同じ教育を受けられるというのが公教育の最大のメリットだと思いますが、こだわるのですよね。いろいろな理由があると思います。これは意見として申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":194,"id":"exchange-045"},{"speaker":"高橋（し）委員","kind":"質問","question":"学校の魅力発信で、学校説明会や見学会というのをきちんとやっているということですが、それでも４１％のお子さんが私学に行ってしまうということで、これは、結局やっていますけれどということではないのですかね。だから、もう少し小学生に対する、 この中学校はというＰＲの仕方があるのではないかと思うのですけれど、それが１点です。","respondent":"新井特別支援教育担当課長、酒川指導課長","answer":"委員ご指摘の人材のところで、例えば教職員だけでなくて、学習支援員を配置しております。支援が必要な子が、通常の学級にいながらも授業でのサポートを受けられるところも１つメリットとしてはあるかと考えています。大規模校、小規模校の学校支援人材ですが、大規模校においては、スクールサポートスタッフ、エデュケーションアシスタント、副校長補佐を必要に応じて複数配置して支援しております。","voiceIndex":198,"id":"exchange-046"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今、特別支援のほうの指導の話を伺いました。ですから、今お話があったように、しっかりとやっていただけているところはあるのですけれど、それはそれとして、いわゆる普通学級に通っている子たちがどういう学校生活を送れて、私立もそうだけれど公立もこうだというのをもう少しＰＲしていただきたいなと。これは要望で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":201,"id":"exchange-047"},{"speaker":"山本副委員長","kind":"質問","question":"ご説明ありがとうございました。私から質問します。小学校・義務教育学校前期課程の一覧を見ますと、義務教育学校の学校選択実績が非常に多いのが目につきます。やはり義務教育学校に希望が集まっているということかと、この数字を見ると思うのですが、その辺り、区の認識はどのようになりますか。","respondent":"石井学務課長","answer":"義務教育学校につきましては、９年間の一貫教育をやっているというふうなところの魅力は確実にあるのではないかなと考えています。一方で、学校については、中学校連携グループを組みながら、９ 年間の一貫した教育というのは品川区全体で行っている部分ではあります。","voiceIndex":203,"id":"exchange-048"},{"speaker":"山本副委員長","kind":"質問・要望","question":"設備も絡みますし、義務教育学校は人気があるから、どんどん増やしていくという、それは簡単ではないと思いますけれども、小中一貫の義務教育学校は品川区から始まったということで、品川区として評価を得ているということが１つ、これで示されているのかなと思いましたのと、やはりいいということが表れているかと思いますので、できるだけ希望する方々は入れるようにしていただきたいですし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":205,"id":"exchange-049"},{"speaker":"高橋（し）委員","kind":"意見","question":"城南第二小学校が５１人が学校選択で抜けていて、トータルで１０１人抜けて、それで１３４人なのですが、工事の関係なのかと思いますけれども、浜川小学校が完成してからも学区内の人数が多くて今もう本当にぱんぱんで、城南第二小学校も、今工事中だから、工事に向けてということで抜けている方々がそうではなくなったときに、先の話なのですけれど。","respondent":"石井学務課長","answer":"我々としても、そういったところでまた就学人口を推定していきたいと考えています。明日またご報告させていただきたいとは思っているのですけれど、新入学者の受入れ枠の部分でも一定程度考慮していかなければいけない部分があるのかなと考えております。","voiceIndex":207,"id":"exchange-050"},{"speaker":"西本委員","kind":"質問","question":"すみません、今、質問がありました浜川小学校１６３名ですが、これは５クラスになるのでしょうか。ここは新しくなってすてきな学校になったのですが、学区の住民基本台帳上の人数は２０３名です。浜川小学校の周辺というのは、子どもが多くなっている地域と認識してよろしいのでしょうか。どういう現状なのでしょうか。","respondent":"石井学務課長","answer":"浜川小学校の住民基本台帳上の人数は２０３名となっております。ここ数年間の実績ですと、令和８ 年度入学に関して２０３名、昨年度は２０６名、その前は２２４名、その前は２１６名、その前は２４６名ということで、実は少しずつ減ってきております。","voiceIndex":210,"id":"exchange-051"},{"speaker":"西本委員","kind":"質問","question":"先ほどもご心配の質問がありましたが、クラス数などは大丈夫なのですか。下手すると、また城南小学校のように学区域を変えなければいけないという状況に。ただ、この地域は、ほかのところも増えているのですよね。これはどう考えられていますか。","respondent":"石井学務課長","answer":"もちろん受入れ可能数を決めるときについては、もともとの住民基本台帳上の人数に加えまして、その間の転出入等も考慮した上でクラス数を決定しております。そういった状況を見ますと、今のところは、学区変更といったことではないような形で考えております。","voiceIndex":212,"id":"exchange-052"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"西本委員","kind":"質問","question":"今の状況ですと、こういうことはあり得るかなと思うのです。こういうことが起きたのは、セキュリティが弱かったのでしょうか。今後対策を取るということなのですが、どういう対策が考えられているのか。今、何件というお話もありましたけれど、保育園や幼稚園というのは結構なところで採用していると思うのですけれど、どのぐらい使われているのですか。そういう対処も含めてお願いしたいと思います。","respondent":"染谷保育施設運営課長","answer":"保育園については、学校と契約の事情は異なりまして、区立園においては、全園一括して契約している関係がありますので、今回の対象になった園というのは、残念ながら区立の全園です。","voiceIndex":220,"id":"exchange-053"},{"speaker":"西本委員","kind":"意見","question":"こういうことはあります。クレジットカードもそうです。保育園も業者が入って、パチパチ撮る近所の写真屋がなくなっている状況がありますし、保育園の中でお金のやり取りをするのは困るということもあったので採用しているということなので、できる限りのことをしていただいて、保護者の利便性を考えると、やめる方向に行かれてしまうと困るだろうと思いますので、お願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":222,"id":"exchange-054"},{"speaker":"石田（ち）委員","kind":"質問","question":"対象となるのは学校が２校と幼稚園が４園と保育園が４４園ということで、先ほどもあったと思いますが、漏えい内容というのは氏名と住所と電話番号でしたか。写真自体もということですか。氏名、住所、電話番号は、一部の保護者のものということですか。全部ですか。保育園で言うと全園という話でしたけれど、全保護者というわけではなくて、一部の保護者ということでいいのか、そこを伺いたいと思います。","respondent":"舩木庶務課長、染谷保育施設運営課長","answer":"漏えいの内容につきましては、先ほどご説明しましたとおり住所、電話番号、氏名ということで、写真データの漏えいは確認されておりません。保育園の状況ですが、はいチーズ！フォトは、保護者が登録するような仕組みになっております。登録自体は保護者の任意ですが、現在６割ぐらいの保護者がサイトに登録している状況でございます。","voiceIndex":224,"id":"exchange-055"},{"speaker":"西本委員","kind":"質問","question":"すみません、１点だけ。在園児の人数を教えてもらえますか。何歳児が何人というのが分かれば。","respondent":"佐藤保育事業担当課長","answer":"全体で６８人というのが分かってございまして、歳児ごとの人数につきましては、すみません、今、 手元に資料がございません。","voiceIndex":230,"id":"exchange-056"},{"speaker":"西本委員","kind":"質問","question":"そうしたら、６８人が周りの保育園に行くということですか。希望者になると思いますが、それは枠がそれだけあるという認識でよろしいでしょうか。","respondent":"佐藤保育事業担当課長","answer":"優先転園を希望される方が何名かにもよるとは思いますが、当該箇所にあった園から大体１kmぐらいの範囲内でございましたら、在園されているお子様の数の空きというのは現状で確保することができるという状況です。","voiceIndex":232,"id":"exchange-057"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.29bu.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":44,"characters":52896,"voices":235}},{"id":"r08-20260629-5","meetingId":"r08-m0708","date":"2026年6月29日","dateIso":"2026-06-29","committee":"総務委員会","time":"午前10時00分～午後２時31分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を88件抜き出しています。","hasFullText":false,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"ここの場所ですけれども、いろいろな企業のオフィスがあって、駐車場も各建物に個別についておりました。近隣の企業にそれぞれご挨拶に行ったと思うのですが、その辺の配慮は、もうきちんとできているのでしょうか。ここを工事するのは、解体するだけでも大変だと思うし、造るのでも大変だと思うので、それだけ先にお聞かせください。","respondent":"長尾施設整備課長","answer":"今回の工事に関わる説明会につきましては、議決いただいた後、７月に近隣向けに予定をしております。設計内容につきましても、従前の建物の状況も踏まえて、近隣への視線であるとか、そういった配慮をしながら計画をしております。","voiceIndex":14,"id":"exchange-001"},{"speaker":"須貝委員","kind":"質問","question":"本当に大変な場所だと思うので、近隣とうまく話し合いを継続して、無事に工事が終わるように願っています。もう１点だけ、ソーラーのシステムを導入するというようなことがあったと思うのですが、太陽光発電、あの周りは結構高い建物ばかりですよね。太陽光は、きちんと得られるのですか。その点だけ気になったので、それだけ教えてください。","respondent":"長尾施設整備課長","answer":"設計の段階で太陽光パネルによる十分な発電量を確保できるところを確保しており、枚数については、 屋上で子どもたちが遊べるスペースであるとか、ほかの設備のスペースとかを考えていますので、そこまで枚数はないですけれども、発電には支障のないような計画をしております。","voiceIndex":16,"id":"exchange-002"},{"speaker":"須貝委員","kind":"質問・要望","question":"それならいいのですけれども、ただ、あそこを、一応、商業地になっていて、近隣はいくらでも高い建物を建てられると思うので、一時的に設置したとしても、恒久的にはすごく難しい。隣のビルとは全く隣接するような状況なので、そういうことも考えられてやっていると思いますけれども、無駄にならないようにやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"今の質疑の関連で、太陽光設備の設置位置について、Ｒ階、屋上の左下に並んでいるものが太陽光設備なのかを確認させていただきたいのと、あと、予定価格が各契約の案件で出ておりますけれども、これは公開されているものでしたか。区として、公開されているのであれば、予定価格はどういう価格として、しているということなのかを伺いたいと思います。","respondent":"長尾施設整備課長、廣瀬経理課長","answer":"ソーラーパネルにつきましては、総務委員会資料の中で明示されておりません。今、委員がおっしゃっていたものは緑化の部分になります。ソーラーパネルは塔屋の上に置く予定にしております。予定価格についてのご質問ですけれども、国や自治体の行う工事請負契約は、おおむね共通したルー ルに基づいて予定価格を積算しております。","voiceIndex":19,"id":"exchange-004"},{"speaker":"松本委員","kind":"質問","question":"向きとしては、公園にも面しているので、公園のほうにできるだけ近いように持っていけば、多分、発電がうまくいくのではないかと思うのですけれども、塔屋部分というのは、多分、これ、五反田の公園は南東側ぐらいですか、公園に面するほうに近づけてソーラーパネルを置く計画であれば、比較的発電できるような、今後、再開発とかで周辺にビルが建っても。","respondent":"長尾施設整備課長","answer":"この敷地の中でいうと、最も高い場所で、最も太陽光が差す可能性の高いところになっておりますので、そちらのほうに設置を計画しております。","voiceIndex":22,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"予定していたもの以上の暑さになることもあり得ますので、ぜひ、この案件だけでなく、全ての公共事業において、事故なく安全に進めていただきたいと思っているのですけれども、積算の中で、 どのように熱中症対策を具体化されているのか、現場にはどのような指示をしているのか、そこだけ確認をさせていただきたいと思います。","respondent":"長尾施設整備課長","answer":"一般的に対策として講じられている内容については入ってはいるのですけれども、委員のおっしゃるように、やはり想定を超えてくるような暑さが続くであるとか、あと、工事の内容によっては、戸外で工事している場合などは。","voiceIndex":25,"id":"exchange-006"},{"speaker":"須貝委員","kind":"質問・要望","question":"すみません、委員長、一言だけ言わせてください。先ほど言うことを忘れたのですが、これは２者が入札に参加して１者が辞退ということは、随意契約と全くこれは同じなのですよね。やはりこういうことはできれば避けていただきたいと思います。今回の議案に対しては賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-007"}]},{"id":"topic-02","title":"第７９号議案、鈴ケ森小学校校舎改築電気設備工事請負契約","agenda":"第７９号議案、鈴ケ森小学校校舎改築電気設備工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"今回の入札は、このように出ていて、それに対しては異議はありませんが、これも同じように、２者が入札して１者が辞退、１者が落札したということで、まさに随意契約に見えるのです。こういうことは、経理課のほうで何か改善するという方策はないのでしょうか。それだけ少しお聞かせください。","respondent":"廣瀬経理課長","answer":"今回、結果的に応札していただいたのは１者という形ではありますが、こちらは結果ですので、区としては、随意契約ではないと考えております。ただ、応募しやすい入札条件というところは、引き続き、区の責任として検討して対応していきたいと考えております。","voiceIndex":58,"id":"exchange-008"},{"speaker":"須貝委員","kind":"質問・要望","question":"こういう入札の結果を見ると、区民の方が見たら、どうしてなのだろうという、皆さん、疑問に思ってしまうのです。要は、品川区の事業は受けたくないのかなと、嫌われているのかなと、もっと多くの企業があると思うので、ぜひ改善に向けて努力していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-009"},{"speaker":"のだて委員","kind":"質問","question":"今回、鈴ケ森小学校の工事は、電気設備だけなのですけれども、そういうことになった経緯、理由などを伺いたいと思います。","respondent":"荒木学校施設担当課長","answer":"もう１件が、機械設備工事です。本来であれば、本件の電気設備工事と併せて、今回、定例会に契約議案を提案する予定でございましたが、こちらは、同日５月２９日の開札結果は不調となってあります。","voiceIndex":61,"id":"exchange-010"},{"speaker":"のだて委員","kind":"意見","question":"今回不調になったということで、今、いろいろ工事価格、資材等上がっております。しっかり工事を進められるように、また、建設業者の方も生活が成り立つような価格として提示をしていっていっていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-011"}]},{"id":"topic-03","title":"第８１号議案、キャビネット他の買入れ","agenda":"第８１号議案、キャビネット他の買入れ","exchanges":[{"speaker":"つる副委員長","kind":"質問","question":"すみません、参考までに、こうした物品の購入のときに、当然、納品という作業が出てくるのですけれども、５番のところに、主な買い入れ品目他とあるのですが、輸送費、輸送費という言い方だと大きくなってしまうのですが、納品するときの経費は、ここに含まれているという理解でいいのか、そこだけ教えてください。","respondent":"石井学務課長","answer":"物品については、まず、学校に納品するための費用も計上されているのですけれども、例えば、今、 既存校舎から新校舎のほうに物品を移動する場合とか、そういったこともあります。それはまた別途、 予算で計上しています。","voiceIndex":78,"id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"品目のところで、「他」と書いてありますが、ほかに何があるのかを伺いたいのと、あと、すみません、基本的なことで、一般需用費というのはどういうものを指すのかを伺いたいと思います。","respondent":"石井学務課長","answer":"今回は、この２つの節を併合した上で契約を行っているところです。","voiceIndex":80,"id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"ここも１の買入物品のところに、「荏原第六中学校他」と書いてありますけれども、ほかの学校も対象として入っているのでしょうか。それならば、記載されていないので、そこら辺、少し教えてください。","respondent":"石井学務課長","answer":"今回につきましては、老朽物品の取替えということで、荏原第六中学校のほか、戸越小学校、荏原第一中学校、山中小学校、宮前小学校、小山台小学校など、主に平成の真ん中ぐらいに購入した物品の老朽取替を対象としています。","voiceIndex":96,"id":"exchange-014"},{"speaker":"のだて委員","kind":"質問","question":"今回、回転釜ですとか消毒保管庫設備は、日本調理機株式会社製の機器にすることになったということで、これがいろいろ制約があったということなのですが、そこをもう少し詳しく、どのような制約があったのか、決定の経過を伺いたいと思います。","respondent":"石井学務課長","answer":"ガスを使うものですので、既存のガス管にきちんと設置が可能であるですとか、そういった今の調理現場の実情に合ったものが、こちらの物品の指定となったというようなところです。","voiceIndex":99,"id":"exchange-015"}]},{"id":"topic-04","title":"第７６号議案、電線共同溝等工事（特別区道Ⅰ－２４１号）委託契約","agenda":"第７６号議案、電線共同溝等工事（特別区道Ⅰ－２４１号）委託契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"ここの場所の電柱を含めて無電柱化推進ということなのですが、ほかにはもっとたくさんあると思うのです。ここの道路に関して、別にそんなに狭いというわけでもなし、景観がよくなるということでもなし、なぜここがこういうふうに指定されたのでしょうか。理由を教えてください。","respondent":"森道路課長","answer":"本路線につきましては、令和５年度に改定しました無電柱化推進計画の中で位置づけをしております。","voiceIndex":115,"id":"exchange-016"},{"speaker":"須貝委員","kind":"質問","question":"もう１点、そのままお尋ねします。今、林試の森の防災避難所拠点ということですが、そうすると、 下のほうに書いてある１３番、⑤がありますけれども、ここの通り、ずっと武蔵小山に向かっていく通りも電柱等々あると思うのですけれども、そちらも同じ理屈で無電柱化にやっていくということですか。教えてください。","respondent":"森道路課長","answer":"目黒区でここをやるということはまだ聞いていないですけれども、そういった情報交換をしながらやっていきたいということと、それから、林試の森公園の水車門の東側道路と呼んでいるのですが、今、 昔の財務省の庁舎があったところについても拡幅の計画がございまして。","voiceIndex":117,"id":"exchange-017"},{"speaker":"のだて委員","kind":"質問","question":"今回は随意契約ということでやられていますけれども、随意契約にした理由を伺いたいと思います。","respondent":"森道路課長","answer":"今回の部分につきましては、ＮＴＴともお話をしておりましたけれども、 東京電力のほうでしっかりやっていくというところもありますし、実際に東京電力の電柱のほうが多いというところもありますので、東電タウンプランニング株式会社に随意契約という形で進めているところです。","voiceIndex":120,"id":"exchange-018"}]},{"id":"topic-05","title":"第７７号議案、東大井公園改修工事請負契約","agenda":"第７７号議案、東大井公園改修工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"今、いろいろ防災のほうでも話が出ていると思うのですが、公園改修工事をするときに、井戸を造ったり、災害に備えて様々な対応をしていくと思っているのですが、すみません、図面、私は全部見ていないので、図面は分からないのですが、ここもそういう対応をされるのでしょうか。教えてください。","respondent":"大友公園課長","answer":"新たに整備する防災施設といたしましては、下水道直結のマンホールトイレ、また、かまどベンチを設置する予定です。こちらにつきましては、既に１００トンの防火貯水槽が整備されているということで、井戸・防火貯水槽の設置予定はございません。","voiceIndex":136,"id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"よく聞こえなかったのですけれども、井戸は設置されないということですか。","respondent":"大友公園課長","answer":"ここの公園については井戸は設置はしません。","voiceIndex":138,"id":"exchange-020"},{"speaker":"須貝委員","kind":"質問","question":"少し意見だけ言わせていただきます。こういう折に、それぞれの拠点として、やはり井戸水を確保するというのは自治体の義務だと思うのです。それに対して、やはりきちんと対応すべきだと思うし、やっていかなくてはいけない。区民の生命、命を守るためにやっていかなければならないことだと思うのですが、これからそういう対応をしていくような考えはおありなのでしょうか、教えてください。","respondent":"大友公園課長","answer":"そのため機能の重複となるところがありますので、本公園には設置しないというところではありますけれども、公園を新たに設置する際とか、既存の公園につきましても、井戸の確保に視点は重きを置いて整備を進めていきたいと考えているところです。","voiceIndex":140,"id":"exchange-021"},{"speaker":"のだて委員","kind":"質問","question":"今回、修景施設の中で、グリーンインフラが３か所あるのですけれども、どういうものなのかということと、あと、ミスト施設も２基設置されるということで、これ、多分、全ての公園に設置するという方針ではないと思うのですけれども、どういうところに設置しているのか。今回設置するとなった経緯ですとか、ミスト施設を設置する基準とか考え方があったら伺いたいと思います。","respondent":"大友公園課長","answer":"ミストについてですけれども、ミストの設置は全体の方針での考えは、現時点でのお示しはございません。","voiceIndex":142,"id":"exchange-022"},{"speaker":"つる副委員長","kind":"質問・要望","question":"場合によっては、そうした障害をお持ちのお子さんがここの遊具で遊びたいとなるときに、十分な移動その公園に横づけをして、乗り降りも含めてやれるようなところまで、整備していただきたい。ほかの所管等々を含めて、イメージしながら、ここにインクルーシブ遊具というか、そういう公園となっていくかどうかというところを教えてください。","respondent":"大友公園課長","answer":"今回、インクルーシブの導入の背景からご説明させていただきたいと思います。","voiceIndex":144,"id":"exchange-023"},{"speaker":"石田（秀）委員長","kind":"質問","question":"ほかに。１点だけ、私からも。先ほど、須貝委員の話なのですが、私も第１回定例会で質問をさせていただいた井戸の件なのだけれども、１８０ｍで２００か所、２００ｍで１８０か所だったか、忘れてしまったのだけれども、それぐらい必要だと思っていますと質問しました。だから、よかったなと思っていたのです。ですから、非常にそういう意味では、やっていただいているのだなと思ったのです。","respondent":"大友公園課長","answer":"この井戸の全体計画につきましては、今年度から全体の区の中の井戸を考えていくということで、防災課および地域活動課と、場所の選定とか、そういうような必要性というところも踏まえ検討しているところです。","voiceIndex":146,"id":"exchange-024"}]},{"id":"topic-06","title":"第７８号議案、西大井広場公園（北側）改修等工事請負契約","agenda":"第７８号議案、西大井広場公園（北側）改修等工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"ここの場所は、多くの木が、中木ですか、たくさんあると思うのですが、そこはほとんど伐採するのですか。かなり緑が多い場所だと思うのですが、その辺について教えてください。","respondent":"大友公園課長","answer":"既存の公園樹木については、多くの樹木を伐採する形となります。その理由といたしましてですけれども、既存の園内、勾配が大きく駐輪場を整備する観点からも、勾配をならすため、大幅な切土を実施します。","voiceIndex":161,"id":"exchange-025"},{"speaker":"須貝委員","kind":"質問・要望","question":"本当にきれいな樹木が生えて緑が美しい場所だと思うので、今のお話ですと、ほとんど伐採されるということですけれども、今の時代に、緑が１回そこで失われるというのは、かなり大きなインパクトがあると思います。本当は、できれば、できるだけ残してほしいと思うのですけれども、実際は、ここを使い勝手の面で、ほとんど、大半、１回伐採して、新たに植え替えるということで、非常に残念です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":163,"id":"exchange-026"},{"speaker":"こしば委員","kind":"質問・要望","question":"私も西大井駅をよく使わせてもらうのですけれども、今、３階建ての駐輪場の改修に合わせてということのご説明がありました。スケジュールについて教えていただきたいと思います。改修の前に、今回議案に上がっている駐輪場を建設して、そこから３階建てのほうを建て直していくのかどうか、その辺りを教えていただきたいと思います。","respondent":"大友公園課長","answer":"本件、現在、契約手続等々をこのようにお伝えして進めているところではありますけれども、建屋の駐輪場も、別途、改修工事を実施する予定です。","voiceIndex":164,"id":"exchange-027"},{"speaker":"こしば委員","kind":"確認","question":"確認ですけれども、仮設でここの公園に２００台のという答弁と認識してしまってよろしいですか。あくまでも改修で３階の部分を隣の駐輪場にといいますか、そこで利用してもらう。あくまでも仮設での対応という認識でいいですか。","respondent":"大友公園課長","answer":"建屋の工事で駐輪場が使えなくなるというところを踏まえての駐輪場は、一時的な仮設という形のものにはなります。","voiceIndex":166,"id":"exchange-028"},{"speaker":"松永委員","kind":"質問","question":"整備内容のところなのですけれども、トイレについてですが、こちらは、今、ステンレス製の１人用の和式の便所があると思うのですけれども、こちらは全部取っ払って、また新しい誰でもトイレのような形になるのか、その辺を伺いたいと思います。","respondent":"大友公園課長","answer":"その新設内容が、男性用のトイレとして、大便器、小便器、あと女性用トイレとして、洋式が１つ。バリアフリートイレを１基という形で設けることで計画をしています。","voiceIndex":168,"id":"exchange-029"},{"speaker":"のだて委員","kind":"質問・要望","question":"確認なのですけれども、先ほど、駐輪場、今回の１８１台の普通自転車と大型２０台の駐輪場が仮設ということなのか、そこを確認させていただきたいと思います。それで、やはり樹木がたくさんあって、住民の皆さんにも親しまれてきた場所だと思うので、近隣の住民との合意というか、調整はどうなっているのか伺いたいと思います。","respondent":"大友公園課長","answer":"樹木についてですけれども、本数としてですが、具体的には、今現在、高木が１９２本あります。中木が約１００本あります。それが改修後につきましては、高木が１０２本、そのうち移植が １６本です。中木が１１２本になる予定です。","voiceIndex":171,"id":"exchange-030"},{"speaker":"のだて委員","kind":"意見","question":"この樹木のところは、結構、高木が９０本、移設が１６本ありますけれども、切られる本数が多いということで、やはりそこは住民の皆さんも心配されるところだと思いますので、しっかり説明していただきたいと思います。住民の納得を得ていただければなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":173,"id":"exchange-031"},{"speaker":"つる副委員長","kind":"確認","question":"既存だと、結構、日陰という部分では確保されていたりということもあるのですけれども、それは木が成長するとともに、あとは近隣住民の代表の声として今ありましたけれども、葉っぱが隣地のほうに来ないという、そういった作業は当然やっていただきながらですが、その辺の整合性というところで、それに耐え得るような今の状況になっているのかどうかを、涼しさの確保は、東屋とか。","respondent":"大友公園課長","answer":"樹木の適正な管理におきまして、樹形でいくと、この１０２本、 また、今回、駐輪場も整備するというところにおきましては、木陰確保ができ、緑道を散策する上で木陰の中を楽しんで散策をいただけるような計画になるのかなと考えています。","voiceIndex":174,"id":"exchange-032"}]},{"id":"topic-07","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"すみません、この変更内容ですが、今回、インフレスライドに対する契約が変更された額と、それから廃棄物運搬処分の変更に対する額を、大まかでいいから教えてください。","respondent":"大友公園課長","answer":"インフレスライド分として約７１０万円、廃棄物運搬処分の変更といたしまして約１８０万円のそれぞれ増となっているところです。","voiceIndex":189,"id":"exchange-033"},{"speaker":"中塚委員","kind":"意見","question":"変更内容の２つ目の廃棄物運搬処分の変更ということですけれども、廃棄物とは何なのか、自然由来のものなのか、それとも掘っているときに何か人工物があったのか、この廃棄物は何かご説明いただきたいと思います。","respondent":"大友公園課長","answer":"子供の森公園、目黒川に近いため、因果関係は証明できないところはありますけれども、古い目黒川の護岸構造物や、子供の森公園となる前の従前の建物の敷地で使われていた基礎など、考えられるところはあるかと思うのですけれども。","voiceIndex":192,"id":"exchange-034"},{"speaker":"中塚委員","kind":"意見","question":"コンクリート殻ということで、不明だということですけれども、ここの公園、相当古いので、造った当時のことを知っている職員はもうほとんどいないと思いますけれども、後から取得した、これ、もともと東京都だったのか、よく分からないけれども、今、取得している品川区が殻の処理までするということも何だかなというふうにどうしてもなってしまうのですよね。","respondent":"大友公園課長","answer":"やはり古い年代のものというところもあり、調査した結果というところで、調査する前は本当に何も分からないコンクリート殻だったのですけれども、いろいろな目黒川の護岸の構造がここまで来ていたのではないかとか、様々な調査をした結果、やはり不明というところが結果です。","voiceIndex":194,"id":"exchange-035"},{"speaker":"須貝委員","kind":"質問","question":"そこに土地があったから、ここに分室を造るということになったのでしょうが、ほかになかったのですか。このように、見た目だと、図面上だと、非常に使い勝手が悪いように思うのですが、せっかく造るなら、もう少し四角い建物を造られたほうがよかったと思うのですが、やはり適当な場所がなかったことと、今急いで造らなければいけないということで、このような場所を選定したのでしょうか。","respondent":"立木品川区清掃事務所長","answer":"児童相談所の整備にあわせまして、子供の森公園に少し変更がございました。その後、第一三共から土地の寄附がございまして、その土地と合わせまして一体的に整備をするということで、公園の形、それから児童相談所の位置等を勘案した結果、この位置に。","voiceIndex":202,"id":"exchange-036"},{"speaker":"須貝委員","kind":"質問","question":"もう１点だけ。今、車両の出入りですけれども、今までのほうがすごく出入りしやすかったと思うのです。ほかの車両にも迷惑をかけなくて。今度の場合には、結構、多いときは、ほかの車両が目の前の道路を本当にたくさん通って、かえって危ないような気もするのですが、その辺は大丈夫なのですか。","respondent":"立木品川区清掃事務所長","answer":"車両の出入りに関しましては、これは毎朝、こちらに限らず、どこの事務所もそうなのですが、車両が出る際には、必ず職員が複数の箇所に立ちまして、交通の流れを見ながら安全に出庫させるという形でやっておりますので、新しい分室になりましても。","voiceIndex":204,"id":"exchange-037"},{"speaker":"のだて委員","kind":"質問","question":"ここは隣に子供の森公園がありますので、子どもたちの出入りもあると思います。工事の安全性をしっかり確保してほしいと思うのですけれども、その辺りを伺いたいと思います。","respondent":"長尾施設整備課長","answer":"今回の新築工事に当たりましては、当然、安全管理には十分配慮して、公園の利用にも支障がないように努めてまいりたいと思います。","voiceIndex":206,"id":"exchange-038"}]},{"id":"topic-08","title":"第６０号議案、品川区特別区税条例の一部を改正する条例","agenda":"第６０号議案、品川区特別区税条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"それと、年金受給者の扶養親族の申告書のところでは、（２）番のところですけれども、今回、申告書の提出が義務化されるこということで、これは初めてのことではないかと思うのですが、伺いたいのと、今回、今までも乖離がある部分はあったと思うのですが、なぜ義務化するのかというところを伺いたいと思います。全体的に、区民にとってはどういう影響があるのかというところを各項目で伺いたいと思います。","respondent":"初貝税務課長","answer":"公的年金のところのものですけれども、こちらは、もともとは国の制度になりますけれども、国のほうで、今回、２０５万円以下の方に関しましては、一律で、基礎控除が上がった関係で、 扶養控除等の扶養親族等の申告書の提出はするまでもなく。","voiceIndex":240,"id":"exchange-039"},{"speaker":"のだて委員","kind":"質問","question":"扶養親族の申告のところは、結局、なぜ義務化するのかということで、乖離があり、対応するためだということだったのですけれども、もともと自己申告というか、自分で申請するかどうかというところだったと思うのですが、今回、義務化されるということで、なぜなのかなということがあるので、もう少し詳しく説明いただけるところがあれば伺いたいと思います。取りあえず。","respondent":"初貝税務課長","answer":"（２）の公的年金などの受給者に関する義務ですけれども、こちらは少し説明が重複してしまいますけれども、そもそも税金なので、きちんとしたご自身の状況を示していただいて、それに対して、我々が賦課していくというものです。","voiceIndex":242,"id":"exchange-040"},{"speaker":"中塚委員","kind":"質問・要望","question":"私は、この姿勢ではいけないと思います。一地方自治体として、非核平和都市品川宣言を持つ自治体として、 これは明確に反対をすべきだと私は思います。これは誰に聞いたらいいのかよく分かりませんけれども、ｉＰａｄは手で拡大できるではないですか。特にこういう小さい字は拡大しないと見えないので、少し工夫していただきたいと思うのですけれども、その２点、伺いたいと思います。","respondent":"初貝税務課長","answer":"１点目のところですけれども、こちらの国が定めているものになりますので、また、先ほど委員からご指摘あった点に関しましても、国のほうで定めているものですので、区としては、その内容等々に関して判断する立場にはないと考えております。","voiceIndex":244,"id":"exchange-041"},{"speaker":"中塚委員","kind":"意見","question":"解像度のほうは、ひとつよろしくお願いいたします。なのに、この税制改正になると、国によって判断すべきもので、区が示すものではないと、 この姿勢は明らかな矛盾だと思います。恒久平和に対して、区自らが姿勢を示すべきときに、こういう品川区の姿勢は改めるべきだと指摘しておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":246,"id":"exchange-042"},{"speaker":"須貝委員","kind":"質問","question":"何点かあるのですが、まず、公益信託の見直しに伴う所得税法の規定の見直しです。これは、メリットとして、自治体が寄附を受けやすいような仕組みに変わるということなのでしょうか。最初の１点だけ、公益信託の見直しは、メリットとして、自治体が寄附を受けやすくするために創設されたのかと、そうなると、区民感情としても、少しいかがなものかなと思うのですが、その辺、ご見解をお聞かせください。","respondent":"初貝税務課長","answer":"（１）の公益信託の見直しに伴う所得税の改正に関してです。こちらに関しましては、旧公益信託が、 いわゆる認定特定公益信託ですので、そちらは、結論から申し上げますと、自治体に寄附を多くするという制度ではない形になります。","voiceIndex":247,"id":"exchange-043"},{"speaker":"須貝委員","kind":"意見","question":"なかなか今回、字は拡大すれば大きくはなるのだろうけれども、非常に分かりにくい制度だったと思うので、こういうときはぜひ企画経営部長が皆さんにより分かりやすいようにお伝えしてくれると、 我々も安心して審査できるのではないかと思いました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":249,"id":"exchange-044"},{"speaker":"つる副委員長","kind":"質問","question":"そういうところを含めて見たときに、先ほどご答弁があったように、区政においてどうこうするということではないということは思うのですけれども、１点だけ、これまでの２.１％の中で、大半を復興債の償還に充てていたという中で、でも、逆に今度、１％をそういうふうに変えるわけですから、主でなおかつ１０年延長でという、その償還の期間を延ばして。","respondent":"初貝税務課長","answer":"そうですね、今ご指摘いただきました償還等々の話です。今、私の手元に今回の税制改正があったもとの、ここのところ等々の件に関しては、今、手元になくてお答えできないのですけれども、 いずれにしても、国のほうでしっかりと議論されているものと認識しております。","voiceIndex":250,"id":"exchange-045"},{"speaker":"のだて委員","kind":"意見","question":"反対です。防衛特別所得税以外は、基本的に区民にとってプラスになるものだと思います。しかし、 防衛特別所得税の軍事費拡大の原資にするため、どんどん拡大していけば戦争に近づいていくことにもなります。今回の改正は、それを具体化するものですので、反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":257,"id":"exchange-046"},{"speaker":"中塚委員","kind":"意見","question":"必要な変更もありますが、防衛特別所得税の創設ということで、反対です。もう一言、やはり東日本大震災の復興の財源を使って軍事費の増税をする、このことに品川区は反対をすべきだと思います。国の議論に委ねるというその姿勢は、とても品川区民の理解を得られないと改めて指摘しておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":260,"id":"exchange-047"}]},{"id":"topic-09","title":"第６１号議案、品川区附属機関の構成員の報酬および費用弁償に関する条例の一部を改 正する条例","agenda":"第６１号議案、品川区附属機関の構成員の報酬および費用弁償に関する条例の一部を改 正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今、いじめ対策委員会が実際に調査などをしている件数は何件なのか伺いたいと思います。今回、委員長が３万円、委員が２万３,０００円ということで、この金額設定にした理由があれば伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":266,"id":"exchange-048"},{"speaker":"のだて委員","kind":"質問・要望","question":"ガイドラインも、いろいろ会議に出るだけではなくて、調査とか、実際、ヒアリングしたりとか、そういったところもありますので、そういったところもしっかり加味をして設定していくことが必要だというような中身だったと思うのですけれども、今回、そうしたことも加味した設定になっているのかというところを最後に確認させていただきたいと思います。","respondent":"中西総務課長","answer":"委員ご指摘のとおり、確かにガイドラインに書かれております３つの類型等々あります。そういった部分を含めて報酬を設定しているものです。","voiceIndex":271,"id":"exchange-049"},{"speaker":"中塚委員","kind":"意見","question":"増額ということなので、賛成をしたいと思いますが、担っている職責を率直に思うと、もっと引き上げてもいいという議論が起きるべきだと私は思います。増額なので賛成はいたしますけれども、現状で職責に対して妥当だとは私は思いません。もっと引き続き、弁護士の方々と意見も聞きながら、今後、 議論を進めていただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":281,"id":"exchange-050"}]},{"id":"topic-10","title":"令和８年陳情第２７号、税法上の障害者控除を、「要介 護２」認知症の者にも適用するよう求める陳情","agenda":"令和８年陳情第２７号、税法上の障害者控除を、「要介 護２」認知症の者にも適用するよう求める陳情","exchanges":[{"speaker":"こしば委員","kind":"質問・要望","question":"確認をさせていただきたいのですけれども、冒頭で何か所か分からないところがありました。障害者控除は、本来であれば、文字どおり、障害者の手帳を持っている方が対象になると思うのですけれども、 要介護の方を対象とすることの法的な根拠があるのかないのか。先ほど、法的根拠があって独自にできないような話をされていたような気がしたのですけれども、その辺りをもう一度教えてもらっていいですか。","respondent":"初貝税務課長","answer":"先ほどの説明と少し重複してしまう部分はあるかと思いますけれども、まず、所得税法と地方税法の中で、控除対象として障害者ということが列挙されている中で、１つ、それは基本的には手帳の交付を受けている、そういったところになるのですけれども、それ以外のところで、先ほど。","voiceIndex":290,"id":"exchange-051"},{"speaker":"こしば委員","kind":"質問","question":"そうすると、結局、自治体の判断に委ねるところが多いという認識でよろしいですか。","respondent":"初貝税務課長","answer":"それ以外のところ、要は、障害者というところに関しては、それ自体を障害者控除の対象の範囲として拡大することは各自治体には認められていない、そういったことになっております。","voiceIndex":292,"id":"exchange-052"},{"speaker":"こしば委員","kind":"質問","question":"そうしますと、既にほかの自治体、先ほどもおっしゃっていましたけれども、 要介護のレベルも大分、認知症の進み具合によるとは思うのですけれども、その辺り、今般、比較をされたですけれども、比較をした上で、例えば、この陳情にあるとおり、要介護２の方を対象とした場合の税額控除、おおよそどのくらいのものと見積もりをされているのか教えていただきたいと思います。","respondent":"初貝税務課長","answer":"例えば、かなり多く見積もってでございますけれども、その方たちの半分が認定書を取得して、全員、一般の障害者控除を受けた場合ですけれども、税金、区政という意味では、約１,９００万円程度の税収が減収というような形になるということです。","voiceIndex":294,"id":"exchange-053"},{"speaker":"こしば委員","kind":"質問","question":"分かりました。先ほど、１,９００万円ほどの税収の減があるということをお聞きいたしました。その辺り、必ずしも例えば、認知レベルと、多分、要介護が進むイコール認知症が進んでいくとは、 それはイコールの関係ではないわけではないですか。その辺り、まさに分析をされて、先ほど、幅広く考えていきたいという話がありましたけれども、認知症との関連性のようなものを教えていただければと思います。","respondent":"佐藤高齢者福祉課長","answer":"したがいまして、冒頭ご説明したとおりでして、そういったところを詳細にこれから検討いたしまして、税務課等々、関係課と調整した上で検討していきたいと考えております。","voiceIndex":296,"id":"exchange-054"},{"speaker":"こしば委員","kind":"質問・要望","question":"要介護だけでなく、また認知症のレベルを、そういうものを、今、複合的に全体観をもって検討されているということですので、ぜひそれは進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":298,"id":"exchange-055"},{"speaker":"中塚委員","kind":"質問","question":"冒頭の説明で、高齢福祉課長から、対象を広げる検討をしていきたいという説明がありました。その上で、少し詳しく伺いたいと思うのですけれども、まず、基準について見直す必要があると判断したと。その上で、対象を広げることを検討したいということですので、いつからの実施を目指しているのか、 対象はどこまで広げようと思っているのか、現状のお考えを伺いたいと思います。","respondent":"佐藤高齢者福祉課長","answer":"そういったところから見ますと、品川区が要介護３以上と置いているところが、これはこれとして税法の規定に沿った形でやってきたところではあるのですけれども、周辺自治体と比べてどうなのかというところは、課題があると認識しているところです。","voiceIndex":299,"id":"exchange-056"},{"speaker":"中塚委員","kind":"質問・要望","question":"いつからどこまで実施について、今後検討したいということですけれども、ぜひ来年の４月から、つまり、来年度予算に反映していただきたいということと、杉並区の事例が陳情書にもありますけれども、 要支援以上を対象とするというふうにしていただきたいと思いますが、最後にいかがでしょうか。","respondent":"佐藤高齢者福祉課長","answer":"改めてのご質問ですけれども、区の様々な事業に関しては、毎年事務事業評価等を通じて、その時点でどうなのかというところは、これまでも検討してきたところです。","voiceIndex":301,"id":"exchange-057"},{"speaker":"のだて委員","kind":"質問・要望","question":"言っておきたいのは、資料をきちんとつけていただきたかったです。障害者控除の現状とかが分かるようにしていただきたい、これは今後お願いしたいと思います。現状を伺いたいのですけれども、今、６５歳以上で要介護１から５、あと、要支援の方も分かれば、 人数をそれぞれ伺いたいのと、あと、ここ３年の普通障害者控除と特別障害者控除の認定数をそれぞれ伺います。","respondent":"佐藤高齢者福祉課長、初貝税務課長","answer":"障害者控除対象者認定書の交付件数ですけれども、申し訳ありません、直近の令和７年度の数でお示ししますと、合計１６２件で、障害者が５１件、特別障害者は１１１件です。例年、この程度の数で推移しているという認識です。障害者控除に係る人数ですけれども、一般障害者控除を受けられている方の合計が、おおよそ令和７年度分の数字になりますけれども、一般のほうが約３,６００人、特別障害のほうが約 ２,４００名程度です。","voiceIndex":303,"id":"exchange-058"},{"speaker":"のだて委員","kind":"質問・要望","question":"これはぜひ認定する介護認定を受ける際とかに、こうした制度があると、対象になる方にはぜひお知らせをしていただきたい、申請書などを送っていただきたいと思いますが、それを１点伺いたいと思います。それで今回、拡大されるということなので、それはよかったなと思っています。分かれば、２３区の中で要介護２以下を対象にしている区がどれだけあるのかを伺えればと思います。","respondent":"佐藤高齢者福祉課長","answer":"２点お伺いいただいたと思います。","voiceIndex":306,"id":"exchange-059"},{"speaker":"のだて委員","kind":"質問・要望","question":"これは陳情の中で、やはり経済的負担のことも書かれております。いろいろ通院費用がかかったりですとか、また、トイレにタオルが詰まってしまって、取り替えに３０万円以上の出費が出てしまったということから見ても、こうした支援をしていくことが必要だと思いますので、ぜひ広く利用できるように、対象も拡大していっていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":308,"id":"exchange-060"},{"speaker":"松本委員","kind":"意見","question":"これまでのご答弁で、１個気になったのですが税法に従ってやっているのだというふうなお答えがあったかと思うのです。その状況の中で、先ほどのご答弁では、これに従って要介護３をこれまで認定の基準にしていたというふうにおっしゃっていたのですけれども、私はここが少しつながりが読めなくて、税法のどこを根拠として、今の品川区の基準がうまれたのかというところをもう一度ご説明いただけますか。","respondent":"佐藤高齢者福祉課長","answer":"委員から冒頭におっしゃっていただきましたけれども、要介護の認定と障害者の手帳の認定では、大きく異なるのは、やはり障害者の認定は、障害が永続的にどうしても続いてしまうということと、 介護保険自体が自立支援を１つの目的としている関係がありまして、そうすると。","voiceIndex":309,"id":"exchange-061"},{"speaker":"須貝委員","kind":"質問","question":"すみません、何度も念を押して恐縮なのですが、この度の陳情に対する考え方です。区としては、この方向、どの程度の介護度か云々はあるけれども、時期的なものは、またいつからということもあると思うのです。この陳情に対しては、そういう方向で進んでいくと、こういうふうにお願いされていることに関しては、そのとおりだというふうな考え方で我々は受け止めていいのでしょうか。教えてください。","respondent":"佐藤高齢者福祉課長","answer":"私どものほうで発行している障害者控除対象者認定書の発行基準について、現在の要介護３から拡大していくということをこれから検討していくというところで、冒頭、税務課長からの説明もありましたとおりで。","voiceIndex":312,"id":"exchange-062"},{"speaker":"つる副委員長","kind":"質問・要望","question":"少し聞き漏らしたかもしれないですが、各委員の質疑を伺って分かったことで、確認をさせていただきたいところがあって、現状の控除、障害者控除というところで、さっき、一般が３,６００人、特別が２,４００人とあったのですが、これは、ここで言うところの障害者対象者認定書の数ではなくてという理解でいいか、そこをまず教えていただきたいことが１つ。","respondent":"初貝税務課長","answer":"今、委員ご指摘の、それぞれ認定のところですけれども、一般と障害の中に、認定書をもって障害者控除を受けている方が、どれくらいかということで、大体おおよそなのですけれども、４０から５０名程度の方が認定書をもって障害者控除を受けているというようなところです。","voiceIndex":315,"id":"exchange-063"},{"speaker":"つる副委員長","kind":"質問・要望","question":"冒頭にもありましたけれども、今回、陳情では、要介護２、認知症ということで、ある意味で、 フォーカスしてあるわけですが、冒頭のご説明でもありましたけれども、より他区の状況を見ても、幅広い視野、視点に立った検討が、ある意味では、必要ではないかということは、改めて、ほかの区の状況ですとか、冒頭の説明を伺っていて思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":317,"id":"exchange-064"},{"speaker":"松永委員","kind":"確認","question":"本日結論を出すで、趣旨採択でお願いいたします。理由といたしましては、先ほどの質疑でもありましたが、まず、東京２３区の大部分の自治体が既に認知症の実態を考慮して、要介護２以下の方にも適用しているということを確認できました。そうしたことも踏まえて、この陳情の趣旨については賛同し、今回、趣旨採択という形にさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":320,"id":"exchange-065"},{"speaker":"つる副委員長","kind":"確認","question":"本日結論を出すで、趣旨採択でいきたいと思います。先ほど質疑の中でも確認させていただきました。陳情については、要介護２で認知症ということで明記されていたかと思いますけれども、他区の状況、また、冒頭の説明を含めたその他の質疑を含めて、 より視野の広い検討をしていく必要性もあるのではないかというところも含めて、趣旨採択という形にしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":322,"id":"exchange-066"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択です。控除を受けられる障害者と同程度の状況の高齢者の方がいるのに控除を受けられないというのは不公平だと思います。議会からもぜひ後押しして進めていきたいと思いますので、採択していきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":323,"id":"exchange-067"},{"speaker":"松本委員","kind":"意見","question":"採択ではなく趣旨とする理由といたしましては、本陳情は、要介護２で認知症ということで、これを通してしまう、採択と申し上げてしまうと、逆に、要介護１の方で認知症が進んでいらっしゃって、障害者控除の厚労省の基準、厚労省の通知とかを見て、要介護１で障害者控除の対象となり得るような方について、我々が議会として排除してしまったというふうな結論になりかねないというところを考えますと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":324,"id":"exchange-068"},{"speaker":"須貝委員","kind":"意見","question":"本日結論を出すということと、採択でお願いします。弱者を生まない品川区政、このような適用は見直す時期に来ているかと思います。この適用を早く改善して、そして、本当に温かい福祉に強い品川区になってほしいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":325,"id":"exchange-069"},{"speaker":"中塚委員","kind":"質問・要望","question":"区も対象を広げていきたいと述べておりますので、一刻も早く実施してほしいし、対象も広げてほしいと思うので、採択というふうにも心は揺れたのですけれども、私自身は、ぜひ要支援以上に広げていただきたいというのは質疑の中でも述べたとおりでありまして、陳情そのものが要介護２、認知症にもということなので、現状、区が後れている中で、後発組が要介護２で終わってはいけないと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":326,"id":"exchange-070"},{"speaker":"のだて委員","kind":"質問・要望","question":"私は採択として進めていただきたいと思いますが、皆さん、もし全会一致で趣旨採択できるのであれば、そのほうが区民の皆さんにも歓迎されると思いますので、趣旨採択に合わせるかたちでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":329,"id":"exchange-071"},{"speaker":"須貝委員","kind":"意見","question":"私も同様で、本来は採択でお願いしたいところですが、皆さん、全会一致となるならば、趣旨採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":330,"id":"exchange-072"}]},{"id":"topic-11","title":"令和８年陳情第１５号 昇降機が最新基準（平成２１年・２６年告示）に適合していな い旨のシールを乗り場および籠内に掲示することを求める陳情","agenda":"令和８年陳情第１５号 昇降機が最新基準（平成２１年・２６年告示）に適合していな い旨のシールを乗り場および籠内に掲示することを求める陳情","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"いろいろ聞くと、自転車を置いて上に上がるこの議会棟の、ふだん我々がよく使っているエレベーターには貼っていないという話を聞いて、私も今日、朝、見てきたのですけれども、そもそも貼ってあるところも、私、よく見ていないので、何が貼られていて、何が貼られていないのか、私自身は認識はできなかったのですけれども、 少しそういう話も聞いたので、議会棟がどうなのかということも含めて、区の建物で。","respondent":"長尾施設整備課長","answer":"ご説明しました地震時管制運転装置に関して、あと、戸開走行保護装置、この２つの装置がついているものは、それぞれ国交省が任意の表示制度としてシールを貼れるような制度を準備しております。","voiceIndex":337,"id":"exchange-073"},{"speaker":"中塚委員","kind":"質問","question":"知りたいという方がいるのは事実ですから、それはきちんと丁寧な説明、知る権利を尊重するということはもちろん必要だと思いますけれども、今回は、エレベーターに限った陳情ではありますけれども、いわゆる防災対策全体を考えていったときに、エレベーターであれ、建物であれ、様々な基準に対して、造ったときは適法だったけれども、基準が上がることによって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":339,"id":"exchange-074"},{"speaker":"のだて委員","kind":"質問・要望","question":"先ほども言いましたけれども、資料をぜひ陳情にもつけていただきたい。その上で現状の確認なのですけれども、区有施設で既存不適格の昇降機が８０基程度あるということで、陳情の３ページ目のリストを見ると、欄が全部で６９行あるので、既存不適格のエレベーターは６９基あるということだと思うのですが、区の施設で、このリスト以外にも既存不適格が約１０基あるということでよいのか伺いたいと思います。","respondent":"長尾施設整備課長","answer":"それが１つ大きな課題であると感じておりまして、そのような状況もありますので、 区のほうで改修の計画を定めたところで、なかなか思うように順番どおりに進んでいくという確保が難しいような状況もあります。","voiceIndex":340,"id":"exchange-075"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、既存不適格のエレベーターは約８０基あるということで、先ほどは、シールを貼っていないものが８０基ということだったのですが、そうすると、適合しているものは基本的にシールが貼ってあるということなのかを確認させていただきたいのと、実際、議会棟のところはシールは貼っていないですよね。","respondent":"長尾施設整備課長","answer":"エレベーターメーカーの状況につきましては、委員おっしゃるように、技術者不足といったところは１つ大きな要因になっているかと思います。","voiceIndex":342,"id":"exchange-076"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういう事例もあるということで、まずは改修をしっかり進めていただきたいと思いますし、やはりなかなかスケジュールを示すのは難しいということですけれども、やはり戸開走行保護装置ですとか、 地震時管制運転装置ですとかというのは、やはり事故があって、そういったものを設置する義務が課せられておりますので、安全面を考えても、できるだけ早く設置をしていくことが必要だと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":344,"id":"exchange-077"},{"speaker":"須貝委員","kind":"意見","question":"今回、エレベーターのことですが、国交省の説明では、日本のエレベーター事故率は世界最低のレベルであり、年に１回の法定検査が義務づけられている。ですが、後づけするにも相当日数がかかるという現状で、日本全国でも１００万台のエレベーターが、 そのような状況にあるという現状もありますが、引き続き、品川区としても、少しずつでも改善するために対応してほしいと思います。意見だけで終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":345,"id":"exchange-078"},{"speaker":"松永委員","kind":"意見","question":"本日結論を出す、不採択でお願いいたします。理由は、対象となる既存不適格の昇降機については、定期検査や適切なメンテナンスによって一定の安全性が継続されているということと、もう１つは、国のマーク表示制度も自主的な改修を促進するための任意制度であることは分かります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":348,"id":"exchange-079"},{"speaker":"こしば委員","kind":"質問・要望","question":"そうは言っても、区のほうで、 今、順次、改修、法定点検を進めている中で、安全基準を満たしていないというシールを区が積極的にこれを貼り出すということは、陳情のところに震災時にパニックを防ぐためと書いておるのですが、むしろ平時の中で、こういった安全未達のシールを貼ることによって、区民の方がパニック、不安に陥ってしまう、そういった危険性があると思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":349,"id":"exchange-080"},{"speaker":"つる副委員長","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。質疑を確認させていただいて、冒頭の説明も含め、優先順位をしっかりとつけて適格にしていくことをしっかりと進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":350,"id":"exchange-081"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、趣旨採択です。は既存不適格を安全なものにしていくことが必要だと思いますけれども、やはり分かりやすく区民に伝えていくことが必要だと思いますので、趣旨採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":351,"id":"exchange-082"},{"speaker":"松本委員","kind":"意見","question":"本件については、シール云々というよりも、エレベーターが既存不適格をどう解消していくかということが大事だと考えております。その中で、あえてシールを、今回の既存不適格ということのシールを貼っていくよりも、できるだけ早く解消していただくということに注力していただいたほうが、区民の安全に資すると考えておりますので、シールについては不採択と申し上げします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":352,"id":"exchange-083"},{"speaker":"中塚委員","kind":"質問・要望","question":"本日結論を出すということと、いろいろ考えましたけれども、不採択でお願いします。ただ、先ほど説明の中で、更新には３０年かかるという話がありましたけれども、区役所なり公の施設であるだけに、そこは前倒しで進めていく、基準が上がった理由にもよりますけれども、そこはよく見て、３０年と言わずに、慎重に検討していくという姿勢は求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":354,"id":"exchange-084"}]},{"id":"topic-12","title":"令和７年度品川区一般会計予算繰越明許費繰越計算書","agenda":"令和７年度品川区一般会計予算繰越明許費繰越計算書","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"今の議会の報告は、このタイミングで必ずしなければいけない根拠があるのか、繰越明許を、いわゆる予算特別委員会でもない、補正の審議でもない通常の総務委員会の中で繰越計算書の報告は、位置づけられているものなのか、それとも区が先に説明したいというものなのか、 中身は理解しているのですけれども、なぜこのタイミングなのかということがよく分からなかったので、 そこだけ。","respondent":"加島財政課長","answer":"今回の繰越明許費の報告につきましては、地方自治法施行令第１４６条第２項に基づきまして、議会に報告を行うことになっているものです。そのため財政を所管しております総務委員会にご報告をしています。","voiceIndex":361,"id":"exchange-085"}]},{"id":"topic-13","title":"審査請求の却下の報告について（報告第２１号）","agenda":"審査請求の却下の報告について（報告第２１号）","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"言えない理由があれば、それはそれで示していただきたいのだけれども、今の説明とこの資料だと、対象が分からないもので、一般的な理屈としては、そういうことがあるということは理解しているのだけれども、聞いてはまずいのですか、そこがよく分からないので、そこも含めてご説明いただけたらと思います。","respondent":"中西総務課長","answer":"恐れ入ります、冒頭で申し上げればよろしかったのですが、今回の案件、相手先の方が特定されないようにといった形で、少し分かりづらいご説明をしているといったところでご理解いただければと思います。","voiceIndex":368,"id":"exchange-086"},{"speaker":"中塚委員","kind":"質問","question":"特定されてしまうのですか。特定されないようにというのは分かるけれども、いいです、以上です。何のことだか全然分からないですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":370,"id":"exchange-087"},{"speaker":"松本委員","kind":"質問","question":"内部通報について、新たに、令和８年、今年の５月に公益通報で調査した結果、改善等の措置が講じられた案件があると区のホームページに公開されておりまして、こらは必ずしも法に基づく報告事項ではないとは思うのですけれども、区民にも関わることですし、あと、内容的には、これが個人情報保護法に関するものなので、総務委員会でもご報告いただけないかと思うのですが、いかがでしょうか。","respondent":"中西総務課長","answer":"恐れ入ります、委員長とご相談しまして、どのような取扱いにするか検討させていただきたいと思います。","voiceIndex":375,"id":"exchange-088"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.29so.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":60,"characters":61635,"voices":379}},{"id":"r08-20260630-6","meetingId":"r08-m0708","date":"2026年6月30日","dateIso":"2026-06-30","committee":"区民委員会","time":"午前10時00分～午前11時51分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":false,"topics":[],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.30ku.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":3,"characters":510,"voices":5}},{"id":"r08-20260630-7","meetingId":"r08-m0708","date":"2026年6月30日","dateIso":"2026-06-30","committee":"厚生委員会","time":"午前10時00分～午後２時13分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","hasFullText":false,"topics":[{"id":"topic-01","title":"令和７年度品川区障害福祉計画等実績","agenda":"令和７年度品川区障害福祉計画等実績","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"３０ページの放課後等デイサービスと児童発達支援ですが、すごい勢いで毎年利用者が増えている状況だと思うのですけれども、放課後等デイサービスの誘致にも様々な支援策を使いながらやっていただいていると思うのですが、先ほど放課後等デイサービスも２か所増えたということですが、現在の放課後等デイサービスは、しながわの福祉を見ると３３か所で３４０人分ですが。","respondent":"石橋障害者施策推進課長","answer":"まだまだ数が足りない認識はありますので、 そういったところ、どういった障害種別で必要なのかも、今持っている数字から洗い出しをできる限りやりたいとは思っておりますので、児童発達支援と放課後等デイサービスの整備に努めてまいりたいと考えております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それなので、療育と言いながら、やはり就労を支える施設としても利用せざるを得ないと思っていまして、そういうところからも必要量を出していただいて、就労も続けられるようにぜひご検討いただきたいと、お願いをしておきたいと思います。自宅に戻ったということになるとしたら、 地域生活移行は親の元に戻るということになったのか、具体的に伺いたいのが１点です。","respondent":"石橋障害者施策推進課長","answer":"基本は地域移行というのは、グループホームに入るか、またアパートなどの独り暮らしという認識はしていますが、その方が選ばれた、どこで住んでいきたいというように、安心して自分らしく暮らしていけることを実現させるのが第一になりますので、その方がどこを希望して。","voiceIndex":11,"id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問","question":"地域精神保健福祉連絡協議会は、令和７年度は何回ぐらい行われたのか、それについても伺います。そのことによってどのように改善されていくのかを伺えたらと思います。","respondent":"石橋障害者施策推進課長、芝野障害者支援課長","answer":"１点、答弁が漏れておりました。大変失礼いたしました。地域精神保健福祉連絡協議会の回数について、令和７年度は１回開催しております。私から２点、ご質問にお答えします。第三北品川病院の医療ショートステイの関係です。こちらはまだ今、交渉をさせていただいてございまして、なるべく早く体制が整って、ご利用していただけるように努力してまいります。","voiceIndex":13,"id":"exchange-003"},{"speaker":"鈴木委員","kind":"意見","question":"それで、前の森山医院のときは、人工呼吸器を使われている方が利用できない状況があったのですが、今、大田区のさぽーとぴあの医療ショートステイが受け入れていただけているので、そちらも利用できることにはなったのですが、 さぽーとぴあは大田区の施設ですし、品川区でもそういう、人工呼吸器をつけた方もぜひ受け入れていただけるように交渉もお願いしておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":16,"id":"exchange-004"},{"speaker":"吉田委員","kind":"確認","question":"独り暮らしができないというのは、要は独り暮らしに対するサポート体制を充実しなければいけないことになりますので、その辺については評価をもう少し厳しめに、きちんと区が本来目指している地域移行なのかを確認すべきだと思うのですが、その点についてぜひ伺いたいのですが、いかがでしょう。","respondent":"石橋障害者施策推進課長","answer":"それぞれに自立支援協議会でも部会も設置しておりますので、活用しながら、地域生活への移行を区としてはどう捉えていくのかもしっかりと考えながら、施策についてもしっかりと支援を充実していきたいと考えております。","voiceIndex":18,"id":"exchange-005"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひその辺はきっちり、こういう計画の中でも目標を立てて進めていただきたいと思います。昔に比べるとすごく進んだのは、本当に評価をしております。やはり中には、そういう団体とか会に参加すること自体があまり得意でない方もいらっしゃると思いますので、ぜひ、本当に今進んできているという前提でさらに進めていただきたいと思うのですが、 その点についていかがでしょうか。","respondent":"石橋障害者施策推進課長","answer":"計画の策定に関しましては、パブリックコメントですとか、当事者の方も意見を言っていただける場所もつくっておりますので、今後、障害部門をはじめとして関係している各所には、計画も通していろいろお伝えはしていきたいとは思っておりますので、当事者を含め。","voiceIndex":20,"id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"呼びかけの工夫によっては、本当に団体に参加していない方たちも参加できるような仕組みもできると思うので、その辺についてはぜひ検討していただきたいと思います。自立支援協議会は私たちも傍聴できるようになったのですが、そこに、位置づけられているそれぞれの部会は、私たちが要求しないだけなのか、傍聴したいですと言ったらできるのか、できないという思い込みでお願いもしないのですが。","respondent":"芝野障害者支援課長","answer":"自立支援協議会本会ではなくて専門部会ですが、今のところは非公開という形でやらせていただいております。","voiceIndex":22,"id":"exchange-007"},{"speaker":"吉田委員","kind":"質問・要望","question":"ということなので、こちらの傍聴する力量もありますのであれですが、議員だけではないですから、 傍聴といえばそこに関係する、もしくは直接の関係ではないけれども、障害者のご家族の方でここも聞いてみたいとか、何かそういう方もいらっしゃると思いますので、ぜひ傍聴ぐらいはさせていただいてもいいと思うのです。今検討中とか、そういうことがあったら教えていただきたいのですが、いかがでしょうか。","respondent":"芝野障害者支援課長","answer":"専門部会の公開につきましては、まだ内部的には検討はしておりませんので、今後、その在り方も含めて研究してまいりたいと思います。","voiceIndex":24,"id":"exchange-008"},{"speaker":"吉田委員","kind":"意見","question":"傍聴も、団体の方だけでない障害者の関係の方も、やはりもう少し自分たちに具体的に関係する部会なんかも傍聴したいというご希望者は多分いらっしゃると思いますので、ぜひ研究ではなくて前向きに検討していただけたらいいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":26,"id":"exchange-009"},{"speaker":"やなぎさわ委員","kind":"質問","question":"資料の１１ページ、１２ページです。今回の数字、非常に順調でありますけれども、その中で実際の数字の健全性、しっかりと定着しているのか、就労後のモニタリング、６か月以上の定着などを含めて、そういったことに関して区として、そういう昨今の事案もありますので、何か対策、モニタリング等を実施されているのか、もしくは今後する予定があるのか、お伺いしたいと思います。","respondent":"芝野障害者支援課長","answer":"就労支援における就労後のモニタリング支援のお問合せだと思うのですが、社会福祉法人げんきで就労を承っているのですが、離職支援を行っておりまして、就職後、そういうお困り事があった場合には、 来所いただいても構いませんし、電話相談、訪問相談、その他。","voiceIndex":28,"id":"exchange-010"},{"speaker":"やなぎさわ委員","kind":"質問","question":"そういった相談事業はあるとして、区としてこういったモニタリング、数字を出す上で、今後そういったものも入れて追跡し、数字も入れておく必要がある。それこそ健全性の担保という意味で思うのですけれども、そういったお考えがあるかをお伺いしたいです。","respondent":"石橋障害者施策推進課長","answer":"今お話がありました就労継続支援のＡ型、Ｂ型に関しましては、区の指導検査の対象事業にはなっておりますので、区で指導検査に入ることで、サービスの質の一定の水準を図っていただくというところは、しっかりと区としても見ていきたいと思ってあります。","voiceIndex":30,"id":"exchange-011"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ちなみに、昨今、就労支援で絆ホールディングスの件があったり、食材費の件でも不正の案件があったりしたと思うのですが、そういった何か点検は、最近、品川区ではされていらっしゃるのでしょうか。","respondent":"石橋障害者施策推進課長","answer":"申し訳ありません。運営指導の詳細については今把握をしていないので、そういった今、委員ご指摘の部分の指導に入ったかは、把握していないところになります。","voiceIndex":32,"id":"exchange-012"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"その辺のチェック、伴走をしていただきたいというのと、話は戻りますが、こういった就労定着支援のチェックとか、もしくは定着後の伴走、そういったものもぜひ数字として出していただくことも要望させていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-013"},{"speaker":"若林委員","kind":"質問・要望","question":"すみません、順番が逆になったかもしれないですが、１番目の地域移行で、そこの新しく地域移行等意向確認担当者という役割ができて、前に進んでいるのだろうと理解はするのですが、議会の中でも度々出ますけれども、区外の施設に入所している方、利用している方が一定数いらっしゃって、 そうすると、区外の施設の方に対しての地域移行の支援は、担当者の役目も含めてどのようにされているのかは。","respondent":"石橋障害者施策推進課長、芝野障害者支援課長","answer":"私からは、住まいの確保についてと、定着支援事業所の定着率の３５％の認識というところの答弁をします。地域定着支援の実績ゼロですが、こちらは、区内に定着支援をやっている事業所はございませんが、あと、区の独自事業として障害者地域生活サポート２４事業をやっておりまして、２４時間の見守りも含めて対応しておりますので。","voiceIndex":36,"id":"exchange-014"},{"speaker":"若林委員","kind":"質問","question":"そうすると、地域定着支援が実績ゼロだけれども、障害者地域生活サポート２４で代替している、代わりになっているという意味で、そうすると実質的に、地域定着支援事業としてはゼロだけれども、障害者地域生活サポート２４で何件それをカバーしていると、そういう言い方になるのでしょうか。","respondent":"芝野障害者支援課長","answer":"障害者地域生活サポート２４事業の実績ですが、当初登録者数としては、令和７年度に知的障害者３０人、精神障害者６０人がいまして、支援の延べ件数になりますが、知的障害者が１,１８０回、 精神障害者が２,６５６回、こちらでカバーさせていただいているところです。","voiceIndex":39,"id":"exchange-015"}]},{"id":"topic-02","title":"令和７年度品川区介護保険制度の運営状況","agenda":"令和７年度品川区介護保険制度の運営状況","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"それで、見直すときも、要支援２と要介護１というのはそんなに状況は変わらないので、要介護１にということも言われていたと思うのですが、それだけでなく、要介護３から５も少ないので、そこもしっかりと、特別養護老人ホームに入れるかどうかということも変わってくるので、ぜひ見直していただきたいので、伺います。それが１点です。それについても伺います。その３点についてお伺いします。","respondent":"佐藤高齢者福祉課長","answer":"ただ、要介護認定の有効期限は最長３年になりますので、３年程度で全体の要介護度がこの基準に沿って変わっていくとご認識いただければと考えております。","voiceIndex":46,"id":"exchange-016"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今年は第１０期に向けての計画なので、ぜひここはご検討いただきたいと思っているのです。それにもかかわらずなぜ介護保険料だけが高いのか、私は少し不思議だと思っていまして、区としてどう考えるかを伺いたいと思います。６５歳以上の人の保険料が余って積み立てている基金がかなり増えていると思うのですけれども、令和７年度末で幾らになっているのかも伺います。","respondent":"佐藤高齢者福祉課長、樺島高齢者地域支援課長","answer":"すみません、基金の具体的な数字はあれなのですが、今年度の決算が終わりましたら、最終補正で積む場合は積み上げてというところですので、こちらは引き続き第１０期の介護保険事業計画の中の保険料の算定のときも。私から、１１ページの地域支援事業についてのご説明をします。大変申し訳ございません。前年度から減っている理由については今すぐにお答えできる材料がないのですが、ただ、それに伴う各事業は引き続き実施をしています。","voiceIndex":48,"id":"exchange-017"},{"speaker":"鈴木委員","kind":"質問・要望","question":"あと、この段階も品川区の場合は１７段階で、基準額の最高でも３.３倍という状況ですけれども、これも１７段階の方は１.３％しかいない状況にはなっているのですが、私は考え方としても、この保険料はさらに高額所得者に応能負担をしてもらうという段階にぜひしていただきたい、これは要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-018"},{"speaker":"やなぎさわ委員","kind":"質問","question":"資料の１０ページの特例減額、低所得者対策についてお伺いしたいのですけれども、令和７年度１２ 件ほどいることは、この推移で見るとかなり減ってきていると思うのですが、この１２件の内訳が、 ずっと同じ方が継続で受けられているのか、新たに申請されて受けている方がいるのか、その状況がお分かりになりましたらお伺いしたいです。","respondent":"佐藤高齢者福祉課長","answer":"申し訳ございません。内訳の把握はしておりませんけれども、委員ご指摘のとおり、この間、漸次減少しているという実態です。","voiceIndex":53,"id":"exchange-019"},{"speaker":"やなぎさわ委員","kind":"質問","question":"そのとおりだと思うのですが、平成１３年が１４９件もあったのですよね。現在、１０分の１以下になっていて、本当に低所得者、困窮者の方が減っているのでこの数字ならいいのですが、これは、平成１３年と現在で、基準が変わったり何か変更があったりしてこれだけ減っているのでしょうか。その辺お伺いしたいと思います。","respondent":"佐藤高齢者福祉課長","answer":"こちらの特例減額は、事業パンフレットも置いておりまして、受け付けているところではありますけれども、減少している理由については、こちらでは把握していない状況です。","voiceIndex":55,"id":"exchange-020"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"なので、ぜひ、今その１２件を把握していないということですけれども、これの中身が継続か新規かも含めて調べていただいて、そして、この特例減額についての周知もしっかりしていただきたいと思っているのですが、ちなみにその周知についてはいかがでしょうか。どのような周知をされていらっしゃるのか、お伺いします。","respondent":"佐藤高齢者福祉課長","answer":"今後の分析については、委員ご指摘のとおり、 こちらとしましても把握しまして、必要な対応を取っていきたい、検討していきたいと考えています。","voiceIndex":57,"id":"exchange-021"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ぜひ、それこそ１４ページとか１５ページには広報活動というのを載せていただいていますし、積極的にやはりこういった制度をご案内して、１２件をどれぐらい捕捉できているのか、当然該当する方であれば、基本的には使いたいと思う方が多いとは思うので、ぜひこの辺は、これだけ大分件数も減っているので、しっかり中身を分析して、周知に努めていただきたいと思います。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-022"},{"speaker":"吉田委員","kind":"提案","question":"今の周知の話です。そうすると、この方たちにはもう介護が必要だという判断も可能になって、そこにしかるべきサポートができると思うのですけれども、その点について、何かそういう共通の課題を持った人たち、支払いが滞るようになったとか、そういうことについての対策は検討されているのでしょうか。やはりそういうのが必要になっていくと思うのですが、お答えできる範囲でお答えいただきたいと思います。","respondent":"佐藤高齢者福祉課長","answer":"なかなかやはりこれがあれば大丈夫ということはなくて、様々なアンテナがそれぞれありますので、 そこを情報共有していくのが大事と思いますので、委員のご指摘もありましたが、個人情報というのはどうしても出てきますけれども、同じ行政であれば。","voiceIndex":61,"id":"exchange-023"},{"speaker":"吉田委員","kind":"意見","question":"難しいことは承知で今、意見を申し上げたのですけれども、本当に情報は多分いっぱい発信してくださっていると思うのですが、いっぱい来ること自体が、もう受け止める側には難しい状況である人たちがこれから増えていくことは認識の上、対策を考えていただければと思います。これはもうお願いするしかないので、以上です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-024"},{"speaker":"鈴木委員","kind":"質問","question":"それは結構大きな額にもなりますので、今回、陳情も出されて、総務委員会で審査されたと思うのですが、そこを知らない人がすごく多いと思っていまして、認定証を発行しますよという周知をこちらの高齢福祉課でしていただくようになると思っていまして、その周知をぜひお願いしたいと思うのですが、いかがでしょうか。","respondent":"佐藤高齢者福祉課長","answer":"先ほどの議論でもありましたけれども、なかなか届きにくいところはありますので、どういうツールがいいか継続的に考えていきたいと思います。","voiceIndex":65,"id":"exchange-025"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"分かりました。そのように計算すれば分かると思うのですが、できればこの中に、件数だけではなくて金額もぜひ次回以降は入れていただければと思いますので、要望だけします。","respondent":"菅野福祉部長","answer":"今の保険料の軽減について少し補足させていただきたいと思いまして、件数が近年減っている、平成１３年度１４９件というお話がありましたが、こちらについては多分、介護保険ができた当時の話で、 以前、独自の介護保険料の特例減額を実施していた経過がありまして。","voiceIndex":70,"id":"exchange-026"}]},{"id":"topic-03","title":"令和７年度５歳児健康診査事業の検証結果と令和８年度の取組み","agenda":"令和７年度５歳児健康診査事業の検証結果と令和８年度の取組み","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"４８人が受診した中で、４人が医療機関と発達相談室に紹介されたということですが、この医療機関はどこの医療機関というのがあるのか、それがあるのであれば伺いたい。それから、令和８年度が５２園で１,０００人に拡充してこれからやっていくということで、ぐっと広げられるわけですが、全員にこれを広げる計画はいつ頃までにしていくのか、その見通しについても伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-027"},{"speaker":"やなぎさわ委員","kind":"確認","question":"先ほどの鈴木委員の質疑と重なる部分で一応確認ですけれども、今回１２園モデル実施で、今後 ５２園に増えて、対象者も１,０００人に増え、大体４.５倍ぐらいに増えると思っておりまして、人員確保の問題で改めてお伺いしたい。改めて、ここら辺の課題はきちんと解決できる見込みはあるのでしょうか。","respondent":"川村品川保健センター所長","answer":"あわせて、ほかの区でも同様の課題があろうかと思います。いろいろな方法で医師を確保している事例もありますので、そういったものを参考にしながら、しっかりと確保して、健診を実施した後、しっかりと支援につながるように担保していきたいと考えております。","voiceIndex":86,"id":"exchange-028"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"やはり、こういった５歳児健診になると、その分、もちろん先ほどの、今日の最初の令和７年度の障害福祉計画の実績等にも絡んできますけれども、発見が増えると児童発達支援とか専門医療の初診待ちが増えてくるので、発見ベースと同時に受皿の拡充も併せて要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-029"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.30ko.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":29,"characters":35698,"voices":102}},{"id":"r08-20260630-8","meetingId":"r08-m0708","date":"2026年6月30日","dateIso":"2026-06-30","committee":"建設委員会","time":"午前１０時００分～午後１時４６分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を57件抜き出しています。","hasFullText":false,"topics":[{"id":"topic-01","title":"大崎西口駅前地区（大崎駅西口Ｆ東地区）の再開発事業に係る事業者による近隣説明会の 開催","agenda":"大崎西口駅前地区（大崎駅西口Ｆ東地区）の再開発事業に係る事業者による近隣説明会の 開催","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それと、地区内の権利者数等について全体像を伺いたいと思いますけれども、当該地区の土地所有者数と借地権者数、借家人の数、分譲マンションの棟数、区分所有者の数、法律上の権利者数、地権者数というのですか、あと、そのうち再開発組合加入者数、そして最後、当該地区にある分譲マンションは、 準備組合にはマンションごとで加入しているのか、区分所有者個人ごとに参加しているのか。","respondent":"中道都市開発課長","answer":"準備組合といたしましては、こういった近隣の説明会をして、様々な声を聞いて、そうしたことを踏まえて今後の計画につなげていきたいというところで開催するものですので、そういったことを踏まえて、今後の状況等を見て手続をするというところだと考えています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"借地権のところは後でまたやりますけれども、時期ですけれども、現時点では行政としては未定だということで、逆に安心したというか、何というのですか、この時点では、行政として予断を持って、ここまでに都市計画決定をするなどという考えは持っていないということだと思うので、やはり近隣説明会自体が、ある意味、都市計画手続に向けた第一歩だと私は認識はしているのですが。","respondent":"中道都市開発課長","answer":"そうした中で約８割以上の方が、都市計画に進めてほしいという同意書を提出されたということから、いわゆる近隣説明会を行って、周辺の地域の方々のご意見も聞きたいということを言われている状況です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"提案","question":"やってください」と、相談を受けて言ったのかどうか伺いたいと思います。それで、課長は８割以上という話は聞いていると伺いましたけれども、先ほど紹介した、地元の方々から届いている書類などには、８割同意ではないという疑義が出されているわけです。近隣説明会の開催について、指針に適合していると考えているのか、伺いたいと思います。","respondent":"中道都市開発課長","answer":"今現在は、正式に何か書類が出てきている、都市計画に向けた企画提案書の中で、様々なそういったことが書いてあるところではございませんけれども、一定程度、行政といたしましては、地域からの８割合意が得られたということは聞いてはいますので、今度、説明会をして。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤委員","kind":"提案","question":"都市計画手続に入る、つまり企画提案書を受け取った時点で精査したいということだと思うのですけれども、それは当然なことだとは思うのですが、８割がどうなのかという話も後でしたいのですけれども、先ほどから紹介している、６月２９日付の、大崎西口駅前地区再開発を心配する会から全ての建設委員のメンバーに届けられたお願いの文書なのですけれども。","respondent":"中道都市開発課長","answer":"再開発をしますと、どうしても当該地に住み続けたいという方であっても、引っ越しを２回、仮移転のところに１回、また戻ってくるのに１回、要するに合計２回、引っ越しをしなければいけないというところ、やはりそこにつきましてはどうしても。","voiceIndex":11,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは、住民のために選択肢を増やしたのだみたいな話がありますけれども、「鳥瞰イメージ」という資料にもありますけれども、これはオフィスビルそのものなのです。こちらは、 先ほどから紹介している文書、要望書などにも書かれていることなのですけれども、だから住替え・移転する方々を含めての８割同意とは、かなり無理があるのではないかと思うのですけれども、区の見解を改めて伺いたいと思います。","respondent":"中道都市開発課長","answer":"繰り返しになりますけれども、今回の当該地区の再開発につきましては、当該地に住み続けるのか、もしくは地区外に移転するのか、もしくは大崎駅西口Ｆ南地区、近隣地の再開発のほうに移り住むのかといった中での生活再建の中で。","voiceIndex":13,"id":"exchange-005"},{"speaker":"安藤委員","kind":"提案","question":"自らが、そこに住みたいという方々の要望には応えられない計画を進めようとしているわけですから、一層努力をしなくてはいけないのではないかと。品川区自らが現地に赴いて、納得がいかない多くの権利者の声も聞いていただくなど調査を行って、改めて、この企画提案書を受ける段階なのかどうかを判断していただきたいと思うのですけれども、いかがでしょうか。","respondent":"中道都市開発課長","answer":"区は、そういった様々な声に対しては、きちっと受け入れる体制はありますので、また何かございましたら、私のところに来ていただければ、そういったお話は聞いていきたいと考えています。","voiceIndex":15,"id":"exchange-006"},{"speaker":"安藤委員","kind":"提案","question":"スケジュールは白紙なわけです。最後に借地権についても伺いたいのですが、都市再開発法は、再開発組合設立の要件として、区域内の土地の所有権者および借地権者のそれぞれ３分の２以上の同意を得ることを求めています。ですから、この再開発は、進められない、 見通しが立たないはずなのですけれども、１つは、ところが先ほどは複数人いるという話もあったので、 増えたということなのでしょうか。","respondent":"中道都市開発課長","answer":"ですので、今、安藤委員が言われるような、１名の方が反対しているというところで、都市計画の次の段階、事業認可申請のときには、法律にのっとって、土地の所有者の３分の２以上の同意、また借地権者の３分の２以上の同意が必要だというところで、もし仮に１名ならば。","voiceIndex":17,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"何というか、今そのような状況ではないという話ですけれども、それはなぜなのかが分からないということで、３分の２ですから、複数名いるという、２人だったとしても、そのうち１名の方が反対しているわけですから、そうすると２分の１にしかならない。だから今の段階で見通しが立っていないのです。","respondent":"中道都市開発課長","answer":"ですので、そういった中で、地域の権利者の方の総意の部分が８割以上の中で都市計画を進めていきたいという報告を受けていますので、まずは近隣説明会を開催して、周辺の地域の方々のご意見を聞いて、今この再開発にどういった意見があるのかというのは、 十分。","voiceIndex":19,"id":"exchange-008"},{"speaker":"安藤委員","kind":"提案","question":"ましてや都市計画決定というのは行政の決定なわけですから、それをやる上で、自らの足で、 自らの目で耳で、そういった住民の声を聞き、そして調査もし、そしてこれが本当に、区長がこの間言っているような、まちづくりの主体はそこに住む地域住民になっているのかという観点で、しっかりと見ていくということが行政には求められていると私は思いますので、ぜひそういった立場で今後。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":21,"id":"exchange-009"},{"speaker":"こんの委員","kind":"提案","question":"先ほど、法律上では位置づけはないということなので、だとすると、今、質疑を聞いていて、企画提案書がまだ出されていないとすると、想像ですが、この住民説明会で皆さんのご意見を十分に聞いて、そして企画書を作っていかれるための住民説明会を行うのではないかと想像するのですが、ほかの例で、こういう再開発のときに、企画提案書が作られる前に住民説明会をするみたいなことが今まであったのか。","respondent":"中道都市開発課長","answer":"ですので、そういった意見も受けまして、準備組合といたしましては、ＪＲと様々協議をして、その期間、１年間ぐらいかかったのですけれども、再開発の中で取り組むような提案を様々今受けながら再開発を進めているという状況ですので、やはり区といたしましては。","voiceIndex":23,"id":"exchange-010"},{"speaker":"こんの委員","kind":"提案","question":"そうすると、やはり企画提案書の前に住民説明会を行うというのはありだといったところですか。なので、よくよく、やはりいろいろな方の意見を聞く場というのは非常に大事だと思いますので、企画提案書が作られる前の住民説明会、いわゆる決定のことではなくて、いろいろな声を聞く住民説明会をぜひしながら、進めるに当たってはこうしたことが必要だということは今確認させていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":25,"id":"exchange-011"},{"speaker":"おぎの委員","kind":"質問・要望","question":"今回の再開発といいますか、まちづくりということで、目的の部分に、建物の老朽化等による心配といいますか、防災性の向上を一番最初に掲げられておりますが、この地域の、今、区が考えている現状といいますか、旧耐震基準の建築物ではありますが、非常に古くて危ないと思っていらっしゃるのか、 もう少しまだ大丈夫なのか、それともやはり過密なので何とかしたほうがいいと思っていらっしゃるのか。","respondent":"中道都市開発課長","answer":"再開発の説明会の範囲ですけれども、準備組合からは、今冒頭で説明した、裏面の２Ｈの範囲の中に案内を配っているというところですので、対象としてはその方々にはなるのかと考えております。","voiceIndex":27,"id":"exchange-012"},{"speaker":"おぎの委員","kind":"質問・要望","question":"今はまだ都市計画に進めるか否かという段階ということですので、しっかりと近隣の方の意見が聞けるような状況を、区としても適宜アドバイスなどしながら介入していただきたいと思います。よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"第１１次計画の目標は死傷者数が６００人以下だったのを、今回８００人以下と、目標は、下げたというか、その理由は何なのかというのと、あと実際に増えているからだとは思うのですけれども、死傷者数が増えてしまっているというのはあると思うのですが、何で増えているのかというのは、その理由も伺いたいと思います。そして、この計画の内容について説明するし、理解してもらった上で意見も出してもらう。","respondent":"原交通安全担当課長","answer":"続きまして、説明会につきましては、現時点では説明会の実施は考えておりません。理由につきましては、本計画につきましてはパブリックコメントを、要綱に従いまして実施する予定です。","voiceIndex":34,"id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"なので、私たちの思いとしては、こういった、特に命に関わる重要な計画だと私は思っているのですけれども、こういった計画のパブリックコメントに際しては、説明会も併せて行うということを当たり前にしていただきたいと思いますので、これは要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-015"},{"speaker":"こんの委員","kind":"確認","question":"大きく２点です。この計画の中から確認というか、関連する、「総合的な対策を」と目的の中にもありましたので伺っていきたいのですが、１つは道路交通安全対策という中から、１点はカーブミラーの設置というところ、 もう一つが道路標識の設置といった角度。この２点を伺いたいのですけれども。大分、このことについては以前よりも、設置できる部分には設置されている。この２点をお伺いします。","respondent":"森道路課長","answer":"カーブミラーと、私道の出入口の安全性について、ご質問を頂きました。道路課といたしましても、私道・公道の区別なく、あるいは設置できる・できないの区別なく、安全にするために必要な設備というものはしっかりとつけていきたいとは思っております。","voiceIndex":38,"id":"exchange-016"},{"speaker":"こんの委員","kind":"質問・要望","question":"ご理解いただけるかどうかというところもあるというのも理解しております。ここをどうするかといったところで、私道ですから、当然、公道のように車が出入りするというのは、住人の方はいいのですが、そうではない外部の車両というのは控えていただきたいというのが、住民の方の要望でもあるのですが、それでもやはり宅配の車など、生活に必要な車というのは入ってくる。","respondent":"原交通安全担当課長","answer":"区といたしましては、様々なご要望を頂く中で、どうしたら安全な通行ができるか、危険箇所が多々あるところも承知しておりますので、そういったところにつきましては、適宜、警察と情報共有をして、実際に実施の要領といたしましては、警察と一緒に現場を見て、何ができるのか。","voiceIndex":40,"id":"exchange-017"},{"speaker":"こんの委員","kind":"質問","question":"もう一つ、道路交通環境の整備という角度で１つお伺いしたいのですけれども、これは、お宅の建て替えをしたときに、電柱がそばにある。セットバックしたときの、電柱が残ってしまうことのへ対策は、やはり、これが残らないようにしていくためにはどうしたらいいのかということを、区はどのように考えているのか、また、なぜ残ってしまうという課題が生じてしまうのか、その課題についても伺いたいと思います。","respondent":"森建築課長","answer":"とはいいましても、委員がおっしゃるとおり、通行の妨げになりますので、下げていただくように、建築課の職員からも、何度も建て主に対して説明して、ご理解いただけるように努めているところです。","voiceIndex":42,"id":"exchange-018"},{"speaker":"こんの委員","kind":"質問","question":"なかなかご理解いただけないといったところの理由の一つに、お聞きするところ、電柱をセットバックするときの費用はまず自腹というか自費、最初に自分で払う、後から戻ってくる。そうしたことで、なかなかそのことをご理解いただけないというのが１つあるというのは、実際にそういうご相談を受けたことがあります。ご理解いただけるようなやりようがないのかというところを伺いたいと思います。","respondent":"森建築課長","answer":"直接支払いが可能かどうかにつきまして、電柱の事業者に問い合わせている最中です。１つの事業者からは、どうしても難しい。もともと、電柱移動についてオーケーしてくれた方と支払者が違うというところで、受け付けられないとは聞いております。","voiceIndex":44,"id":"exchange-019"},{"speaker":"こんの委員","kind":"意見","question":"品川区が全額負担、最終的にはしてくださる。その支払いの仕方というところで、今、交渉してくださっているということですので、引き続き、このことが１つクリアになると、ご理解のしようがあるかと思いますので、ぜひ引き続き、その点の交渉をお願いしたいと思います。それが促進につながると、 こうした電柱が残るということの課題も解消につながるのかと思いますので、どうぞよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-020"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"先日も、事故はなかったのだけれども、旗台小学校の脇のところは信号がないのです。それで、区境から坂道を下りてくるのと、それで交差してしまって、そこがヒヤリハットになる。これは、私のところだけではなく、品川区としても問題だと思うので、今後これをどういうふうに推進・強化していくというのを、今現在のことをお知らせしていただきたいと思います。","respondent":"原交通安全担当課長","answer":"令和６年中は１５件といったところで、８件の増加をしております。都内につきましても、都内全体で２８０件、事故が起きておりまして、前の年からプラス３６件といった形で、やはり特定小型原動機付自転車も広く普及し続けているといった現状で認識しております。","voiceIndex":47,"id":"exchange-021"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひよろしくお願いします。そういった中で、２点だけ質問をします。もう一点なのですけれども、素案の７３ページなのですけれども、警察と地域交通政策課が掲げている「トワイライト・オン運動」も、本当に幅広く推進していただきたいと思いますけれども、これは本当に私の要望としてなのですけれども、そのことについて２点、何かあればお話しいただければと思います。","respondent":"原交通安全担当課長","answer":"最後に「トワイライト・オン運動」です。こちらも警察が広く呼びかけているものですので、それぞれ交通安全運動が年に２回ありますので、その実施の前後で広く呼びかけていけるよう、広報も連携していきたいと考えています。","voiceIndex":49,"id":"exchange-022"},{"speaker":"おぎの委員","kind":"質問・要望","question":"大分、聞きたいことが、全く同じものが出ておりましたので、最後に要望だけお願いしたいと思います。ぜひ現地に行って、自転車の流れなどを見ていただきたいと思っております。同時にやはりＬＵＵＰなどの小型のモビリティが、やはりスリムなので、赤信号で止まっている車の隙間を縫って前へ出ようとする、そういった運転をされている方を非常に多く見かけます。以上要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-023"},{"speaker":"えのした副委員長","kind":"質問・要望","question":"こちらはパブリックコメントを実施されるということで、もし分かればなのですけれども、まだ４月からですから、４・５・６月と３か月しかありませんが、この新しい交通ルールに変わってから、先ほど死傷者数の増減みたいなものもありましたけれども、このルールに変わって少なくなった、いや、増えたというところが、数が分かれば教えていただきたいのですが、いかがでしょうか。","respondent":"原交通安全担当課長","answer":"今ご質問いただきました、今年の４月から青切符制度が導入されたことによる情勢の変化についてご説明いたします。４月から青切符制度が導入されまして、自転車の取締りというのは青切符で行われるようになっております。","voiceIndex":53,"id":"exchange-024"},{"speaker":"えのした副委員長","kind":"質問・要望","question":"取締りの件数も減少していて、事故も減っているということで、交通安全としては大変、効果が出ているのかなと感じておるところであります。こちらは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-025"},{"speaker":"こんの委員","kind":"質問","question":"今、副委員長からの質問に少し関連するのですが、青切符に関連して、青切符となった項目が百十何項目ある中に、違法駐輪も入っていると認識しているのですが、違法駐輪で青切符を切られるというのは相当だと思うのですけれども、これに伴う、いわゆる品川区としての違法駐輪対策といったところは、 これまでもやってきましたけれども、さらに青切符というところに含まれてきたといったところを考えると。","respondent":"原交通安全担当課長","answer":"区といたしましては、こういった違法駐輪対策といたしまして、これまでも進めております駐輪場の整備と、あと現場における指導・警告と、あとは放置禁止区域を適宜設定して、そういった違法駐輪の車両の除去に努めていきたいと考えております。","voiceIndex":57,"id":"exchange-026"},{"speaker":"こんの委員","kind":"質問","question":"今おっしゃってくださった対策をぜひ進めていただきながら、１つ課題だと思っているのが、駐輪場を造る。一方で、どうしてもそれが造れない場所に違法駐輪がずっと残っていて、それを撤去する作業があります。費用もかかる。こういった角度で少し、これは費用もかかりますし、予算もかかることですし、こうしたところの観点というのは、どんなふうに今お考えをお持ちなのか、お聞きしたいと思います。","respondent":"原交通安全担当課長","answer":"委員がおっしゃるとおり、なかなか即効性が難しいようなところですので、２３区、ほかの区の取組なども共有しながら、引き続き違法駐輪対策をしていきたいと考えています。","voiceIndex":59,"id":"exchange-027"},{"speaker":"こんの委員","kind":"質問","question":"ですので、どうしたら、そこの場所に警告したら、自分できちんともう置かないようにしていただけるかというための施策みたいなものを考えている企業も出てきておりますので、こうしたところを研究しながら、より撤去作業にかかる費用軽減、予算を使わなくても済むようなところという観点も、これから併せて研究も調査もしながら進めてみてはいかがでしょうか。","respondent":"原交通安全担当課長","answer":"区といたしましては、今、委員のお話がありましたとおり、現状の事業は継続しつつ、民間企業など、 そういった研究が行われていることについても注視しながら、今後の業務に反映できるように考えてまいりたいと思います。","voiceIndex":61,"id":"exchange-028"}]},{"id":"topic-02","title":"電線共同溝等工事（特別区道Ⅰ－２４１号）の委託","agenda":"電線共同溝等工事（特別区道Ⅰ－２４１号）の委託","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"資料の１ページ目の２段落目の２行目、「技術職員の業務省力化を目的として」とありますけれども、 技術職員というのは、品川区の職員ということでいいのか確認したいのと、あとこのような委託形式ということでないと、電柱の地中化というのはなかなか区単独では難しいということなのか、伺いたいと思いますし、あとコスト面なのですけれども、特に趣旨のところには書いていないのですけれども。","respondent":"森道路課長","answer":"コスト面については、特に減少するということの具体的な理由といいますか、項目としてはなかなか挙げづらいのですけれども、全体的なスケジュールが短縮されたり、それぞれの事務費が減少するということはあるかと考えています。","voiceIndex":67,"id":"exchange-029"},{"speaker":"こんの委員","kind":"質問","question":"工事に関連して伺いたいのですが、これは、電柱の地中化の工事。お聞きしたい関連のことというのは、いわゆる電柱が建っている道路の占用料といったところを伺いたいと思うのですけれども、地中化になった場合の占用料はどうなるのでしょうか。参考までに伺いたいと思います。","respondent":"川崎土木管理課長","answer":"占用料につきまして、今、区道上に建っている占用に関しては徴収はしておりますけれども、地中化になることで減免ということにはなっております。","voiceIndex":70,"id":"exchange-030"},{"speaker":"こんの委員","kind":"質問","question":"減免ということですね。どれぐらいの減免になるのかというのを参考までに伺いたいのと、そうすると、あと参考までに、他区との比較で、電柱が外に出ている場合、いわゆる道路使用の占用料というのは、それぞれ２３区統一ではないと認識しているのですが、割とばらつきがあるみたいなお話も聞いたことがあります。","respondent":"川崎土木管理課長","answer":"他区と比べてというところなのですけれども、品川区は２３区の平均単価を使っておりますので、通常よりも、一般の品川区の固定資産税の兼ね合い等も含めると、比較的２３区の平均値で取っていますので、安いという言い方はできませんけれども。","voiceIndex":72,"id":"exchange-031"},{"speaker":"こんの委員","kind":"確認","question":"工事に関連して、その辺のところを少しお聞きしました。この占用料が、ひいては電気料金にも関わってくるといったところのお話を伺ったことがあったので、そういえば占用料はどういうことになっているのかなと思いましたので、この機会なのでお聞きさせていただきました。現状、品川区としては ２３区平均のところだと。引き続き、こうしたところを順次進めていただけますよう、 よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-032"},{"speaker":"えのした副委員長","kind":"質問","question":"私からも何点か、これは契約方法が一般競争入札ではなくて随意契約になっているのですけれども、 これはやはり先ほどのご説明で、民間の専門的技術・民間活力の導入による、他の区でも採用されている方法、包括して委託するためというような理由からなのでしょうか。そちらをご説明ください。","respondent":"森道路課長","answer":"電線につきましては、東京電力とＮＴＴがたくさんの電線・電柱を管理されておりますけれども、それを移動させていくということになりますと、実質的に東京電力のグループとＮＴＴのグループしか作業できないということになってまいります。","voiceIndex":76,"id":"exchange-033"},{"speaker":"えのした副委員長","kind":"質問","question":"理解いたしました。その中で、地中化はインフラ整備のとても重要な取組だと考えておりますけれども、他の地区ですと、 今、東京電力とＮＴＴというお話がありましたが、ほかに光ファイバーやケーブルテレビのケーブルなども一緒に進めているという話なのですが、今回はどのような形で進められるのでしょうか。","respondent":"森道路課長","answer":"電柱には、今、副委員長がおっしゃられたような、有線やケーブルテレビなどという、いろいろな電線が一緒に併設されているですけれども、東京電力とＮＴＴが今回の事業をしていただいて、有線やケーブルテレビも同じように管を設けて、その中に線を入れていくことになりますので。","voiceIndex":78,"id":"exchange-034"}]},{"id":"topic-03","title":"（仮称）勝島人道橋上部工の架設","agenda":"（仮称）勝島人道橋上部工の架設","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"今朝６時ぐらいに行ってまいりました。ランニングやウオーキングをされている方が、急な橋の出現に驚いていらっしゃいました。分かっていたら見たかったという方もいらっしゃいましたけれども、今回、深夜にやっていたというのは、水位を使ってということで深夜にやっていたということでしょうか。今後の工事はまた昼間の工事に戻るのか、その辺をお願いいたします。","respondent":"森道路課長","answer":"実際に、台船という船に載せて、その上に橋を据えて、位置を合わせながら、ジャッキでも下げるのですけれども、 潮が下がってくることを利用して架設したです。ですので今回は、大潮でございますけれども真夜中の設置になったです。","voiceIndex":84,"id":"exchange-035"},{"speaker":"おぎの委員","kind":"意見","question":"今後は普通の工事になっていくと思います。こちらができて、また人の流れや、ウオーキングの方たちの回遊性などもできたりするのかなと考えています。課が違うかもしれませんが、ぜひ開通の際には、両方の町会の方なども呼んでいただいて、皆さんでこちらの開幕式をやっていただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":86,"id":"exchange-036"}]},{"id":"topic-04","title":"子どもの森公園改修工事","agenda":"子どもの森公園改修工事","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"これから順次、工事が進んでいくと思うのですけれども、以前にも伺ったのですが、改めてなのですが、現在のかいじゅう公園内にある黄色のアロサウルスなのですけれども、２足歩行の肉食恐竜なのですが、品川区のポスターなどにも頻繁に使用されていますし、この公園の１つの、そういう意味では品川区のシンボルの一つになっていると思うのですけれども、新しい公園になっても。","respondent":"大友公園課長","answer":"恐竜のモニュメントについてのご質問なのですけれども、こちらは、残す恐竜というところでは、状態のよいもの３体を残し、状態の悪いものは撤去し、合計１０体の恐竜を整備するという形で以前ご説明させていただきまして、その中に。","voiceIndex":93,"id":"exchange-037"},{"speaker":"安藤委員","kind":"質問","question":"私の好みというのもあるのですけれども、それ以前に、やはり先ほども言ったように、ポスターなど、 もう品川区のシンボルの一つになってしまっているのです。もう一度だけ伺いたいのですけれども、ある程度お金をかければ再利用できるのではないかと思うのですけれども、その辺はいかがですか。","respondent":"大友公園課長","answer":"その結果、１体が、補修でそのまま利用できるかというところで追加させていただいたのですけれども、残念ながら、当初の形態等々も含めまして、黄色い、今、ポスターなどにも使われている恐竜というところについては、難しいという判断がされているところです。","voiceIndex":95,"id":"exchange-038"},{"speaker":"安藤委員","kind":"質問・要望","question":"とても残念だというか、何とか最後の最後まで、手はないかということを考えていただければということで、これは要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-039"},{"speaker":"こんの委員","kind":"質問","question":"公園改修、本当に楽しみにしております。それで、１点お聞きしたいのですが、この改修に当たっては、今、品川学園方面の入り口付近に、少しお水が出せるような、水浴びができるような場所があったかと思うのですけれども、そこは残るのでしたでしょうか。その辺を伺いたいと思います。","respondent":"大友公園課長","answer":"その場所についてなのですけれども、少し説明しにくいのですけれども、公園中央部ぐらいになる見込みです。","voiceIndex":99,"id":"exchange-040"},{"speaker":"こんの委員","kind":"確認","question":"私事で恐縮ですが、私の娘も小さいときに、実はこの水浴びをしに、遊びに連れていったことがあって、非常に多くのお子さんが、ジャバジャバではないのですが、程よく浴びられる、すごく年齢が低いお子さんでも遊べる非常にいいものだったので、それがきちんと、場所は変わっても残されるということを確認できましたので、皆さん楽しみにされると思いますので、引き続き。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":101,"id":"exchange-041"}]},{"id":"topic-05","title":"を続けます。 次に、⑹東大井公園改修工事","agenda":"を続けます。 次に、⑹東大井公園改修工事","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"その結果、反映された部分というのはどこなのかなども伺いたいと思います。それと、あと人工芝エリアがあるのですけれども、マイクロプラスチックの流出など環境への課題も指摘されておりますので、環境に優しいタイプの人工芝にして、環境や利用者に配慮していただきたいと思うのですけれども、いかがでしょうか。","respondent":"大友公園課長","answer":"人工芝というところについては、マイクロプラスチックの対策を実施するというところにおきましては、有効な手段といたしまして、排水工にフィルターを設置するということで、マイクロプラスチックの流出を防ぐ対策を実施して工事を行ってまいります。","voiceIndex":110,"id":"exchange-042"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後のところなのですけれども、契約直前というところで、あれかもしれないのですけれども、フィルターもそうなのですけれども、今、様々、人工芝であってもタイプが出ているということもありますので、その辺、最後まで工夫して、なるべく環境に負荷がないようなものにしていただきたいと思うのですけれども、再度お伺いします。","respondent":"大友公園課長","answer":"人工芝の体系といたしまして、ロングパイルの人工芝やノンフィル人工芝、また砂入り人工芝など種類があるのですけれども、今回、砂入り人工芝というところを採用しておりまして、この人工芝につきましては、ほかの人工芝より環境への配慮がされているものでございまして。","voiceIndex":112,"id":"exchange-043"},{"speaker":"こんの委員","kind":"確認","question":"工事直接のことではないのですけれども、工事に関連して１点確認させてください。ここの公園には、消防団の資機材の格納庫があったと認識しております。改修に当たっては、その格納庫はどのようになるのか、ご存じでしたら教えてください。","respondent":"大友公園課長","answer":"格納庫については、既存の倉庫を移設する形で考えてあります。出入口付近の利便性の高いところに既存の倉庫を移設してまいりますので、そのまま活用いただく形で考えております。","voiceIndex":116,"id":"exchange-044"},{"speaker":"こんの委員","kind":"質問・要望","question":"移設してくださる、一応、既存の公園内に格納庫は置いてくださるということで、公園が主の改修工事なので、あまり消防団のことばかり要望というわけにはいかないのですが、移設する場所によっては出し入れがなかなか、ここは公園の西側だと思いますが、歩道もそんなに広いわけではないので、格納庫から出した資機材を搬入するとき、車などが入ってくるといったことを考えると。","respondent":"大友公園課長","answer":"西側の道路に接した形の場所になりまして、公園の位置でいきますと、北西の位置に移設してまいります。","voiceIndex":118,"id":"exchange-045"}]},{"id":"topic-06","title":"西大井広場公園（北側）改修等工事","agenda":"西大井広場公園（北側）改修等工事","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"駐輪場なのですけれども、こちらは整備台数の考え方というのはどういう考え方なのかというのをお伺いしたいのと、あと大型自転車とあるのですけれども、これは何を指しているのかを教えてください。","respondent":"大友公園課長","answer":"駐輪場の整備台数についてなのですけれども、まず公園に、駐輪場の整備に至ったというところの経緯からご説明させていただきたいのですけれども、当公園の南側広場は、サッカークラブやグラウンドゴルフの活動、また区民まつりおよび防災イベントの実施など。","voiceIndex":124,"id":"exchange-046"},{"speaker":"安藤委員","kind":"質問","question":"公園の駐輪場というと、一般的にフリーというか料金を取らないところも、限られたスペースではあってもあるのですけれども、ここの駐輪場はそのようになるのか、それとも料金を徴収するというところになるのか、伺いたいと思います。意見聴取のところについては、近隣の住宅４３０戸にアンケートを取ったということで分かりました。質問は、先ほどのところのご答弁をお願いします。","respondent":"原交通安全担当課長","answer":"スペースの関係上、ないところもございますが、普通自転車用のところはラックの使用を予定しておりまして、おおむね４０センチ幅のラックを置いておりますので、こちらのラックに入らない自転車に対しては。","voiceIndex":126,"id":"exchange-047"},{"speaker":"安藤委員","kind":"確認","question":"最初の２時間は無料だということで、公園の利用者にも使ってもらいたいということだと思うのですが、若干、公園の南側の広場を使う方々がこの駐輪場を使うのかというのは、そんなに利便性がいいのかと言われると微妙なところが、利用者目線でいうとあるのかなというところは感じておりますので、公園の利用者の皆さんに。","respondent":"大友公園課長、原交通安全担当課長","answer":"利便性の件につきましてなのですけれども、北側ということで、道路を挟んでの反対側となりますので、南側は今回、改修を行いませんけれども、北側に改修を行って、利用できる駐輪場ができるというところの案内を。現在、建屋につきましては、定期利用が２７４台、当日利用が約１６０台で運用しているところでございますが、こちらは、公園の改修が終わりますと、建屋のほうは全て定期利用で約４００台がとめられる状態にする予定です。","voiceIndex":128,"id":"exchange-048"},{"speaker":"こんの委員","kind":"確認","question":"駐輪場のことを私もお聞きしたいと思います。そういうものをイメージしているのかの確認が１点。そうすると、工事の１日にできる時間帯などがあると思うのですけれども、ここは少し、保育園のお昼寝時間というのは配慮してさしあげたほうがいいのかなと思うのですが、工事はどういうふうに行われるのでしょうか。お願いします。","respondent":"大友公園課長","answer":"続きまして、工事についてなのですけれども、こちらは日中というところで、時間は特に制限はかけていないというところではありますけれども、工事の中で一定、振動が出る工事、音が出る工事というところにつきましては、保育園等々と調整しながら。","voiceIndex":132,"id":"exchange-049"},{"speaker":"こんの委員","kind":"質問・要望","question":"駐輪場について、そうすると、多分、水神公園と同じようなタイプのものがつくのかなといったところで、ありがとうあります。もう少し台数が増えるといいかなという感じもしますけれども、あのタイプは非常に使いやすいのでよろしいかと思います。無事故で安全に工事を行っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":134,"id":"exchange-050"}]},{"id":"topic-07","title":"公園における花火の使用","agenda":"公園における花火の使用","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"実施してみての改善点というのはあったのか、昨年の試験的な取組では、どのような試行結果といいますか、それが得られたと考えていらっしゃるのか伺いたいと思います。","respondent":"大友公園課長","answer":"このような使用状況・利用状況を踏まえまして、公園の管理者がいる公園で実施を継続するというところが必要であると考えたところです。公園の拡大をすると、公園管理者がいないというところで、そのような対応ができなくなるというところで、今回も５公園という形で実施していく。","voiceIndex":139,"id":"exchange-051"},{"speaker":"安藤委員","kind":"質問","question":"そんな中で、昨年の試行の実施の状況など、今ご説明がありましたけれども、昨年の審議では、 公園の管理時間との兼ね合いや、近隣の迷惑を考えて、時間は８時までにしたというお話だったと思うのですけれども、今回９時までにしていただいたというのは、その問題はクリアできたのでしょうかというのをお伺いしたいと思いますし、しながわ区民公園だけ時間が短い理由は何なのかも教えてください。","respondent":"大友公園課長","answer":"こちらを延ばすところの課題といたしましては、やはり騒音や、騒ぐというような音の問題が一番大きいかと思います。そういうところにつきましては、公園管理者がいる公園での実施というところで、 巡回するという対応で課題をクリアできると考えているところです。","voiceIndex":141,"id":"exchange-052"},{"speaker":"安藤委員","kind":"意見","question":"分かりました。いろいろこれからも試行錯誤しながらやっていくことになると思いますけれども、ぜひ今年もやって、 様々なご意見も頂きながら、来年も継続できるように実施していっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":143,"id":"exchange-053"}]},{"id":"topic-08","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"６月２５日の松永議員、新妻議員、６月２６日のこしば議員の地域公共交通についての質問で、品川区は今後、環境の変化等を踏まえ、区民へのアンケートや移動データ等を用いて、区全体の交通ネットワークを総合的に検討していくという旨の答弁だったと思うのですけれども、改めて今後の区全体の公共交通をどうしていく考えなのか伺うと同時に、アンケートとはどのような手法で、いつどのような目的で行うのか。","respondent":"あくつ委員長、櫻木地域交通政策課長","answer":"先ほどの前段の部分については昨日の仕切りのとおりですので、その前提の中で、アンケー トの部分、お答えいただける部分でご答弁いただければと思います。ご答弁をお願いいたします。繰り返しの答弁になりますので、アンケートの部分についてお答えしますと、現在、区全体の公共交通ネットワークを整理する中で実施が想定されるアンケートにつきましては、現時点では概要や時期等は未定です。","voiceIndex":155,"id":"exchange-054"},{"speaker":"安藤委員","kind":"質問","question":"前回もアンケートもやりましたということですが、今回このアンケートをやる目的というのを聞きたいのです。何のためにアンケートをやるのですかというところ。今後、コミュニティバスを増やすという考えがあるのか、バス事業者に対して支援などといったものを行う考えがあるのか、伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":158,"id":"exchange-055"},{"speaker":"安藤委員","kind":"質問","question":"概要や時期というよりも、何のために取るのかという目的について質問をしているのですが、少しはっきりしない答弁なので、もう一度だけお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":161,"id":"exchange-056"}]},{"id":"topic-09","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"出席希望ではないです。希望しないというところで、私たち共産党としては、道路大会というのは趣旨に反対なものですから、参加しないということの意思表示をさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":176,"id":"exchange-057"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.30ke.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":41,"characters":51286,"voices":177}},{"id":"r08-20260630-9","meetingId":"r08-m0708","date":"2026年6月30日","dateIso":"2026-06-30","committee":"文教委員会","time":"午前10時00分～午後１時38分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件抜き出しています。","hasFullText":false,"topics":[{"id":"topic-01","title":"学校改築の進捗","agenda":"学校改築の進捗","exchanges":[{"speaker":"西本委員","kind":"確認","question":"おおむねこの５年ということなのですけれども、城南第二小学校以降、この米印にも書いてありますが、中東問題、これどうなるか分からないという、予測がつかないのですけれども、 それにしても資材高騰はあるでしょう。そうなってくると、校舎の向きが変わったりするのです。それについての説明を近隣住民たちにきちんとしていますかということを確認したいと思います。この２つお願いします。","respondent":"荒木学校施設担当課長","answer":"主に委員からご指摘いただきましたように、音や日陰の問題、 あとは風向きといったところも丁寧に説明いたしまして、要望がございましたらそれぞれ個別に当たるなど、影響範囲、それからその対策についてもしっかりと丁寧に進めていき、可能な限り、学校のつくりに関しても。","voiceIndex":5,"id":"exchange-001"},{"speaker":"西本委員","kind":"確認","question":"工事のほうはもちろんできるだけ短縮ですよね。でも、今の状況を考えると、 短縮には到底なり得ないという思いがあるので、ただ、結局旧校舎を使いながらやってくると、校庭が潰されるという感覚になるので、校庭等での授業についての確保というものは、それぞれできているのですよねということを確認させてください。もうやってしまっていますから。お願いいたします。","respondent":"荒木学校施設担当課長","answer":"現在は三木小学校と大崎中学校の改築困難校の建て替え検討を進めているところではありますけれども、ほかの学校につきましても、今後の就学人口動向の推計や、あとは老朽度、それから地域バランスなどを総合的に勘案した上で、柔軟に改築計画を進めてまいりたいと考えています。","voiceIndex":7,"id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"ですから、これから１８校やるにしても、整備基金というものがあることは分かっているのですが、そこももっと増やしていかなければいけないだろうという思いもあるし、本当に教育に関してのお金の使い方というのか、税金の使い方というか、予算の立て方というものをシフトしていかないと、考え方を改めていかないと、改築できない状況になるのではないかなと私は思うのです。","respondent":"荒木学校施設担当課長","answer":"現在は建て替えをメインで進めてきたわけなのですけれども、今後は、先ほどご提案いただいたような長寿命化計画や長寿命化改修など、新しい手法も何かないかというところも含めて、 検討はしていきたいと考えています。","voiceIndex":9,"id":"exchange-003"},{"speaker":"ゆきた委員","kind":"質問","question":"本年２月の学校プール施設の在り方で、日よけシェードを改築校の標準仕様としていくという方向性が示されたと思います。先ほどの説明で、東海中学校においても日よけのスペースを設けるというお話あったと思います。今回の資料でプール諸室と記載されていますが、ここが冷暖房設備を備えた採暖室も含まれているというように理解してよろしいのかお聞きしたいと思います。","respondent":"荒木学校施設担当課長","answer":"１点目の、プールの日よけシェードですが、 こちら基本設計図面で、なかなかそこまで細かい表現はできていないのですけれども、この資料でいうところの右上の５階平面図、こちらの青く着色してある部分が屋外プールとなりますが、この周囲には大型のひさしを設けて。","voiceIndex":12,"id":"exchange-004"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"２つとも確認できました。近年の猛暑を踏まえて、子どもたち、また教職員が安全・安心に水泳の授業を行えるように、これまで示されてきた検討結果が設計に反映できるように、今後も改築校に活かしていただきたいと思います。こちらは要望で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-005"},{"speaker":"澤田委員","kind":"質問","question":"私からは特別支援学級のことをお伺いしたいのですけれども、現在東海中学校には特別支援学級がないと把握しているのですけれども、今回は新しくできるということで、 浅間台小学校に特別支援学級もありますし、そこに通学している児童の皆さんたちが今後そのように通えていくようになるのかなと思って、大変うれしく思っています。区としての考えをお聞かせいただけますか。","respondent":"荒木学校施設担当課長","answer":"今後詳細なしつらえにつきましては、現在進めている実施設計で検討してまいりたいと思います。もう１点の既存校および既に改築が終わった義務教育学校などに関しましても、今年度も特別支援教室、特別支援学級の拡充を図るために、改修工事などを予定しています。","voiceIndex":16,"id":"exchange-006"},{"speaker":"澤田委員","kind":"意見","question":"広さをしっかり確保していただけるように進めてくださっているということで、安心しました。これからもぜひ、カーミングルームというか、落ち着けるスペースなど、いろいろ配備を進めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":18,"id":"exchange-007"},{"speaker":"高橋（し）委員","kind":"確認","question":"ご説明ありがとうございました。そうすると、前もお話ししましたけれども、学校の敷地の調査のような計画が入っていないと思うので、そうすると三木小学校と大崎中学校をやるまでが、しばらく間が空くのかなということがあるのですが、そこの確認です。これ固定級を５つにするということですから、そのような傾向を今、 先読みしているのかなというところがあるので、そこです。","respondent":"荒木学校施設担当課長、新井特別支援教育担当課長","answer":"鈴ケ森小学校につきましては、一部未契約ではあるのですけれども、１００億円超となる見込みです。やはり年々費用が上がってありますので、建設費の抑制に向けた取組も並行して進めているところです。ただ、関係課とも連携いたしまして、トイレの位置や、あとは敷地の南側に寄りまして、道路に近くなるといったところもありますので、窓から入ってくる音の対応など、そういったところで、知的、情緒。","voiceIndex":20,"id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それぞれありがとうございました。反発されるかもしれませんけれども、でも、そこは何とか教育委員会のほうで周辺の利用団体などに理解していただいて、本当に何か月に１回でもいいから広いところで運動できるような手だてをぜひ、これは要望でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-009"}]},{"id":"topic-02","title":"令和９年度新入学者の受入枠","agenda":"令和９年度新入学者の受入枠","exchanges":[{"speaker":"西本委員","kind":"質問","question":"現状は分かりました。人数も、今年の実績が浅間台小学校２３人、中延小学校１９人なのです。ですから１９人ということは、人数が少ないことはあれですけれども、集団というか、今の教育環境にはとても適しているのかなと思うのです。ですから、上神明小学校、清水台小学校、小山台小学校は３０人程度なので、そこも２クラスぐらいになるといいのかなと思っているのですが。その現状はどうですか。","respondent":"石井学務課長、新井特別支援教育担当課長","answer":"は全体的な傾向としては増えてきているというような認識です。新１年生の特別支援学級のお子さんの数としては８人ということで、特別支援学級を設置されているほかの学校との割合で見ても、一番多い学校になっています。","voiceIndex":28,"id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"学校の小規模か大規模かによっての特徴、それが学校の特徴になっている可能性はあるのです。ですから、そうなってくると、極端な話、そのようなお子さんが多いところは、研究校じゃないけれども、 手厚くするという、特化してしまうという、そのようなことをやってしまってもいいのかなと思っているのです。","respondent":"石井学務課長、新井特別支援教育担当課長","answer":"単純な転出入については押さえていないのですけれども、昨日ご説明いたしました、新入学学校別増減要因一覧の資料で、増要因と減要因にそれぞれ転入、転出というような数字があります。伊藤小学校の件で、例えばこの４月から自閉症・情緒障害の特別支援学級を開設したといったところの、肌感覚になりますけれども、例えば新１年生の場合ですと、保育園、幼稚園の年長のときに、就学相談と言われる。","voiceIndex":31,"id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"少し実態が見えてまいりました。これでいいというわけではないので、いろいろなパターンの中で品川区の教育の特徴のような形まで拡大していく、成長していただければなと思いますので、今後、 そのような意味では研究を深めていただいて、本当に一人ひとりに目の行く教育というものをぜひ目指していただきたいなというように要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-012"},{"speaker":"ゆきた委員","kind":"質問","question":"中学校の３５人学級の取組について、大変意義のある取組だと認識しています。一方で、今年度の学校選択では、地域の保護者の方々から、例年以上に希望校へ進学しにくかった、待機となって最後まで空きが出なかったという声も伺っております。そこで、３５人学級の導入が学校選択にどのような影響を与えたということで認識しているのかお聞きしたいと思います。","respondent":"石井学務課長","answer":"昨日も受入れ、入学率のことについて、実は説明いたしました。令和７年度につきましては６８.１％の方が入学できたところ、令和８年度入学では３６.４％であったと。これはもう明らかに受入可能数の問題であろうと思っています。","voiceIndex":36,"id":"exchange-013"},{"speaker":"ゆきた委員","kind":"質問","question":"保護者にとっては、例年なら入ることができる学校だから大丈夫と考えていても、制度の変更によって状況が変わるということもあると思います。入学の受入れとしては、学校案内や、学校選択の説明において、こうした点についてより丁寧な情報提供をさらに進めていっていただければと思いますが、この点についてお聞きしたいと思います。","respondent":"石井学務課長","answer":"一方で、学校選択制そのものは、まだ選択肢は残っているというような段階で１つ有意義なものだと考えていますので、引き続きこういった中で丁寧な運用をしながら、きちんと説明も行ってまいりたいと考えております。","voiceIndex":38,"id":"exchange-014"}]},{"id":"topic-03","title":"「品川区附属機関の構成員の報酬および費用弁償に関する条例の一部を改正する条例」の概 要","agenda":"「品川区附属機関の構成員の報酬および費用弁償に関する条例の一部を改正する条例」の概 要","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"今回の改正の理由が人材確保と今おっしゃっていたと思うのですけれども、需要が増えているのは分かりますが、実際どのような状況なのでしょうか。これとても大切な委員会で、やはりきちんと仕事をしていただきたいと思いますし、どのような方々をどのような理由で選んでいて、だけれども、その中ではやはり報酬を上げないと確保できなくなっていますということなのか、その現状を教えていただけますか。","respondent":"保土澤教育総合支援センター長","answer":"実際どのような方が委員になっているかというご質問ですけれども、委員長は弁護士の梶智史先生にお願いしており、それ以外の委員も、国立教育政策研究所の名誉所員である学識経験者、弁護士、心理学・福祉をご専門とする大学教授、児童精神科医など。","voiceIndex":45,"id":"exchange-015"},{"speaker":"西本委員","kind":"確認","question":"今厳しいのだというお話、本当にただでさえ専門家が少ない分野なので、確保することは大変だろうなと思うのですけれども、ただ、この改正後の委員長が３万円、委員が ２万３,０００円というものは、競争の中で有効な数字なのですか。これで大丈夫ですかということを確認させてください。","respondent":"保土澤教育総合支援センター長","answer":"ちなみに他自治体の１事例をお伝えしますと、同じような委員をお願いするのに１万９,０００円でお願いしているような自治体もありますけれども、やはり実態を伺うと、お願いはしても今回は無理だというようなことがあったり。","voiceIndex":47,"id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"１万９,０００円や３万円ですから。人材確保というものは。初任給を高くして、人材確保にやっきになっているではないですか。それと同じです。このいじめ対策というものは、非常に大切なことですから。だからその金額も、もうこれにこだわらずに、許せる範囲の中でになるでしょうが、これから高くしてもいいのではないかなと私は思いますけれども、 今後の動向などはどのように考えておられますか。","respondent":"保土澤教育総合支援センター長","answer":"今ご指摘いただいたとおり、我々もこの委員会を非常に重要な機関だというように認識しております。","voiceIndex":49,"id":"exchange-017"},{"speaker":"ゆきた委員","kind":"質問","question":"今回委員の報酬を引き上げる理由として、人材確保と調査体制の維持が挙げられています。一方で、 条例では報酬は日額というようになっていますが、実際にいじめの重大事態が発生した場合、第三者委員会の委員は、１件当たりおおむね何日程度活動することを想定しているのか、どの程度の日数が必要となってくることを想定しているかをお聞きしたいと思います。","respondent":"保土澤教育総合支援センター長","answer":"この日額というものにつきましては、これはあくまでこのいじめ対策委員会にご出席いただいた、その日の金額と。大体１回当たり２時間から３時間で実施をしておりますので、そのときにお支払いをする金額というようになっております。","voiceIndex":52,"id":"exchange-018"},{"speaker":"ゆきた委員","kind":"質問","question":"そうすると、その委員会に出席した時間ということなので、それ以外の、先ほど申し上げました学校への聞き取りや資料作成、報告書作成など、そういった時間は日額のところに入っていないということとなるという認識でよろしいですか。","respondent":"保土澤教育総合支援センター長","answer":"学校への聞き取りをしていただく、児童や教職員への聞き取りをしていただくときに、この二、三時間、やはり時間を要するケースにつきましては、この日額をお支払いして、聞き取りという内容で対策委員会を実施したという形で回数としてカウントをしております。","voiceIndex":54,"id":"exchange-019"},{"speaker":"ゆきた委員","kind":"意見","question":"理解できました。いずれにしても、専門性の高い委員を安定的に確保できるように、先ほどあった弁護士や医師など、そういった体制の維持に努めていただければと思いますので、 お願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":56,"id":"exchange-020"}]},{"id":"topic-04","title":"区立学校におけるいじめの重大事態の発生状況","agenda":"区立学校におけるいじめの重大事態の発生状況","exchanges":[{"speaker":"澤田委員","kind":"質問","question":"これどのような経緯で発覚したのかということを教えていただけますでしょうか。いじめＤアンケートなどいろいろ取っていらっしゃると思うのですけれども、そのようなところからなのか、それとも、例えば先生やスクールカウンセラーの人に相談があった、親からの報告なのかとか、ご相談なのかとか、それを教えていただければと思います。","respondent":"保土澤教育総合支援センター長","answer":"いじめＤアンケートなど、そういったところが見られてというようなことではございません。","voiceIndex":61,"id":"exchange-021"},{"speaker":"澤田委員","kind":"質問","question":"転校のというところで、区としてもいろいろな方法でいじめを早期発見しようという取組を行われている中で、そこでは拾えなかったかということがすごく残念ではあるのですけれども、今、その児童と保護者の方がどうされているのか心配でありますし、いろいろ対応してくださっているとは思うのですが、今どうしていったらいいのかというものを持ち合わせていなくて申し訳ないのですけれども。","respondent":"保土澤教育総合支援センター長","answer":"これまで区として行ってきた経験や、デジタルもそうですし、専門職を、本年度からスクールカウンセラーやスクールソーシャルワーカーと巡回をして、担任の先生に相談する以外でもいろいろな子どもの話を聞くよという大人が近くにいるのだということを安心感に変えながら。","voiceIndex":63,"id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"重大事態ということで認定して、継続中のものが何件あって、解決したものが何件と、実績を教えてほしいのですけれども。教えてください。","respondent":"保土澤教育総合支援センター長","answer":"いじめ重大事態の総数についてお伝えします。令和４年度から令和７年度までの実績になりますけれども、こちらは全部で３５件対応をしております。その中で解消した回数というご質問でしたけれども、全部で２３件解消しています。１２件はまだ調査中です。","voiceIndex":68,"id":"exchange-023"},{"speaker":"西本委員","kind":"確認","question":"１つは、解決した後どのような状況になっているのでしょうか。そのような状況まで行った上での解決策、解決という形になっているのか、 そこを確認させてください。それは一番先にやらなければいけないことなのだけれども、 では加害者となっている児童・生徒についての対応は、教育機関の中でどのぐらいやっているのでしょうか。成果が上がっているのでしょうかというところを教えてください。","respondent":"保土澤教育総合支援センター長","answer":"いじめの解消というものが、１つ転校などといったことではなくて、いじめを認知してから、 その行為がやんで、そのやんだところから３か月間同じようなことがなく、本人も特段いじめに関する相談をしていない、そして周りで見ていても。","voiceIndex":70,"id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"３か月ないから大丈夫と、私はそうは到底思えないのですけれども、 被害者は相当心に傷を負っているのです。足りていないと思います。自分がいじめをやっているなどと思っていないですから。だから難しいのです。もっと危機感というか、気持ちというか、をしっかりフォローする体制というものは必要なのではないですか。３か月間ないからいいというわけではないと思いますけれども、いかがでしょうか。","respondent":"保土澤教育総合支援センター長","answer":"いじめの定義といたしましても、やはり該当の児童・生徒が心身の苦痛を感じていない状態、これが３か月程度という認識ですので、 我々もご指摘のとおり、３か月たったからという、そのような、何というのですか、乱暴な形ではなくて、やはりそのケースごと、また。","voiceIndex":72,"id":"exchange-025"},{"speaker":"西本委員","kind":"意見","question":"もう１点あります。保護者に対しての指導をどうしていますかということです。現場はよくやっていると思います。ただ、保護者はどうなのだろうなと。ただ、異様に敏感になってしまうという可能性もありますので、この両者の、 両側のフォローというものをしっかりやっていかないと、結局子どもにつながってきますので、その辺はどうされていますか。","respondent":"保土澤教育総合支援センター長","answer":"当該の保護者につきましては、これはやはり学校と同じ方向で、当該の子ども、被害であっても加害であっても、必要な指導、それからサポートをしながら対応していくことが必要ですので、基本的には学校は保護者と連絡を取り、そして面談を重ねながら。","voiceIndex":74,"id":"exchange-026"},{"speaker":"西本委員","kind":"質問・要望","question":"いじめが起きたときにいろいろな要因が入ってくるので、いろいろと工夫されてやっておられるのだろう、蓄積もそれなりに出てきているのだろうと思いますので、そこは教育委員会としてしっかりやっていただきたいなと思っています。ですから、保護者の方々に隠さない、当事者だけでは済まず、皆分かっているはずなので。もう一つ言いたかったのですけれども、時間があれなので次回の機会にしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-027"},{"speaker":"ゆきた委員","kind":"確認","question":"今回の事案も含めてなのですけれども、令和７年度は１３件の重大事態が認定されて、多くの案件は現在も調査中ということで、私も区のホームページで確認しました。あわせて、改めて確認ですけれども、通常委員の５人以内で全案件を調査しているのか、専門性が必要な案件だけ臨時委員を追加しているのか、同じ臨時委員が複数案件を担当しているのか、お聞きしたいと思います。","respondent":"保土澤教育総合支援センター長","answer":"臨時委員の取扱いにつきましては、毎回出ていただいている委員の方のご都合がつかなかった、 ちょっとご都合が悪いというときに臨時委員の方にご出席いただいて、必要な人数を確保していじめ対策委員会を進めております。","voiceIndex":78,"id":"exchange-028"},{"speaker":"ゆきた委員","kind":"質問","question":"通常の委員の方４人と、委員長が１名いるということで、そして臨時委員が追加でということですね。長期化することの懸念もあります。案件数の増加や専門性に応じて臨時委員を柔軟に活用していくことというのが今後ますます必要になると思いますが、これについてお考えをお聞きしたいと思います。","respondent":"保土澤教育総合支援センター長","answer":"実際にこのいじめ対策委員会も、先ほどお伝えしたように、学校へ行っての聞き取り調査などを行うときには、人数が一定程度必要になる場面というものは当然出てまいりますので、必要に応じてこの臨時委員の先生方にもお力添えいただきながら。","voiceIndex":80,"id":"exchange-029"},{"speaker":"ゆきた委員","kind":"質問","question":"先ほど報告事項の中でもありましたけれども、委員の人材の確保というものはさらに重要性が増してくると思います。複数案件で補っていくということもあると思いますし、この臨時委員の活用についても、今後の考え方は検討していかなければいけないなと感じていますけれども、 その辺についてお聞きしたいと思います。","respondent":"保土澤教育総合支援センター長","answer":"もちろんこの臨時委員の先生方に入っていただいて、必要な審議が迅速、的確に行われるようにしていくということは大事だと思っていますが、もう一方で、いじめの重大事態を生まない学校のいじめ対応というところを同時に、むしろこちらが本丸かなと考えていますので。","voiceIndex":82,"id":"exchange-030"}]},{"id":"topic-05","title":"「品川区特別支援教育推進計画」の策定","agenda":"「品川区特別支援教育推進計画」の策定","exchanges":[{"speaker":"澤田委員","kind":"質問・要望","question":"委員構成のところで、まず質問をさせていただきたいのですけれども、 その他教育長が必要と認める者というところがあると思うのですが、第１回会議が７月に控えていることを考えると、既にお決まりなのかなというところがあるのですけれども、どのような方が選定されたのか、お聞かせいただければと思います。","respondent":"新井特別支援教育担当課長","answer":"改めて、第１回の開催を経まして、委員の構成等についてきちんと報告をしてまいりたいと考えております。","voiceIndex":88,"id":"exchange-031"},{"speaker":"澤田委員","kind":"質問・要望","question":"もう１点なのですけれども、パブリックコメント、１２月に実施されますが、アンケートではなくてパブリックコメントということなので、広く多くの方の声を聞かせていただけるように実施されると思うのですけれども、全区民からの募集なのか、対象者を教えていただきたいということと、実際に障害をお持ちの子どもを育てていらっしゃる方の声というものはすごく大切かなということと。","respondent":"新井特別支援教育担当課長","answer":"特に私どものほうで現段階で考えているところとしましては、まずはこういった計画をつくっていること、また、 計画に対してご意見を言っていただくような場があることということをこちらのほうで、周知の方法は、 今後保護者の連絡ツール等の検討をいたしまして。","voiceIndex":90,"id":"exchange-032"},{"speaker":"ゆきた委員","kind":"質問","question":"今澤田委員からありました委員の構成のところですけれども、委員の構成は何か条例や規約に基づいて、構成員は１４人以内ということに決められているのか、そこをお聞きします。","respondent":"新井特別支援教育担当課長","answer":"私どものほうで、今回この検討委員会の設置要綱を策定いたしまして、その中で教育長が委嘱する委員１４人以内をもって組織するという形で、根拠にやらせていただいております。","voiceIndex":94,"id":"exchange-033"},{"speaker":"ゆきた委員","kind":"質問","question":"パブリックコメントをやることは全区民にだと思うのですけれども、パブリックコメントをやりますという周知のやり方と、どうアプローチしていくのかということを、改めてですけれども、もう一度お聞きしたいと思います。","respondent":"新井特別支援教育担当課長","answer":"先ほど澤田委員のほうからご提案もありました、いわゆる特別支援学級や特別支援学校に通っていらっしゃる児童の保護者の方々に対しても、周知や、あとは通常の学級にいらっしゃるお子さんの保護者への周知というものも。","voiceIndex":96,"id":"exchange-034"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、やはり当事者を入れてほしい。ただ、これは個別個別で考え方が違うと思うので、できるのだったら、 この障害者団体の代表者というのであれば、そこを集約できる人をぜひお願いしたいと、そのような意識で来てほしい。町会長だったら町会の意見を総じて言っていただきたいわけではないですか。そこを確認したいです。そのようなことについてはどうお考えになりますでしょうか。","respondent":"新井特別支援教育担当課長","answer":"実際に当事者のお声をどう酌み取っていくかというところについてなのですが、これは検討委員会の中で決めていくといったところもあるのですけれども、ほかの自治体では、一部なのですが、特別支援学級に通っているお子さん、しかも低学年、中学年。","voiceIndex":99,"id":"exchange-035"},{"speaker":"西本委員","kind":"質問・要望","question":"共生していくべきだろうと。でも、先ほどその子のニーズに合わせた教育環境とおっしゃっていたと思うのですけれども、これすごい大切で、ではその子のニーズに、その子の状況に合わせた教育は何でしょうかといったときに、もちろんインクルーシブ的な、そのようなものは必要だと思うし、あとは個別の、その子特有の、その状況に合わせた教育というものをするべきだと思うのです。普通級は悪くはないです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":101,"id":"exchange-036"},{"speaker":"高橋（し）委員","kind":"質問","question":"ご説明ありがとうございました。さらにそれを超えて、もうそちらも教育という形で含めているところもあります。学校教育法上の学校ではあるのですけれども、特別支援教育推進計画などから外れているところも中にはあったりするのですが、世田谷区は明確に含んでいて、品川区の場合は同様にしていくのでしょうか。どのように扱っていくかというところをお尋ねします。","respondent":"新井特別支援教育担当課長","answer":"今保健センターで試行実施をしております５歳児健診との関係性のところでいいますと、やはり保護者の方が発達上の課題を早期に認知されて、心的な受容をされることが前提ですけれども、そういった就学相談などを通じて、適切な。","voiceIndex":103,"id":"exchange-037"},{"speaker":"高橋（し）委員","kind":"質問","question":"お尋ねしようと思ったのですけれども、先ほど保育部門も入っているということ、課長も入っていくということでありましたので、そこは安心して、そこを取りいれていただくことは大変ありがたいので、今お話があったように幼稚園、保育園も含めていくということがあって、品川区が就学前教育に関していろいろなことをやっていて、非常に、先ほどの５歳児健診も近々ですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-038"},{"speaker":"山本副委員長","kind":"提案","question":"ご説明ありがとうございました。ご答弁にもありましたけれども、杉並区なども特別指導学級の子どもたちへのアンケートなどをしながら、その声を拾うということをやられていて、これはぜひそういったことを進めて、委員の皆さんにご提案していただいて、そのような機会をつくっていただきたいということがあります。ご意見をいただければと思います。","respondent":"新井特別支援教育担当課長","answer":"委員からご意見、ご質問をいただいておりまして、まず１点目の、いわゆる特別支援教育のお子さんの保護者の方の声というものをぜひ聴いてほしいというところについては、この声の聞き方については、 実施方法をアンケートとするのかといったところについては。","voiceIndex":107,"id":"exchange-039"}]},{"id":"topic-06","title":"「（仮称）品川区こどもの権利条例」の制定","agenda":"「（仮称）品川区こどもの権利条例」の制定","exchanges":[{"speaker":"西本委員","kind":"確認","question":"これから検討していくので、これから中身を議論していければと思いますけれども、少し確認だけしたいです。何歳までが該当するのかなということで、その該当年齢を教えてください。そして、１番の背景および目的というところで、「アンケート調査やこども会議を行う中で」ということがありますけれども、これはどのようなものだったのでしょうか。","respondent":"柴田子ども施策連携担当課長","answer":"それからアンケート、こども会議での意見、どういったことがあったのかという点ですが、 まずアンケートにつきましては、令和７年度から計画実施しておりますこども計画の策定に当たってアンケートを取った際に。","voiceIndex":114,"id":"exchange-040"},{"speaker":"西本委員","kind":"質問","question":"大人は分からないです。ですから、それを踏まえていくと、今いろいろ事業をやっておりますが、それが、この「こどもの権利条例」、これから定めていくわけですけれども、それに相反することになっていく可能性もあるわけです。そこまで私は深く考えてほしいなと思っているのです。令和１０年度に条例制定となるのですけれども、もう少し早くしてほしいなという気持ちがあるのです。","respondent":"柴田子ども施策連携担当課長","answer":"まだ着手したタイミングですので、今後どのような形でということは明確にはお伝えすることはできないのですけれども、策定する段階から、そういった点も意識しながら取り組んでまいりたいと考えています。","voiceIndex":116,"id":"exchange-041"},{"speaker":"西本委員","kind":"提案","question":"１つの提案なのですけれども、自ら話をすることは難しいと思うのです。だから、例えば保育士とか、 幼稚園の先生とか、日々の生活の中で、何か寂しい顔をしていたときに何かあったの、そのときどう思った、どうしたかったなどと聞けるチャンスだと思うのです。保育園や、あとはすまいるスクールなどもそうです。児童センターなど、児童センター職員の方々は、そのようなところがたけていますから。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":118,"id":"exchange-042"},{"speaker":"ゆきた委員","kind":"質問","question":"１点だけ、条例制定に当たって、子育て支援団体にヒアリングとありますが、様々な事情から、自ら声を上げることが難しい子どもの意見、例えばヤングケアラーなどがあると思うのですけれども、具体的にどのようなヒアリングをしていくのか、現時点で分かる範囲でお聞きしたいと思います。","respondent":"柴田子ども施策連携担当課長","answer":"幸いに区の中にはヤングケアラーの支援チームがあったりしますので、ヤングケアラーに聞き取りをするということになりましたらば、そういった方々のお力も借りたいと考えてあります。","voiceIndex":120,"id":"exchange-043"},{"speaker":"ゆきた委員","kind":"提案","question":"提案ではなくて恐縮ですけれども、教育や福祉・医療や関係団体、あと支援団体、幅広く連携していただいて、実効性のある計画づくりになっていただければと思います。これは要望で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":122,"id":"exchange-044"},{"speaker":"高橋（し）委員","kind":"質問","question":"今のご説明の中にもあったのですけれども、条例制定後に、どうやってその権利を、権利侵害などから救済するかということで、機関等の話が書いてあったのですが、ほかの自治体、課長のほうが詳しいと思うのですけれども、様々相談機関というか、救済委員会というか、いろいろなものを条例の中に定めているのですが、それはどのような感じで今イメージしているのかということが１つで。","respondent":"柴田子ども施策連携担当課長","answer":"内容はもちろんなのですけれども、名称を知っているというだけでも、入り口としては大変重要かと思いますので、そういった視点を持って検討してまいります。もちろん子どもからの意見を聞いたり、専門家の意見を聞いたり、様々なところから知見を拝借して進めてまいります。","voiceIndex":124,"id":"exchange-045"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"名称は今お話があったように、分かりやすく皆さんに知ってもらうということで、人権を入れたほうがいいのか、権利という言葉を入れたほうがいいのかということは、委員会でも議論してやっていただければいいと思うのですが、町田市などは「子どもにやさしいまち条例」というようなものがあるので、そのようなものは子どものことを考えているのだということは、条例の名称から見えてくるので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-046"},{"speaker":"山本副委員長","kind":"質問・要望","question":"令和８年３月の予算特別委員会において、私から、区立小中学校、義務教育学校の児童・生徒に対しまして、学習用タブレットを活用して、できるだけ幅広く意見を聞くことを要望いたしました。そこで、現状の取組の範囲で教えていただきたいのですけれども、アンケート調査の準備状況です。どのような形で想定されていらっしゃるのでしょうかということで、何か計画があれば教えていただきたいと思います。","respondent":"柴田子ども施策連携担当課長","answer":"大きく３点ご質問いただきました。初めのアンケートの進め方なのですけれども、今想定しておりますものは、小学校、中学校、義務教育学校に関してはタブレットを活用させていただいて、対象の子どもたち全員から回答が欲しいなということで進めているところです。","voiceIndex":128,"id":"exchange-047"},{"speaker":"山本副委員長","kind":"質問・要望","question":"それで、もう１点お伺いしたいのですけれども、制定に向けた取組の中で、条例の実効性を確保するために書かれていて、権利擁護・救済機関設置に向けた対応というものは先ほどもご質問がありましてといったところで、ぜひこれを進めていただきたいと思うのですが、併せて評価の仕組みについて検討するということの記載があるのですが、この評価の仕組み。","respondent":"柴田子ども施策連携担当課長","answer":"現時点ではまだ固まっていないのですけれども、そういった視点で取り組んでまいります。","voiceIndex":130,"id":"exchange-048"},{"speaker":"山本副委員長","kind":"質問・要望","question":"ありがとうございました。おっしゃられたように、ぜひ子どもの視点で、そして子どもの声をしっかりと受け止めて、正しい評価ができるように進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":132,"id":"exchange-049"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.30bu.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":38,"characters":50343,"voices":142}},{"id":"r08-20260630-5","meetingId":"r08-m0708","date":"2026年6月30日","dateIso":"2026-06-30","committee":"総務委員会","time":"午前10時00分～午前11時42分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件抜き出しています。","hasFullText":false,"topics":[{"id":"topic-01","title":"説明に入ります前に、各所管委員会における審査結果","agenda":"説明に入ります前に、各所管委員会における審査結果","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回の補正の考え方、ポイントがあれば伺いたいと思います。見ていると、大体は東京都や国の補助金が来て拡充するというものが多いと思うのですけれども、預かり保育のところでは東京都が引き上げたということで、区は下げるということになっていますけれども、拡充ではなく区が引き下げることになった理由を伺います。","respondent":"加島財政課長","answer":"今回の第２号補正予算の考え方についてですけれども、委員からもございましたように、国の補助金ですとか都の補助金が当初予算編成後に拡充された部分につきまして、６月補正で新たに特定財源を受け入れ、制度の充実を図っていくものです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"預かり保育のところは、結果的に区民としては変わりがないということになるのか伺いたいです。","respondent":"加島財政課長","answer":"預かり保育とはまた別の話になります。国が引き上げた分を都が引き下げた、同額を引き下げたという形になっておりますので、区民の方がこれまで受けられていた補助が少なくなってしまったとか、そういったことではございません。","voiceIndex":7,"id":"exchange-002"},{"speaker":"須貝委員","kind":"質問・要望","question":"そういう状況に追い込まれているということを区としても私は考えていただきたいと思うのですが、その点についてどのようなご見解を持っていますでしょうか。そういう方たちに少しでも、全部とは言いませんけれども、寄り添うということを考えていただいて、私はこれも都や国にもっと働きかけていただきたいと思うのですが、その辺は区としてどのような働きかけをしているのでしょうか。教えてください。","respondent":"加島財政課長、藤村企画課長","answer":"財源は限られておりますので、施策の重複性ですとか最大限効果を持たせるにはどのようなやり方をしていくかということをこれからも考えてまいりますが。もう１点のほうになりますけれども、病児保育ですとかお子さんの具合が悪くなったときの対応につきまして、そういった財政面、政策面に関しまして、都や国に働きかけるというところですが。","voiceIndex":10,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問・要望","question":"本当に、皆さん大変な時期を迎えられていると思います。厳しい時期だと思います。今までいろいろな考え方があると思うのですが、私は５,０００円でも １万円でも支援すれば、やはりすごく感謝をすると思うし、その方たちももう少し頑張ろうという気持ちになると思うので、その辺はもっと小さな、小規模事業主に寄り添うような施策をこれからしていっていただきたいと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"何を伺いたいかというと、ホルムズ海峡の危機の問題で、ナフサ不足が多分野にわたって影響を及ぼしています。本会議でも若干のやり取りがありましたけれども、そこを伺いたいと思います。次の第３回定例会がある夏明けまでに、またいろいろと状況が変わってくるかと思いますけれども、ぜひこの補正予算でも機敏に対応していくことが求められていると思います。いかがでしょうか。","respondent":"藤村企画課長","answer":"ナフサ不足への対応、今の物価高騰ですとかこういったアメリカとイランの戦争に関する全庁的な支援についてかと思います。","voiceIndex":15,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"窓口としては、地域振興部というお話がありましたけれども、手袋を一つ取っても病院や介護士、歯医者を含めて影響が出始めていると伺いますし、まずはそれぞれの所管が担当している相手の状況をしっかり把握することを、ヒアリングも含めて現状を把握していただきたいと思います。そういう判断がいよいよ迫られているのではないかと思いますけれども、最後に区の見解を伺いたいと思います。","respondent":"藤村企画課長","answer":"融資自体が今は難しいというようなお話がございましたけれども、そういった融資のほうを受けやすいようにということで、保証協会の関連ですとか利子補給のところを詰めているものが都の制度ですので、そちらのほうを活用していくということが今のところの区の考えです。","voiceIndex":17,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ中小企業のところをしっかり目配りしていただきたいと重ねて要望して、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-007"}]},{"id":"topic-02","title":"三木小学校外壁改修その他工事請負契約","agenda":"三木小学校外壁改修その他工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"校舎の外壁改修工事ということでやるのですが、三木小学校はかなり古いと思うのですけれども、今外壁工事をすれば１０年間以上は外壁がきれいなままだと思うのですが、ここは建て直しというようなことはないのですか。結局、やっても２、３年後に建て直しするのですということだったら無駄なような気もするのですが、それを教えてください。もう１点。その辺について、ご見解をお聞かせください。","respondent":"廣瀬経理課長","answer":"改築要望につきましては、当該改修工事の着手後に地域から寄せられたという経緯があります。現時点では、改築着手時期は未定ですので、まずは予定している改修工事を完了し、施設の健全な状態を維持することが重要と考えていると所管から聞いております。","voiceIndex":32,"id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"ということは、請負契約を既にやっているのに、今、報告事項として提示をされたということですか。途中なのに、一応をこういう工事期間がまだありますと。体育館のほうは後から防水改修工事ということですけれども、外壁に関してはきれいだということは既にやっている、終わったということですか。","respondent":"廣瀬経理課長","answer":"工期のほうは、こちらに書かれていますとおり６月から１１月までの工期で、今工事をしているものです。外壁の工事は、ひび割れ等を修繕していくというものです。３か年計画というのは、全体で３か年かかるということで、契約自体は個別のものとなっております。","voiceIndex":34,"id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"すみません、もう１回だけ。課長も見られたと思うのですが、それにしては外壁がかなりきれいに見えましたけれども、違うのでしょうか。私の見解なので、見方でやはり汚いのですと言うならばあれですけれども、もう一度言います。隣は相当ひどいです。所管が違うのでそれはあれですけれども、かなりきれいなのですが、それでもやらざるを得ないということですか。","respondent":"廣瀬経理課長","answer":"３か年工事ということなので、既に修繕が入っている部分はきれいになっていると思います。今回工事するところは、もちろん手が入っていないところで、新たに６月から１１月までかけてやるというものです。隣の西品川保育園については、把握しておりません。","voiceIndex":36,"id":"exchange-010"},{"speaker":"のだて委員","kind":"質問","question":"３か年計画でやっているということなので、今回は校舎西側の外壁だけですけれども、ほかのところは既にこの２年間でやられたということなのかを伺いたいです。","respondent":"廣瀬経理課長","answer":"３か年工事であり、今年度が最終ということですので、今年度で全て完了ということになります。","voiceIndex":40,"id":"exchange-011"},{"speaker":"のだて委員","kind":"質問","question":"分かりました。今回も外壁は工事されるということで、当然雨漏りとかもなくしていくことが必要だと思うのですけれども、そうした中で三木小学校は建て替えの困難校となっていたと思うのです。一応何となくスケジュールが出されたような気がします。そうしたことへの影響は特にないと考えていいのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-012"}]},{"id":"topic-03","title":"令和７年度庁舎使用料等未請求事故","agenda":"令和７年度庁舎使用料等未請求事故","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"原因の２つ目は確認体制が不十分だったということですけれども、担当者自身が１人なのか複数でやっているか私には分かりませんが、今までは特に請求書を送って、入金されて確認をすることが……、 こういう仕事は全く１人でやるということは想像しづらいので、確認体制が不十分だったというのはどういう状況なのか、やはり原因を明らかにするということがまずは大事だと思います。","respondent":"廣瀬経理課長","answer":"過去に同様の事故があったかということですけれども、現在過去３年分につきましては緊急点検を実施しています。現時点で、令和６年度以前に同様の大規模な未請求事故は確認されておりません。引き続き調査を継続いたしまして、万が一発見された場合には速やかにご報告いたします。","voiceIndex":49,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"私もこの分野のプロフェッショナルではないですから、専門的知識があるわけでなく言っているので、３年が妥当だということであればその根拠を説明いただきたいし、でも３年と聞くとそんなものなのかという気もしてしまうので、 そこをご説明いただきたいです。いずれにしても、貸していて賃料を取るわけですから、日頃の業務で目に見えているというか、そこにあるものというか。最後にもう１点。","respondent":"廣瀬経理課長","answer":"再発防止策の実施につきましては、基本的には課内、係内で実施をしてまいります。それぞれ、確認者、係長、庶務、予算担当者でチェック、点検を進めてまいりたいと考えております。","voiceIndex":51,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"決裁を下したのが誰なのか。そこがよく分からなかったので、伺います。それと、内訳のことで、自動販売機だったり、モニターだったり、それを動かす電源だったり、戸籍住民課の前の広告であったりということで、今回は経理課に説明いただいているのですけれども、それぞれの所管が気づくような仕組みにはなっていないのですか。使用料だから経理課のほうでまとめてやるということなのか、伺いたいです。","respondent":"廣瀬経理課長","answer":"委員のおっしゃるとおり、庁舎の使用料は基本的に経理課のほうで庁舎の使用許可を出しているので、この品目についてはほぼほぼ経理課のほうが所管しています。","voiceIndex":53,"id":"exchange-015"},{"speaker":"松本委員","kind":"確認","question":"対策の打ち方について、大事なのは再発防止策のほうだと思っていて、その防止策の１つとして再発防止策（１）の①で、実歳入予算の調定額を当初予算額と比べというところで、調定の作成漏れがないかを確認すると書いていただいています。実際にその１年間で契約があって、そこで初めて請求が見通せるみたいなところがあると思います。この辺りは、これで足りるのでしょうか。お願いいたします。","respondent":"廣瀬経理課長","answer":"前年中に既に契約をしている賃貸のものですとか、もしくは例年庁舎の使用をしているような部分につきましては、ご指摘いただきましたとおり当初予算のほうで全て反映しておりますので、その額と比較してジャストということにはならないのですけれども。","voiceIndex":55,"id":"exchange-016"},{"speaker":"須貝委員","kind":"質問","question":"中塚委員からも出たのですが、私も単純なミスだと思うのですけれども、こういうミスは本当にこれだけだったのかと疑問に思います。うちの会社でもそうですけれども、チェックリストがあればこの請求書を出したで終わってしまって、また翌年度は同じようなリストがあればそこで発送すればいいわけですから、少し不思議なような気がします。それについて、今の私の疑問に対して、ご意見を聞かせてください。","respondent":"廣瀬経理課長","answer":"ほかにはないのかというところですが、先ほどご回答したように現在点検を行っています。現時点では、確認されてはおりません。実際に昨年度につきましては、同じ担当者が同じ処理をきちんと行っていて、無事に請求されているです。","voiceIndex":58,"id":"exchange-017"},{"speaker":"須貝委員","kind":"確認","question":"ただ、今後に関しては、恐らく経理課でもこうすればすぐ改善できるだろうという、そういうことはもう考えられていると思うので、前年度、前々年度、それについても何年か調べていただいて、 何も問題がなかったらなかったで確認をして、また報告をしていただければいいのかと思います。事なきを得てよかった結果なのか、後で報告していただければありがたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-018"},{"speaker":"松本委員","kind":"質問","question":"だったら、例えば調整処理をいつやるのか存じ上げないですけれども、月末に各担当が調定処理をするということであれば、月末の調整処理を各所職員が忘れていないかを上長がチェックするということもイメージしやすいのですけれども、どちらでしょうか。この辺りはどうなのでしょうか。","respondent":"廣瀬経理課長","answer":"一応、こちらに記載されているは担当者の調定処理のうちの一部です。光熱費などは毎月発生するようなものもありますので、請求できているものとできていないものが混在していたという状況です。","voiceIndex":61,"id":"exchange-019"},{"speaker":"松本委員","kind":"質問","question":"分かりました。そうすると、またどうしようかというところもあるのですが。もう１つ。担当者と書かれていますが、１名の方なのですか。それとも複数名の方なのですか。どちらでしょうか。","respondent":"廣瀬経理課長","answer":"１名の者が担当しております。","voiceIndex":63,"id":"exchange-020"},{"speaker":"松本委員","kind":"確認","question":"ここまで申し上げたので、あとは多分経理課のほうで対策を考えていただいて、ただ、同じようなことが起こる可能性はどこでもあるので、これは経理課でのところですけれども、ほかの課でも同様のミスはないかというところをこの機会に確認していただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-021"},{"speaker":"のだて委員","kind":"質問・要望","question":"それぞれの委員の方がおっしゃっていましたけれども、再発防止をしっかりとやっていただきたいと思います。今日が末ということで、ほぼ納入されているのかを確認させていただきたいです。やはり、いろいろ仕事を抱えると忘れてしまうことはあると思うのですけれども、そうしたことがない仕事量にしていくということも一つ重要なのかと思うのですが、いかがでしょうか。","respondent":"廣瀬経理課長","answer":"それと、失念していたということに関する事務分担につきましては、既に事務分担の見直しは行っているところでございまして、本人に過度の負荷がかからないような形で今年度の事務の分担を進めてまいりたいと考えております。","voiceIndex":66,"id":"exchange-022"},{"speaker":"つる副委員長","kind":"確認","question":"各委員の質疑で確認できたところと、改めてというところがあるのですが、全体で４科目１１件ということで、先ほど質疑でそれぞれのどういったものかというところは具体的な詳細も若干説明があった中で、分かったことが出納閉鎖でということだと思います。そもそも、まず同月のものの処理として今回失念となっているのか、それとも複数月にまたいでいるいわゆる失念であったのかを教えてください。","respondent":"廣瀬経理課長","answer":"本件は様々案件が交ざっているのですけれども、同月ではなく複数にわたっているものです。","voiceIndex":69,"id":"exchange-023"},{"speaker":"つる副委員長","kind":"質問","question":"複数ということで、そうするとそれはそれで別にそうですかと言って忘れてしまうことはありますと先ほどの質疑の中であったわけですけれども、それは当然あり得るという話はありましたが、当然お金に関することは特にきちんとやっていかなければいけない。ご担当者が非常に絞られた中でのという業務の話もありましたので、今後の対応、再発防止策をしっかりそこをやっていただくというところだとは思います。","respondent":"廣瀬経理課長","answer":"調定処理自体は品川区会計事務規則に定められているものと認識しております。","voiceIndex":71,"id":"exchange-024"},{"speaker":"つる副委員長","kind":"確認","question":"納入する義務者、要するに支払う側は債務者と言うのですか。会計管理室ですよね。そうすると、今回の４科目１１件の内容からすると、突発的に一時的に発生したような請求ではないということで、例年ないし例月ないし、定期的な支払であるというところからすると、そのチェック機能というところでは、経過だけではない部分でのチェックというのはできないものですか、できるものですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-025"},{"speaker":"つる副委員長","kind":"質問","question":"大きい話の流れは分かりました。会社として支払わなければいけないではないかと。そういうようなチェックと言うのですか、これは再発防止策の大きいくくりの中で入っているかもしれませんけれども、対債務者の事業者とのそういったやり取りの中のコミュニケーションと言いましょうか。そこら辺は今後どうやっていくのか教えてください。","respondent":"廣瀬経理課長","answer":"それに伴い、再発防止策にも取り組んで参るのですけれども、今後各事業者とも連絡等々を重ねながら、お互いの中で請求の支払い漏れがないようにはしてまいりたいと考えております。","voiceIndex":76,"id":"exchange-026"},{"speaker":"須貝委員","kind":"意見","question":"うちのときにもそうですけれども、請求書が来ないときは普通請求書が届いてないのですけれどもと、 うちの会社の場合には相手方に必ず連絡をするようにしています。やはり、我々は信用でやっていますので、相手が大手だろうが小さいところだろうが、長年そういうふうにきちんと払っているならば、やはり僕は一言経理課にあってほしかったと希望的に申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":78,"id":"exchange-027"},{"speaker":"中塚委員","kind":"確認","question":"１点だけ。庁舎使用料ということで、自動販売機だという説明が先ほどあったのですけれども、今思ったのは公園にも自動販売機はありますよね。公園課のほうで使用料を取っているのかと思います。そこだけ最後に確認させてください。","respondent":"廣瀬経理課長","answer":"全庁的なところということですけれども、今回は会計管理者と企画部のほうで連名で全庁的な注意喚起は行っているところでございまして、各課で同じような確認体制は各課の体制によってですが、含まれているものと考えております。","voiceIndex":79,"id":"exchange-028"}]},{"id":"topic-04","title":"ありがとうございます。 それでは、正副委員長でまとめさせていただきます。 次に、⑶その他","agenda":"ありがとうございます。 それでは、正副委員長でまとめさせていただきます。 次に、⑶その他","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"一言だけ。今、よく各自治体から返金があります、多く徴収したので返します。その詐欺バージョンが今流行っているので、そこは相手方に対して少し配慮をして、間違いなく品川区だとわかるように。どういうふうに証明したらいいか分からないけれども、今は電話がかかってきたり封書が来たりして、 返金しますと言ってＡＴＭに行ってくださいなんてことにはならないように、よろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":94,"id":"exchange-029"},{"speaker":"つる副委員長","kind":"意見","question":"今、委員長がおっしゃったところで、各委員、同じ思いがあると思います。なので、 この辺のいわゆる区としての公表的なところのタイミングも、これは非常にセンシティブかもしれませんが、悩ましいと思うのです。還付しますとなって、それに乗じていいチャンスだと、まき餌みたいになってしまうという可能性にも注意しながら、７月の報告を待ちたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":96,"id":"exchange-030"},{"speaker":"松本委員","kind":"質問","question":"これまでは職員の人事記録に関する規則の第２条というところで、人事記録の個人情報を保有する根拠がここにあったかと思うのですけれども、これを提供する場合には新たに規定を設けるということかと思うのですが、今回の問題になった事案とは別に、全ての職員に対して多分ここの提供する場合の取扱いというのは適用されるものが新たにつくられたと思うので、これは具体的にどのような新しい基準というか。","respondent":"横田人事課長","answer":"派遣時に提供可能な保有個人情報ですとか、要配慮個人情報の提供には本人同意を有するなどを規定いたしました。","voiceIndex":100,"id":"exchange-031"},{"speaker":"松本委員","kind":"質問","question":"これは、定めてしまえば多分それで大丈夫なものだと思います。派遣した先のほうの取扱いについて、どういうふうに行政としては対応いただいていますか。派遣するときに、こちらが派遣先でも規則を定めてくださいなど、いろいろと伝え方はあると思うのですけれども、現状そこはどうなっているのですか。","respondent":"横田人事課長","answer":"細かくはまだ派遣先と調整できているところではないのですが、一応今後の取扱いといたしまして、 区が提供された情報について利用目的外の利用を禁止するとか適正な管理と保護、そういったことをうたって先方にもご理解いただくように努めてまいります。","voiceIndex":102,"id":"exchange-032"},{"speaker":"松本委員","kind":"意見","question":"こういうことが出てしまうと、いろいろなところから責められたりし得るかと思うのですが、先ほど申し上げたように、これについてはほかの自治体で調べてもなかなかこういうことが起こっているという情報を見つけられなくて、今回の公益通報をきっかけにある意味法に照らした対応ができたというところで、ネガティブにではなく今後よりプラスになるような配慮としていろいろと考えていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":104,"id":"exchange-033"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.06.30so.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":27,"characters":31953,"voices":106}},{"id":"r08-20260701-21","meetingId":"r08-2t","date":"2026年7月1日","dateIso":"2026-07-01","committee":"子ども若者支援・共生社会推進特別委員会","time":"午前10時00分～午前11時26分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"子ども若者支援・共生社会推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件抜き出しています。","hasFullText":false,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"せお委員","kind":"確認","question":"確認なのですけれども、３番の利用認定申請数です。そう記憶しているのですけれども、今は利用パターンが特定の事業所を定期的に利用となっていて、実施方法も余裕活用型は空き定員の枠を活用してとなってくると、例えばある園では、後半は使えませんという話になると思ったのですけれども、そういう実態はどうなのでしょうか。聞かせてください。","respondent":"佐藤保育事業担当課長","answer":"現時点におきましては、今回この事業を実施しようとしている５７施設でいくと、ゼロ歳から２歳児に関して２００名ほど定員の空きがありますので、現在は対応することが十分に可能と考えております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"せお委員","kind":"意見","question":"誰でも通園制度のニーズも増えてくるだろうけれども、先ほどの説明が中途半端ですみません。はこれで終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":7,"id":"exchange-002"},{"speaker":"澤田委員","kind":"質問","question":"今のせお委員の質問に関連していなのですけれども、申込みは今電子で行われていて、申請する際に利用する園を固定、ここを利用したいとやっていらっしゃると思うのですけれども、今の話のように、 年度末で空きがなくなってきたときに、第２希望園、第３希望園など、例えば今使いたいと言っている園以外にもあれば、そこは年度末になっていっぱいになってしまったとしても。","respondent":"佐藤保育事業担当課長","answer":"今ご質問いただきました第２、第３希望園を選ぶことが可能なのかにつきましては、可能というように対応させていただいてあります。","voiceIndex":8,"id":"exchange-003"},{"speaker":"澤田委員","kind":"質問","question":"勉強不足で分かっていなかったのですけれども、あともう一点気になったのが、第２、第３でいろいろ選択できるということですが、保育士が常駐していらっしゃるけれども、１歳児は保育士１人で５人、 ２歳児は６人、３歳児は１５人を見られる中で、どれくらい前からそれが決まっていて、確保とかは大丈夫なのか、気になったので、教えてください。","respondent":"佐藤保育事業担当課長","answer":"保育士の体制整備についてです。こちらは運営形態が一般型と余裕活用型という形態がございます。一般型の場合は、もう枠を固定して運用する形になっておりますので、その枠に対応した保育士が各園に配備されているものです。","voiceIndex":10,"id":"exchange-004"},{"speaker":"澤田委員","kind":"確認","question":"確保できているということで安心しました。最後ですけれども、どのようにこれを周知しているのかも確認させてください。","respondent":"佐藤保育事業担当課長","answer":"周知の方法についてです。今年５月頃に特別な広報誌を作成させていただきました。そういった周知でありますとか、子育てアプリといったものでの周知、ホームページでの周知などを行って、 幅広く皆様に知っていただきたいと考えております。","voiceIndex":12,"id":"exchange-005"},{"speaker":"澤田委員","kind":"質問","question":"子育てアプリもしっかり活用してくださって、うれしいと思っています。ほかにも子育て関係のイベントですとか、出産を控えている方とか、これからの子たちに対してもしっかりと周知していただけるとうれしいと思いますが、いかがでしょうか。","respondent":"佐藤保育事業担当課長","answer":"今様々なご助言をいただきまして、出産を控えた方へのアプローチはまだ足りなかったと思いましたので、そうしたご助言を活用させていただきながら対応していきたいと思っています。","voiceIndex":14,"id":"exchange-006"},{"speaker":"おぎの委員","kind":"質問","question":"先ほど第２希望、第３希望まで受け入れていただけるというお話もありましたが、実際は自分の家に一番近いところから想定して希望されている部分があると考えています。こちらの地域別の施設数の表、数字だけ見ますと、地域によって数字に大分偏りがあるような気はしているのですが、この辺りは、 ニーズに対してばらつきとかはどのような感じなのでしょうか。","respondent":"佐藤保育事業担当課長","answer":"そもそもこの地域は園数が足りない、 偏りがあるところが、誰でも通園においても偏りがある原因というところはあるのですけれども、東大井・八潮地区が少ないので、ここにある園には今後も継続して積極的なアプローチを行っていきたいと思っています。","voiceIndex":16,"id":"exchange-007"},{"speaker":"おぎの委員","kind":"質問・要望","question":"もしここに預けて気に入ったとなれば、それ以降、２歳児以降もまたお願いする形になると思います。お母さんたちの生活、あと園児の数を見ながら進めていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-008"},{"speaker":"つる委員","kind":"質問","question":"モデル事業を含めると４年目になると思うのですけれども、これまでの３年間と今年度の２か月の状況を見て、当然実施件数は全然違うし、乳児も違う、保護者も年々変わるわけですが、ご意見やご感想など、モデル業を含めて改善点として今年度とか、大きな特徴、変遷をまず教えてください。","respondent":"佐藤保育事業担当課長","answer":"保護者の方の感想、お気持ちとしても、試行的事業を通じてアンケート実施などを行っていて、この事業がお子さんの成長にとっても非常に良い影響があるとか、ご自分の時間を持つことができて非常に助かっているなどのお声をいただいていて。","voiceIndex":19,"id":"exchange-009"},{"speaker":"つる委員","kind":"確認","question":"数字的な確認で、３年前、４年前、２０２３年の段階で、数字の推移は、増減は微増微減というのが年度であると思うのですが、品川区の制度的な部分では満３歳に対して年度末までという数字が入るので、若干のずれはあるかもしれないのですが、在宅で子育てしている中でのゼロから２歳児は、 在宅子育ての９割ぐらいの人数のイメージだと思っています。","respondent":"佐藤保育事業担当課長","answer":"こども誰でも通園制度を実施するに当たりまして、利用者の数等を推測しますと、これはゼロ歳６か月から利用できますので、ゼロ歳６か月から２歳児までで保育施設等を利用されていない方が大体 ３,０００名程度、そのうちこの制度を利用される方が２０％程度と推測して。","voiceIndex":21,"id":"exchange-010"},{"speaker":"つる委員","kind":"意見","question":"事業の目標的な部分でいくと、申請数は比較的多くいただいているイメージという捉え方、あとこの事業に関連して、残りの２,４００人については、今実態としてどういう把握があるのか、 要はこの誰でも通園は、当時は定期的預かりモデル事業という名称でスタートしたときのそもそも論が、 孤独に子育てをする家庭、特に母親を中心とする産後鬱とか、育児の鬱。","respondent":"佐藤保育事業担当課長","answer":"こうした取組もずっと行ってありますので、継続していきたいと考えております。","voiceIndex":25,"id":"exchange-011"},{"speaker":"つる委員","kind":"質問・要望","question":"それと先に、さっきおぎの委員からもありましたが、事業者のご都合もあるので、悩ましい部分はどうしてもあると思うのですけれども、区全体で見たときに、それぞれの地区の偏在はあるにしても、誰でも通園で受け入れるのは大体何メートルに１園とか、児童センターだったら８００メートルに１つで、 ベビーカーで何となく行ける距離感が設置のあれだと思うのですけれども、今どういう状況なのでしょうか。","respondent":"佐藤保育事業担当課長","answer":"しかし、今後保護者のニーズを注視していく中で、施設をより増やしていく必要性がある場合には、 様々な事業者へのお声がけ、または公立の施設での開始なども含めまして、幅広く検討していく必要性があると考えております。","voiceIndex":27,"id":"exchange-012"},{"speaker":"つる委員","kind":"意見","question":"次は、表でいくと、４の利用実績、先ほど質疑などでもちらっと触れられていましたが、平均で見て、 助成があるのが上限３０時間です。裏面の４の４月、５月それぞれ、例えば２歳も、利用回数が約３回と見ても、１５時間とか１７時間で、１歳で見ると、３回で見ると１回６時間というイメージです。月３０時間だから、もう少し余裕があって使えますというイメージですよね。","respondent":"佐藤保育事業担当課長","answer":"上限時間についてです。これも昨年度まで実施してきた試行的事業での平均の利用時間などを参考に設定しているものです。委員がお話しいただきましたように、１日６時間、５回のような形で利用される方を想定したものです。","voiceIndex":29,"id":"exchange-013"},{"speaker":"つる委員","kind":"意見","question":"運営関係も聞こうと思ったのですが、先に今回品川区として独自で、国が１０時間という部分を ３０時間と出ていますよね。４時間、月３０時間、これは私がきちっと読んで理解していないのですけれども、事項別明細には、区が都補助を活用して月４８時間まで拡大し、実施とあるのはどちらが正しいのでしたか。プレス発表ですとか、今日の資料も含めて、３０時間になっています。どちらが正しいのか。","respondent":"佐藤保育事業担当課長","answer":"申し訳ございません。事項別明細については、今手元に資料がございませんので、把握していないのですけれども、３０時間の上限で実施させていただいてあります。","voiceIndex":31,"id":"exchange-014"},{"speaker":"つる委員","kind":"意見","question":"これはほかの事業ではないと、何回か見たのです。それで今３０時間という話で、ここはどうでしょう。","respondent":"佐藤保育事業担当課長","answer":"大変申し訳ございません。改めて確認させていただきたいのですけれども、３０時間が正しいというものです。","voiceIndex":33,"id":"exchange-015"},{"speaker":"つる委員","kind":"質問","question":"最後、運営関係ですけれども、これだけ拡大していただいて、モデル事業のときには事業者からも様々なお声をいただいているというのも、各委員もあったと記憶しております。実績見合いで切られて精算されるのか、それともしっかりと定員分が支払われているのか、要するに確保しなければいけない、アイドリングしていかなければいけないと思うのですけれども、どうなっているのですか。","respondent":"佐藤保育事業担当課長","answer":"国の制度では、基本的には利用実績に応じた補助額、公定価格での支払いになっているのですが、区は東京都の補助を活用いたしまして、人員確保が必要である背景を鑑みまして、月額で一定額を実施していただいて、お預かりしていただいたという実績がある事業者に対しましては。","voiceIndex":35,"id":"exchange-016"},{"speaker":"松本委員","kind":"質問","question":"今のところ、つる委員からの質疑に続いてです。公定価格があって、それに加えて、利用実績に応じて園にお金を出されているということかと思います。一応前日までのキャンセルとか当日のキャンセルについて、利用料等の発生はなしとされているので、基本的には利用されている方のペナルティーは、利用時間が消費されてしまうというレベルのものと思います。これはどうなのでしょうか。","respondent":"佐藤保育事業担当課長","answer":"申し訳ございません。今手元に詳細の資料がないのですけれども、まず、利用実績がない場合のお支払いは実施していないのですけれども、１点、時間で急なキャンセルの場合はお支払いするというものがあったと認識しています。","voiceIndex":37,"id":"exchange-017"},{"speaker":"松本委員","kind":"質問","question":"そうすると、仮に前日までのキャンセル、どこかのタイミングまでのキャンセルであれば、施設に対してお金が払われないのであれば、前日までのキャンセルが増えれば増えるほど、施設としては、本来はそこに需要があるほかの方に来てもらって、施設としても、その分を区からしっかりとお金をいただけるという部分の機会を失ってしまう、売上げが下がってしまう状況もあり得ると思うのですけれども。","respondent":"佐藤保育事業担当課長","answer":"現在２か月の事業実施に当たって、そうしたご質問等を法人の方からいただいたことはない認識ですが、今お話しいただきましたように、確かに機会損失でありましたり、モラルハザードの部分は、可能性としては十分あり得るところがあります。","voiceIndex":39,"id":"exchange-018"},{"speaker":"松本委員","kind":"確認","question":"この辺の段階で、柔軟利用と定期利用というのが、一応国では当初想定されていると思うのですけれども、改めて当区の場合、柔軟事業ではなくて定期利用を原則とした理由をお伺いできればと思うのと、原則という言葉がついているので、例外も一応あり得るとは思うのですけれども、 ここはいかがでしょうか。","respondent":"佐藤保育事業担当課長","answer":"一応原則という書きぶりですけれども、例外を想定したものがないのですが、例えば見守り家庭ですとか、リスクの高いご家庭の方がいろいろなところをご利用したいという要望があった際には、柔軟に対応していかなければならないと考えております。","voiceIndex":41,"id":"exchange-019"},{"speaker":"松本委員","kind":"確認","question":"もう本当に始まったばかりの制度なので、どういうニーズがあるのかは、これからだと思います。次に、利用時間です。例えばホームページに載っているところでも、受入れ可能時間が９時から４時になっていたり、その記載がなかったりするところもあるので、このあたりの受入れ可能時間はどういう縛りになっているのか、ここは何かルールがあるのでしょうか。","respondent":"佐藤保育事業担当課長","answer":"１日ごとの実施時間についてです。区から特に規制や縛り等は設けてございません。実際に運用される保育園の皆様の運用形態、また職員配置など、そういった様々な状況の中で設定していただいている状況です。","voiceIndex":43,"id":"exchange-020"},{"speaker":"松本委員","kind":"確認","question":"対象外であるためにここから進めなくて、その後の保育制度の中身が見られないので、あくまでホームページ上で確認している範囲ですが、逆にマイナポータルでは受入園が出てきて、そこにこの時間ですというものがあれば、それでも足りてはいると思うのですけれども、もしそうでないのであれば、このホームページ上に各園の受入れ時間も記載しておいていただけると、保護者の方たちの参考になると思うのですが。","respondent":"佐藤保育事業担当課長","answer":"実際の保護者の方の声をいただいて、大変ありがたいと思ってあります。ホームページ上で、一覧で見やすいのは非常に重要なことですので、いただいたご助言を活用しながら、区として対応できることがどういったものなのか改めて検討していきたいと考えています。","voiceIndex":45,"id":"exchange-021"},{"speaker":"松本委員","kind":"提案","question":"柔軟に対応していただけると保護者の方たちもすごくありがたいと思います。もう一点、保護者の方たちの不満を伺っていると、品川区は子どもが生まれた後にいろいろな制度があってすごく助かるのだけれども、文字情報がたくさんあるので、全部を読み込むのはなかなか大変というお話をよく伺います。これは最後に提案をさせていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-022"},{"speaker":"せお委員","kind":"意見","question":"皆さんの意見を聞いていて、先ほどおぎの委員から、少しお試しで使いたい方も多いだろうという話があって、そこでそうだと思いながら思い出したのですけれども、障害があるお子さんはどれぐらいいらっしゃるのか、対応はその障害によりますけれども、その園児に対して１人つけなければいけない場合もあると思うのです。そういった対応はどうなっているのかをお聞かせください。","respondent":"佐藤保育事業担当課長","answer":"現在区は特殊な対応が必要なお子さんを預かりいただいた際に、そのお子さん専任でつく職員を雇用した際の人件費の補助を行ってあります。本制度につきましても、 事業者の方からそういったお問合せがありましたら、柔軟に対応していきたいと考えています。","voiceIndex":48,"id":"exchange-023"},{"speaker":"せお委員","kind":"質問","question":"今日は担当がいないのであれですけれども、これも昨年度の子ども若者支援・共生社会推進特別委員会で、幼稚園・保育園の在り方、今後の方向性で、いろいろな理由があるのですけれども、こども誰でも通園制度の実施状況とかも見ながら検討していく話があって、答えられる範囲でいいのですけれども、今回この数値を見ていると、増えてきていると思うので、保育園・幼稚園、特に幼稚園は。","respondent":"佐藤保育事業担当課長","answer":"この数値自体は、もしかしたら増えていくのかもしれないということです。そうするとそのニーズに応えるだけの供給は必要となるのだろうと、保育園・幼稚園の在り方を検討していく上で影響のあるものと考えています。","voiceIndex":50,"id":"exchange-024"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"今までの委員の質疑の中で確認させていただいたことがあるのですが、改めて東京都、国の制度を活用してのこども誰でも通園制度を、品川区がさらに上乗せして実施されていることも含めて、品川区が誰でも通園制度を行う目的を教えてください。それと、もし差し支えなければ、８月に新たに２施設が開園ですが、どの地域でどの園なのかを公表いただけるのであれば教えていただきたいと思います。","respondent":"佐藤保育事業担当課長","answer":"こうしたニーズに応えていくことが目的と考えています。続いて、８月より新たに実施予定の２施設です。１つが鈴ヶ森めばえ幼稚園でございまして、 地域としては、東大井・八潮地区になります。","voiceIndex":52,"id":"exchange-025"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"保育園・幼稚園に様々な支援があるわけですが、１つは切れ目のない支援が本当に大事だと思っています。それと、助けを求めたい方の支援がある場というのが行政の大事なところと思っていますので、 こういう場があるのは非常にありがたいと思います。５９施設になった暁には、そういうのも少し入れていただくといいと思いますので、 ぜひそれは要望させていただきたいと思います。いかがでしょうか。","respondent":"佐藤保育事業担当課長","answer":"今年度につきましても、こうした取組はしっかりと継続していきたいと考えています。使える施設のマップについてです。今、実は用意しておりまして、今後速やかにホームペー ジ上にマップを掲示していきたいと考えています。","voiceIndex":54,"id":"exchange-026"},{"speaker":"新妻副委員長","kind":"質問","question":"今ご答弁いただいた中で、そういう方が２０名ぐらいいらっしゃったということで、そういう方が具体的に支援につながったことはよかったと思いますが、潜在的にそういうご家庭があるという視点を忘れずに、引き続きまたお願いしたいと思います。そういう視点から見ると、地域偏在が少し気になります。なぜここが少ないのかと、区が事業者側にどうしてできないのかという把握はされているのでしょうか。","respondent":"佐藤保育事業担当課長","answer":"区といたしましても、 この数を課題として認識しておりますので、この地域にあります園にしっかりと声がけをさせていただきまして、こうした偏りを少しでも解消できるような取組は引き続き実施していきたいと考えております。","voiceIndex":56,"id":"exchange-027"},{"speaker":"新妻副委員長","kind":"質問","question":"最後に１点だけ、オアシスルームとの関連についてお聞きしたいのですけれども、オアシスルームも、 お子様を預ける場所でありますが、ここは５００円という有料の施設になっています。誰でも通園を使える園の開設によって、オアシスルームの利用者が減ったとか、そこの利用者の使い分けをどうされているのかお聞きしたいと思います。","respondent":"佐藤保育事業担当課長","answer":"オアシスルームと誰でも通園制度は、目的や利用形態等が確かに一定程度重複する部分はあると考えていますが、オアシスルームは、より生活の支援ということ、一時保育のような使い方で、必要になったときに、より柔軟に使えるような制度で、誰でも通園制度は。","voiceIndex":58,"id":"exchange-028"},{"speaker":"つる委員","kind":"質問・要望","question":"さっき言い忘れて、項番１の（６）の一般型の括弧内にある在園児と合同でやっているところと専用室について数字で求めていないかもしれない。","respondent":"佐藤保育事業担当課長","answer":"一般型の在園児合同型と専用室独立型の分けです。在園児合同型が６施設、専用室を設けているのが２施設、合わせて合計８施設となっております。","voiceIndex":61,"id":"exchange-029"},{"speaker":"つる委員","kind":"質問","question":"項番１の（４）のさっきの３００円ですが、区内の施設については、区は利用者からお金を取らずに無償、これが区です。結果、区についてはかからないとなるのですよね。その支払いの精算方法はどうなっているのでしょうか。","respondent":"佐藤保育事業担当課長","answer":"ですので、区民の方が利用されるときも、一旦お支払いをしていただきまして、後に品川区に対して補助金の申請をしていただくと、そちらの費用をお支払いするような内容となっております。","voiceIndex":63,"id":"exchange-030"},{"speaker":"つる委員","kind":"質問","question":"流れは分かりました。その上で、この特別委員会の場で期待の部分も申し上げたいと、最終結論はそこなのです。３００円で徴収、利用者負担額無償化の単価を２７５円で計算しているのですけれども、 消費税を１０％としたら、３０２円となるから、どうなのか、そこが分からなかったので、２７５円設定が分からないので教えてください。もう一回質問します。","respondent":"佐藤保育事業担当課長","answer":"そうしますと、時間数が８時間なのか６時間なのかによって、いろいろと単価が変わってきてしまいますので、国としては３００円程度という言い方をされておりまして、予算書等では一応８時間で割った２７５円で計算させていただいているものです。","voiceIndex":65,"id":"exchange-031"},{"speaker":"つる委員","kind":"質問","question":"勉強になりました。項番３に関連して、先ほど、せお委員からもありましたけれども、これまでの３か年度も含めて、多胎児世帯の利用とか、いろいろな障害種別があろうと思うのですけれども、実際の利用実績とか、今年度２か月の状況を、登録だけの方もいらっしゃるかもしれませんが、教えてください。","respondent":"佐藤保育事業担当課長","answer":"多胎児の方のご利用などの実績につきましては、大変申し訳ありません。手元にデータがなくて、どのような利用実態になっているかは把握してございません。","voiceIndex":67,"id":"exchange-032"},{"speaker":"つる委員","kind":"質問","question":"その部分での今後の可能性なのですが、本格的な全国実施は本年度からですが、 品川区は３年間のモデル実施の実績があるので、そうしたことを踏まえて、実態と照らし合わせて、多胎児の対応、それから障害児の対応のアジャストはどんな印象があるのか教えてください。","respondent":"佐藤保育事業担当課長","answer":"国の制度におきましては、今そのような特別な時間設定はないので、現時点におきましては、区としても検討はしていないですけれども、今後制度を実施していくに当たりまして、様々な声をしっかりと拾っていかなければと考えています。","voiceIndex":69,"id":"exchange-033"},{"speaker":"つる委員","kind":"質問","question":"なので、先ほどの事項別明細で、４８時間を３０時間にしているので、所管の思いと最終的な、 ３０時間だろうという十何時間の余裕が、また思いがあるのか、そこを次年度に生かせるという期待もあったものですから、あえて特別委員会の場で言わせていただきました。積極的な事業を期待したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-034"}]},{"id":"topic-02","title":"議会閉会中継続審査調査事項","agenda":"議会閉会中継続審査調査事項","exchanges":[{"speaker":"せお委員","kind":"質問","question":"先ほど冒頭でご案内があった今後の調査日程について質問する機会がなかったので、この場合、前回お話があったひとり親支援は、結局入ってくるのかこないのかというところです。議会運営委員会でも書いてくださっているのですけれども、ここには入っていなかったと思うので、そこら辺がどうなったのか教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-035"},{"speaker":"つる委員","kind":"質問","question":"関連となると、当然全体の年間の予定を出してくる。ただ、例えば今日の質疑の中で関連して、誰でも通園の利用者の中にひとり親の方はどのようになっていて、その方への支援はどうなのですかと質疑したときには、所管の課長がいらっしゃらなかったら、答えられませんということは、常に残りの委員会全て所管の課長に出席をお願いするという理解でいいのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-036"},{"speaker":"つる委員","kind":"確認","question":"そのときに質問の機会があったわけなので、関連ということであれば、関連した質疑しかできなくなる。だから、いろいろな経過を経て示されている日程とは理解していますので、それを事前に事務局とか、 理事者を含めて、明確に確認して、調査困難だと、さにあらず、関連ならということなのであれば、その際に明確に見解として述べるべきだったと、これはあえて申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-037"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.07.01kw.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":20,"characters":24253,"voices":85}},{"id":"r08-20260701-20","meetingId":"r08-2t","date":"2026年7月1日","dateIso":"2026-07-01","committee":"ＳＤＧｓ推進・行財政改革特別委員会","time":"午前10時00分～午後０時05分","status":"校正原稿・正式会議録ではない","sourceType":"draft","overview":"ＳＤＧｓ推進・行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","hasFullText":false,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"このデジタルプラットフォームを幾つか確認、教えていただきたいのですが、デジタルプラットフォームを活用した区民による行政評価というのは、これはプレス発表等の中でどのようにご説明をされたのか。目玉事業の一つだったのかもしれませんが、ご説明を受けたいというのが１つ。改善とか、そういったものに結びつけるような前向きな、そういった意見を引き出せるような質問設定を行う。","respondent":"井添政策推進担当課長","answer":"今回のデジタルプラットフォームを活用した区民による行政評価、プレス発表等での具体的に説明をしてきた経緯ですが、プレス発表で特段、このデジタルプラットフォームを活用した区民による行政評価について頭出しをしてはおりませんが。","voiceIndex":5,"id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問・要望","question":"一つ確認させていただいたのは、今日がこの事業の頭出しだということ、 詳細の頭出しであると。そういったところは配慮しないという、そういう設問の設定になるのか、もしくは品川区としてこれをやるべきではないとか、そういったところが先ほど、前提ではないというお話がありましたけれども、フラットに区民が意見を言えるようなプラットフォームになるのかどうか、確認をさせていただきたい。","respondent":"井添政策推進担当課長","answer":"この５１８万２,０００円の内訳といたしましては、委員からもご紹介がございましたように行政評価委員の評価委員会の委員の方の謝礼、それからこちら、区民意見を募集したり、行政評価委員会を実施していく中で業務支援の委託を入れておりまして。","voiceIndex":7,"id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ありがとうございました。さっき、私、後出しというような強い言い方をしましたが、それはすみません、私の言いすぎだったのかもしれません。これからやる事業ですから、 前向きに品川区の事業改善につながるような形での今後の選定の在り方についてもぜひご検討いただきたいということをお伝えいただきたいのですが、いかがでしょうか。","respondent":"井添政策推進担当課長","answer":"委員からご指摘いただきましたような、今後、行政評価委員会、事前協議、それから区民意見を募集した後に２回実施してまいりますが、本委員会で皆様からいただいたご意見を各委員の方にもお伝えできるように今回と、あとは行政評価委員会、１０月に実施する前にも９月の段階で。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私、いろいろよく分からないことが多くて。それから、もう一つ、評価スケジュールのところで８月に区民意見募集というところに書かれているのですけれども、パブリックコメントとかだったら大体１か月ぐらいというふうなことの期間でされることが多いと思うのですけれども、これも８月いっぱい、１か月間の期間に意見を寄せてもらうということになっていくのか、その点についても伺いたいと思います。","respondent":"井添政策推進担当課長","answer":"こちらにつきましてはパブリックコメント等も参考にして一月は確保したいというところなのですけれども、まだ検討中の段階ではありますが、準備等になるべく早めに準備が整えれば、７月末とか、９月の頭までとか。","voiceIndex":13,"id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問・要望","question":"この登録者が１００名というのはすごく少ないなという思いがするのです。そこら辺のところというのは、もっと多くの区民の皆さんに、区民が意見を出せるよという、そういう形でぜひしていただきたいなと思うのですけれども、その点を伺いたいと思います。","respondent":"井添政策推進担当課長","answer":"ただ、おっしゃるようにコメントなどを投稿するときには、 アカウント登録が必要になってまいりまして、一定のハードルがあるかと思いますので、そちらは戦略広報課やデジタル推進課などとも連携しながら。","voiceIndex":15,"id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうプラットフォーム、デジタルプラットフォームを活用した区民による行政評価を行いますよというのは、しなトークのホームページで詳しくは見てくださいみたいなところも含めてなのかもしれないのですけれども、こういうふうなことをやりますよというのは広報ではお知らせいただいて、しなトークのほうのホームページに詳しくは掲載するというふうなところで。","respondent":"井添政策推進担当課長","answer":"できるだけ多くの方にご参加いただけるような工夫をしてまいりたいと考えております。しなトークでアカウント登録の登録者を増やす工夫についても関係各連携しながら検討してまいりたいと考えております。","voiceIndex":17,"id":"exchange-006"},{"speaker":"まつざわ委員","kind":"質問","question":"お話、分かりました。ちょっと聞きたいのは、デジタルプラットフォームを活用した行政評価というのは、しなトークだけではなくて、アンケートとか、ああいうのも含めてやっているものなのですか。ああ、この評価についてです。申し訳ない。今回のこの５項目ですね。","respondent":"井添政策推進担当課長","answer":"この５事業につきましては当然、これまでも実施してまいりました事務事業評価でも引き続き内部の評価というものは今年度も実施する予定です。","voiceIndex":21,"id":"exchange-007"},{"speaker":"まつざわ委員","kind":"質問","question":"だから、多いって思えない中で、例えば、この５事業をこれを見直しを左右する、こういう、何というのですか、あまり多くとは言えない意見に左右に反映されるというのはどうなのかなというのがあります。だから、ハイブリッドな意見聴取基盤というのはぜひつくるべきではないかなと思っているので、それを教えてください。少なくとも結局する必要があるのかなと私は思うのですけれども、そこを教えてください。","respondent":"井添政策推進担当課長","answer":"私どももデジタルプラットフォーム、昨年度、令和６年度も試行で実施したりもしておりましたが、 投稿数につきましては課題だというふうに捉えておりまして、そこを打開する一つの策として先ほどご紹介させていただきましたアンケート、こちらはアカウント登録なし。","voiceIndex":23,"id":"exchange-008"},{"speaker":"まつざわ委員","kind":"質問","question":"試行的な意味合いだということなので今後、いろいろ検討していただけたらと思います。今、お答えがなかったのですけれども、スクラップ基準、削減と廃止というのはしないではなくて、それも検討していくべきかなと思っているので、引き続き教えてください。それと同じでＤ Ｘもなのですけれども、ＤＸの利用回数というのか。","respondent":"井添政策推進担当課長","answer":"こちらも現状まだ、そちら、一定の基準など、 統一したものは用意しておりませんが、今後、行政評価委員会の有識者のご意見等も踏まえながら、どういった観点で次年度の予算ですとか、今後の政策に反映していくかということは検討してまいりたいと考えております。","voiceIndex":25,"id":"exchange-009"},{"speaker":"えのした委員","kind":"意見","question":"というのは、これからどう周知していくかというところもあるのでしょうけれども、先ほど、周知はＳ ＮＳ等、いろいろおっしゃっていましたけれども、これは期間がもう８月というふうに区民意見募集はなっていますが、この対象の５事業がちょうどそこの８月までに実際あるのであれば、この事業と一緒に、たしかこれ、期間中、７月、今週の日曜日だったかな、七夕の五反田で何か事業をやるかと思うので。","respondent":"井添政策推進担当課長","answer":"本評価対象事業以外のところでも例えば、地域で所管課が実施するイベント等でもこのしながわオープントークからの行政評価といったところのチラシを配布することができないかといったところは所管と今現在調整をしていますので。","voiceIndex":27,"id":"exchange-010"},{"speaker":"えのした委員","kind":"意見","question":"アンケートも先ほどあった選択式ですとか、取り入れて、身近で、よく私もいろいろアンケートはメールでも来ますけれども、例えば、１分以内で終わりますとか、３分以内とか、そういった表記を踏まえて記載しているとか、また、これは予算にもよりますけれども、なんちゃらノベルティですとか、なかなかポイントというのは難しいとは思うのですけれども。","respondent":"井添政策推進担当課長","answer":"今年度は予算上の関係もございましてノベルティについてはなかなか実現が難しいところではありますが、実績等踏まえて次年度以降のそういったノベルティなども含めて次年度以降の対応については検討してまいりたいと思います。","voiceIndex":29,"id":"exchange-011"},{"speaker":"こんの委員","kind":"質問","question":"皆さんから課題と思われているこの事業をもっとよりよくしていくためにどうしたらいいですかという事業評価をいただくというのが本来の在り方なのかなと私はそう思っているのですけれども、そうなると、次年度からもう少し区民の生活、福祉的なところだとかといったところに視点を当てた評価をいただくという、プラットフォーム、広く皆さんから意見をいただくのであれば。","respondent":"井添政策推進担当課長","answer":"今回につきましてはいずれも現在、３か年やってまいりました事務事業評価シートの結果等も踏まえて、区のほうでは課題があったり、見直しのタイミングにあったり、このタイミングで区民の意見・評価が特に有益と判断した、優先順位をつけて判断したものですが。","voiceIndex":31,"id":"exchange-012"},{"speaker":"こんの委員","kind":"質問・要望","question":"それがご自分たち、皆さんの生活によりよく使われていく税金といった考え方からすると、区民の方が今生活の中でこんなこと、 あんなこと、こんなことに困っているというところに行政が対応しているという、そういう事業になってほしいというのが区民の願いだと思いますので、ぜひ次年度以降、何か手法を、そういった区民の方から聞いたものを、事前に選定していくのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-013"},{"speaker":"山本委員","kind":"提案","question":"私も２年前の一般質問、そして去年の一般質問でも要望をご提案させていただきまして、しなトークは記述式で意見を書けるというメリットがある一方で、なかなか多くの人たちに参加してもらいにくいというところで、会員に意見が示せる選択式のアンケートを幅広くやっていくことがいいのではないかということでご要望してきましたけれども、今回、ご答弁の中でこのしなトークだけではなくて。","respondent":"井添政策推進担当課長","answer":"１点目の選定基準や事業の選定の部分につきましては、委員おっしゃるように区民にとって関心の高い事業を選定するというような視点も重要だというふうに認識しておりますので、次年度以降、 そういった視点も含めて検討してまいりたいというふうに考えております。","voiceIndex":34,"id":"exchange-014"},{"speaker":"山本委員","kind":"質問・要望","question":"目標件数１００件というのはこれ、結構意欲的な数字だなと思います。各項目１００件、意見を集めるということでぜひ周知をしていただいて、広く意見が集まるようにしていただきたいと思います。多くの区民の皆様の声を正しく、そしていい区政につながるよう、変えていくというのはとても大事なことだと考えていますので、この取組に期待しておりますので、どうぞよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-015"},{"speaker":"鈴木委員","kind":"質問","question":"議事録については公開されるということなので、やはりこれがいろいろな区民の今後の政策にも関わってくるということなので、議事録が公開されるのであれば、委員会も公開してもいいかなというふうに思うのですけれども、議事録が公開されるにもかかわらず、委員会が公開されないというののその理由というのは何かあるのでしょうか。","respondent":"井添政策推進担当課長","answer":"会議録、記録については要旨を公開するとともに、また、３月に区のホームページで今評価の結果についても公表していく中でその行政評価委員会で受けた意見等もそちらできちんと区民の方に分かりやすく公表していくということも合わせて考えてまいりたいと考えております。","voiceIndex":40,"id":"exchange-016"},{"speaker":"鈴木委員","kind":"質問・要望","question":"議事録は公開されるということですので、忌憚のない意見というのは公開されていたら忌憚のない意見にならないかということには、私はならないのではないかなと思いますので、ぜひともこれは公開の方向も含めてご検討いただけたらというふうに、要望をさせていただきたいと思います。","respondent":"西澤ＤＸ戦略担当部長、與那嶺デジタル推進課長","answer":"令和８年度も東京都の事業である障害者向け・高齢者向けスマートフォン普及啓発事業との連携も継続して推進してまいります。続いてスライド７ページをご覧ください。私からは次のページ、スライド９ページ目以降をご説明します。ＡＩや生成ＡＩの業務への利活用推進についてです。","voiceIndex":42,"id":"exchange-017"},{"speaker":"山本委員","kind":"質問・要望","question":"ご説明、ありがとうございました。幾つか質問させていただきたいと思いますが、まず、全体の話をお伺いしたいと思います。それで、合わせてこの３つの、全体の３つの区分、それから１２項目の中で順調に進んでいる区分、 項目と想定よりもうまく進んでいない区分、項目の色分けでその理由と、課題があればその課題とその修正の取組について、全体からお伺いしたいと思います。","respondent":"西澤ＤＸ戦略担当部長","answer":"シゴトＤＸに関しては、昨年、Ｍｉｃｒｏｓｏｆｔ ３６５の導入だったりとか、先ほど説明しましたＡＩを活用といったところが進んでおりまして、こちらに関しても徐々に徐々に進んでいるかなと思っています。","voiceIndex":47,"id":"exchange-018"},{"speaker":"山本委員","kind":"質問・要望","question":"これ、過去議会でもこういったテーマでやると、若者の意見でスマホとか使っているから、意見が集まりやすいのではないかとか、こういう形で要望がたしかこういうテーマでやってみたというところだと思うのですけれども、 ちょっと防災区民憲章の投稿件数に比べると少ないなというところと思っておりまして、これをやってみての投稿件数を含めての結果に対する受け止め等教えていただきたいと。","respondent":"與那嶺デジタル推進課長","answer":"実際に教室の埋まり方自体も、これ、ちょっと所管で知っている限りではあるのですけれども、８割程度の参加率というところもあると聞いてございますので、やはりまだまだニーズはあるのかなというふうには我々認識していますし。","voiceIndex":49,"id":"exchange-019"},{"speaker":"山本委員","kind":"提案","question":"ご提案します。例示いただいているこの電子申請サービスを活用した申請業務のデジタル化とか、一つの課であったことだと思うのですけれども、これは庁内横展開できることだと思っていまして、一つの担当課で課題があることはほかの課でもその問題があったり、それを解決につなげることができると思うのですけれども、この６１件の相談事項というのは庁内でご共有ってされているのでしょうか。","respondent":"西澤ＤＸ戦略担当部長","answer":"１点目のＤＸ相談窓口の内容が庁内で共有されているかという点についてになりますが、こちらについては庁内報だったりとかというところで、スライド形式にしてもらって、その取組、課題だとか、デジタル活用で出た効果だとか。","voiceIndex":51,"id":"exchange-020"},{"speaker":"山本委員","kind":"質問・要望","question":"ご説明、ありがとうございました。最後に項番１２の「ＥＢＰＭの推進」のところなのですけれども、ここがちょっと前回、昨年度の発表に比べてそこまで大きく進んでいないような印象を受けるのですけれども、このＥＢＰＭの推進のところについて、現状をどう捉えていらっしゃるかというのを教えてください。","respondent":"西澤ＤＸ戦略担当部長","answer":"データアナリストの方にも入っていただいて、ここにも書いてありますけれども、地図× データワークショップなんかも実施しながら、まず課題をどう認識するかというところが重要と思いますので。","voiceIndex":53,"id":"exchange-021"},{"speaker":"山本委員","kind":"質問・要望","question":"案件発掘ということで１５名の方に参加していただいてそれぞれ使えることをお教えして、これから伴走支援が始まるということで、ぜひ個別の支援をして課題解決につなげていただきたいと思います。ＤＸって各所管と連携して横串を通して、それぞれの効果を高めるすごく大事な役割だと思いますので、それぞれぜひうまく連携していただきながら効果を上げるということで進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-022"},{"speaker":"こんの委員","kind":"質問","question":"大きく２点伺いたいと思います。業務改善というここの角度です。このより効率的に仕事をしていただくためにデジタルツールを活用して業務改善、これは非常に大事なことだというふうに思っております。一方で、業務改善の中にはいわゆるミスを減らしていく、リスクヘッジしていく、こうしたことの体制も必要ではないかというふうに思っております。１点、この点についてお伺いしたいと思います。","respondent":"西澤ＤＸ戦略担当部長","answer":"もちろんデジタルデバイド対策というところもやっていきますが、電子申請というところの普及を進めていくことが重要かなと考えております。","voiceIndex":57,"id":"exchange-023"},{"speaker":"こんの委員","kind":"質問","question":"いわゆる電子申請、時代の流れからいってもこれは必要なことだと思うので、あれなのですが、いわゆるミスを減らしていくためのデジタル、いわゆる電子の中で業務の中でもうちょっと改善できなかったのかな、改善していくことが必要なのではないですかということを申し上げたので、うまく伝わっていなかったと思うのですけれども、決して業務改善の効率にＤＸが必要ではないと言っているのではなくて。","respondent":"西澤ＤＸ戦略担当部長、與那嶺デジタル推進課長","answer":"そういったところも含めて検討、推進していきたいというふうに思っております。今回、ご報告した資料の中では１１スライド目の右側の黄色くなっている子ども子育て支援、就学援助、健康管理、こちらの３システムが品川区では特定移行支援システムとなってございまして、それ以外の１５業務については現在。","voiceIndex":59,"id":"exchange-024"},{"speaker":"こんの委員","kind":"意見","question":"標準化の意味がよく分かりました。共通したものを使わないと、やっぱり国へ報告など、また連携などというところが難しいのでそれを使っていくということですが、今、課長がおっしゃったように将来的にお願いしたいので、それぞれの所管でこのばらばらになっているシステムから個人情報を見るのにこっちのシステムを見て、次はこっちのシステムを見てってしていると、どうしてもミスが起きやすい。","respondent":"西澤ＤＸ戦略担当部長","answer":"今回は、システムの標準化でこういった連携の基盤ができたので、ここからさらに活用していく、より区民に利便性が高くする、あとはミスがないようにといったところを今後続けていくところになりまして、こちらが結構長い時間がかかるかもしれないですけれども。","voiceIndex":64,"id":"exchange-025"},{"speaker":"あくつ委員","kind":"質問","question":"ちょっと教えてください。６ページの枠の右側に書いてある東京都高齢者向けスマートフォン普及啓発事業実施予定で、この令和７年から連携開始というところの連携開始の意味をまず教えてください。","respondent":"與那嶺デジタル推進課長","answer":"ご質問いただいた東京都高齢者向けスマートフォン普及啓発事業については、東京都のほうが都民の高齢者向けにスマートフォンの啓発事業を行っているというところで、品川区も会場として使っていただいてという形の連携です。","voiceIndex":68,"id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問","question":"大体高齢の方がやっている。ここにスマホよろず相談のことの記載があって３３４人とあるのですけれども、こうしたスマホの購入費助成、もし利用される方が３万円というところで出てくるといった場合に、品川区としてはそういった誰ひとり取り残さないという具体的な施策として今後、今やっていること以上の何かそういった受皿を用意するのかどうか、その辺りを教えてください。","respondent":"與那嶺デジタル推進課長","answer":"こちら、各キャリアショップで購入する際にそこのキャリアショップで行うスマート教室を受講して、そこで申請まで行うという形の支援も合わせて実施しているところです。","voiceIndex":70,"id":"exchange-027"},{"speaker":"あくつ委員","kind":"質問","question":"板橋区なんかも週に３回ぐらいですか、そういったいわゆるシルバーセンターのようなところで名前は、名称は違いますけれども、そういったところでよろず相談的なものを行っている。これは申し訳ないのですけれども、誰ひとり取り残さないというところから見ると、私的には不十分ではないかなと思うのですけれども、そこについて庁内検討はしたのか、されなかったのか教えてください。","respondent":"與那嶺デジタル推進課長","answer":"各サービスの中でサポートの仕方も様々あろうかと認識してございまして、少し今取り組んでいる中でありますと、例えば、先ほどもちょっとご質問の中にもありました電気・ガス料金支援事業などについては、こちらも電子申請が使えますので、地域センターであるとか。","voiceIndex":72,"id":"exchange-028"},{"speaker":"あくつ委員","kind":"質問・要望","question":"やはりそういったところでの品川区としてもこうした独自の支援事業、物価高騰対策をやる、それもしかもデジタルを１００％活用してということ。そういった、もしデジタル１００％を目指すということであるならば、１００％を目指すとは言っていませんけれども、誰ひとり取り残さないということはそういったサポート体制というのをやはりしっかり品川区として責任を持って確認していく。","respondent":"與那嶺デジタル推進課長","answer":"地域センターでのサポートについては、まず、しながわ電気・ガス料金緊急支援事業については、こちらサポート窓口として開設する予定です。","voiceIndex":74,"id":"exchange-029"},{"speaker":"あくつ委員","kind":"質問・要望","question":"いろいろと前向きにご検討、庁内でしていただいていることも確認できましたので、様々な職員のご負担等も考慮の上、ぜひ前向きに進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-030"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それが１点です。ということは、４割ぐらいが進んでいるとは感じていないということなのか、そうなると結構多くの人が進んでいると感じていないのかなというふうに思うのですけれども、 それは区としてはどういうふうに捉えていて、理由がどういうことでなぜなのかというふうなところについても伺えたらと思います。その点、お願いします。","respondent":"與那嶺デジタル推進課長、西澤ＤＸ戦略担当部長","answer":"私からはデジタルプラットフォームと情報セキュリティについてのご質問にお答えさせていただきます。デジタルプラットフォームの実績件数の投稿数に対しての、じゃ、実際、誰が何人みたいな形のところの数字は申し訳ございません。この中でこのポイントが少ないのではないかということに関しては、我々としても高い目標を持っておりまして、５分の３.５以上を目指しているところもありますので、去年、昨年、Ｍｉｃｒｏｓｏｆｔ ３６５の導入だったりとか。","voiceIndex":77,"id":"exchange-031"},{"speaker":"鈴木委員","kind":"質問・要望","question":"分かりました。それは運営経費がこれから増えていくのは自治体としても大変なので、国として国にこの経費もしっかりと財政措置を行ってほしいという要望書を出した。そこら辺のところの２３区区長会の要望だったり、品川区のコスト面での状況ということについて伺えたらと思います。","respondent":"與那嶺デジタル推進課長","answer":"２３区の状況としてもそこは認識同じでございまして、我々品川区としてもコストはそれにかかっているよねというところは思っておりますし、それは今後も国に対して実際のコストの軽減であるとか、 国からのサポートというところは必要だというところは主張していく次第です。","voiceIndex":80,"id":"exchange-032"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そうすると、３割削減できるというふうな見込みだったにもかかわらず、区としてはどれぐらいコストが増えているのか。国のほうもそういう要望がいろいろなところから出されていると思いますが、令和８年度に関しては国のほうとしても対策がどう取られているのかという辺りもお聞かせいただけたらと思います。","respondent":"與那嶺デジタル推進課長","answer":"国からの支援ですけれども、こちら、いわゆる標準化に当たって、国費の補助金の下に移行していくというところはありましたので、そういった形の支援は入っておりますし、これ、特定移行支援システムに位置づけられたことによって本来であれば。","voiceIndex":82,"id":"exchange-033"},{"speaker":"鈴木委員","kind":"質問・要望","question":"その標準仕様を導入するというふうなことと、それから導入した後、運営をしていくというそのランニングコストについても多分その前に比べたら、かなりコストが増えるというふうなところで、こういう要望がされているのかなと思うのですけれども、そのことに対しても国のほうに国の施策でこれは進めていることなので。","respondent":"與那嶺デジタル推進課長","answer":"委員ご指摘のとおりでございまして、まず、そもそも国から補助金が出ていたのが、標準化システムの開発に関しての経費については国費が出るという形であったのですけれども、運用コストのほうも増大していくということも踏まえまして。","voiceIndex":84,"id":"exchange-034"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひ国のほうにしっかりと出してもらえるようにということでこれからも求めていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-035"}]}],"links":[{"type":"minutesDraft","label":"公式の校正原稿PDFを読む","url":"https://gikai.city.shinagawa.tokyo.jp/wp-content/themes/shinagawakugikai/pdf/2026.07.01sd.pdf"},{"type":"official","label":"公式の会議録一覧","url":"https://gikai.city.shinagawa.tokyo.jp/search"}],"sourceMeta":{"pages":31,"characters":43492,"voices":90}}]);
